// ---------------------------------------------------------------------------
// zundamon transform (deterministic) — shared by main.js and tools/*
// ---------------------------------------------------------------------------
// 文末を機械的にずんだもん語尾へ変換する純粋関数。
// 上から順に最初にマッチした語尾だけを置換する（順序が重要）。
// 置換結果が元と同じルール（例 [/て$/, "て"]）は
// 「ここで打ち切ってこの文は変換しない」という意味の番人ルール。

// ---------------------------------------------------------------------------
// 動詞の活用表
// ---------------------------------------------------------------------------
// 丁寧形（〜ます／〜ません／〜ました）を常体に戻すには、直前の連用形から
// 活用の種類を決めなければならないのだ。ところが連用形の表層は五段と上一段で
// まったく同じなのだ。「書き」も「起き」も い段で、文字だけ見て区別することは
// 原理的にできないのだ。
//   書きません → 書かないのだ（五段：未然形は あ段）
//   起きません → 起きないのだ（上一段：未然形は連用形と同形）
// そこで五段動詞を語彙で数え上げて振り分けるのだ。
// 五段はほぼ閉じた類で、新語が入るのはラ行（「ググる」「事故る」）だけなので、
// 頻出語を数百並べれば実用上は覆えるのだ。表に無い語は上一段の読みに落とす。
// 上一段の読みは連用形の仮名をそのまま残して語尾を足すだけなので、外しても
// 語そのものは壊れない（「歩きないのだ」）のに対し、五段の読みを外すと語幹まで
// 書き換わって語が消えてしまう（「できません」→「でかないのだ」）。
// どちらかを外すなら、壊し方が小さいほうを既定にするのだ。
//
// い段の仮名ごとの、五段の 終止形（う段）・未然形（あ段）・音便形＋過去
const GODAN_ROW = {
  い: { u: "う", a: "わ", onbin: "っ", past: "た" }, // ワ行 買う → 買わない・買った
  き: { u: "く", a: "か", onbin: "い", past: "た" }, // カ行 書く → 書かない・書いた
  ぎ: { u: "ぐ", a: "が", onbin: "い", past: "だ" }, // ガ行 泳ぐ → 泳がない・泳いだ
  し: { u: "す", a: "さ", onbin: "し", past: "た" }, // サ行 話す → 話さない・話した（音便なし）
  ち: { u: "つ", a: "た", onbin: "っ", past: "た" }, // タ行 待つ → 待たない・待った
  に: { u: "ぬ", a: "な", onbin: "ん", past: "だ" }, // ナ行 死ぬ → 死なない・死んだ
  び: { u: "ぶ", a: "ば", onbin: "ん", past: "だ" }, // バ行 呼ぶ → 呼ばない・呼んだ
  み: { u: "む", a: "ま", onbin: "ん", past: "だ" }, // マ行 飲む → 飲まない・飲んだ
  り: { u: "る", a: "ら", onbin: "っ", past: "た" }, // ラ行 帰る → 帰らない・帰った
};

// 五段動詞の語幹表（連用形のい段の直前まで）。行ごとに並べるのだ。
// 未然形（〜ません）も音便形（〜ました）もこの同じ表から引けるのだ
const GODAN_STEMS = {
  // カ行五段。「行く」だけはイ音便でなく促音便なので下で別に扱う。
  // 「起き」「生き」「飽き」「尽き」は上一段なので入れないのだ
  き: [
    "行", "逝", "書", "描", "聞", "訊", "効", "利", "歩", "働", "動", "開", "空",
    "置", "泣", "鳴", "吹", "拭", "巻", "撒", "咲", "敷", "引", "弾", "履", "掃",
    "就", "付", "突", "着", "抜", "焼", "磨", "招", "嘆", "傾", "響", "輝", "続",
    "届", "解", "説", "導", "築", "呟", "頷", "覗", "除", "抱", "焚", "剥", "驚",
    "欺", "貫", "退", "湧", "沸", "裂", "頂", "戴", "省", "捌", "浮", "叩", "吐",
    "溶", "囁", "拓", "轢",
    // テ形の直後の「おき」は補助動詞「おく」なのだ（「置いておきます」
    // 「言っておきました」）。仮名書きの「〜ておく」を漢字の「置」では拾えない
    "てお", "でお",
    "近づ", "近付", "気づ", "気付", "基づ", "傷つ", "息づ", "片付", "落ち着",
    "思いつ", "思い付", "追いつ", "飛びつ", "噛みつ", "ばら撒", "取り除",
    // 「い」は仮名書きの「行く」なのだ（「ついていきます」「見に行きました」）
    "い", "ひ", "つ", "いただ", "うなず", "つぶや", "ささや", "ひらめ", "はたら",
    "ある", "つづ", "みが", "うご",
    // 「とく（解く・説く・溶く）」もカ行五段なのだ。
    // 補助動詞「〜ておく」の口語縮約「〜とく」も同じ活用で、上の「てお」「でお」を
    // 縮めた形なのだ（「引きこもっとくね」＝「引きこもっておくね」）
    "と",
  ],
  // ガ行五段。「過ぎ」は上一段なので入れないのだ
  ぎ: [
    "泳", "急", "稼", "繋", "塞", "防", "注", "仰", "嗅", "研", "漕", "削", "継",
    "騒", "脱", "担", "剥", "嫁", "凌", "紡", "扇", "薙", "跨", "揺ら", "和ら",
    "つな", "ふさ", "そそ", "しの", "かせ", "いそ", "およ", "さわ", "また",
  ],
  // サ行五段。「〜します」の「し」はサ変（「勉強し」）と五段サ行（「渡し」）の
  // どちらでもありうるのだ。終止形は「する」と「す」、未然形は「し」と「さ」で
  // 違うので、取り違えると「渡するのだ」「渡しないのだ」という非文になる。
  // 「直前が漢字1字ならサ行五段」という形の条件では分けられないのだ。
  // 「損し」「得し」「対し」「熱し」「面し」「訳し」「お茶し」がどれもサ変だからなのだ。
  // サ変は「する」がどんな名詞にも付く開いた類なので数え上げられないが、
  // サ行五段は新語が作られない閉じた類なので列挙しきれるのだ
  し: [
    // 漢字1字＋「す」。「話」は体言と同形なので下の STEM_GUARD で番人を付けるのだ
    "話",
    "出", "返", "消", "渡", "探", "捜", "直", "治", "貸", "押", "足", "指",
    "差", "刺", "挿", "干", "増", "移", "写", "映", "表", "現", "記", "示", "試",
    "通", "残", "回", "許", "汚", "越", "超", "壊", "隠", "殺", "潰", "崩", "戻",
    "志", "催", "乱", "帰", "侵", "犯", "冒", "託", "促", "癒", "離", "放", "騙",
    "浸", "醸", "申", "致", "外", "零", "託",
    // 送り仮名を伴う和語
    "起こ", "動か", "生か", "明か", "暮ら", "散らか", "飛ば", "伸ば", "延ば",
    "逃が", "焦が", "転が", "冷や", "増や", "減ら", "慣ら", "鳴ら", "照ら", "散ら",
    "落と", "費や", "燃や", "生や", "冷ま", "覚ま", "済ま", "澄ま", "荒ら", "溶か",
    "沸か", "乾か", "働か", "驚か", "泣か", "笑わ", "迷わ", "惑わ", "悩ま", "及ぼ",
    "滅ぼ", "喜ば", "尽く", "脅か", "逸ら", "濡ら", "揺ら", "枯ら", "漏ら", "蒸ら",
    "垂ら", "走ら", "巡ら", "通わ", "太ら", "困ら", "化か", "無く", "亡く",
    // 「ほど」は入れないのだ。「ほどす」という動詞は無く（「施す」は「ほどこす」）、
    // 副助詞の「ほど」を巻き込んで「それほどします」→「それほどすのだ」を作るのだ
    "果た", "満た", "冷やか", "急か", "誤魔化", "ごまか", "いた", "こぼ", "過ご",
    // 仮名を挟まずに漢字だけで書く和語の複合動詞。下の「直前が漢字なら除く」で
    // 落ちてしまうので個別に挙げるのだ（「思い出し」「取り消し」は仮名が挟まる）
    "目指", "見直", "見渡", "見返", "見落と", "出直", "手渡",
  ],
  // タ行五段。「落ち」「満ち」は上一段なので入れないのだ
  ち: [
    "待", "立", "勝", "持", "打", "保", "育", "発", "建", "経", "絶", "断", "討",
    "撃", "旅立", "役立", "目立", "際立", "腹立", "苛立", "先立", "巣立", "成り立",
  ],
  // ナ行五段は「死ぬ」だけなのだ（「往ぬ」は古語）
  に: ["死"],
  // バ行五段。「伸び」「延び」「浴び」「帯び」「詫び」「滅び」「綻び」は上一段なのだ
  び: [
    "呼", "遊", "学", "選", "運", "結", "喜", "飛", "転", "並", "及", "叫", "忍",
    "跳", "浮か", "よ", "あそ", "まな", "よろこ", "えら", "はこ", "むす", "さけ",
  ],
  // マ行五段。「試み」「染み」は上一段なので入れないのだ
  み: [
    "飲", "呑", "読", "進", "住", "済", "積", "頼", "休", "望", "産", "生", "挟",
    "噛", "掴", "包", "沈", "富", "畳", "刻", "好", "悩", "恵", "恨", "臨", "拒",
    "絡", "囲", "摘", "踏", "組", "汲", "編", "縮", "妬", "憎", "挑", "睨", "潜",
    "含", "羨", "励", "澄", "凹", "混", "惜し", "楽し", "苦し", "悲し", "懐かし",
    "慈し", "つか", "たた", "はさ", "かこ", "から", "なや", "たの", "たのし", "よ",
    // 仮名書きの「飲む／呑む」（「のみます」「のんだ」）。よく仮名で書かれるのだ
    "の",
  ],
  // ラ行五段。「借り」「足り」は上一段なのだ。「降り」「下り」は五段（雨が降る）と
  // 上一段（電車を降りる）が同形で決められないので、どちらの表にも入れないのだ
  り: [
    "帰", "送", "走", "取", "撮", "採", "摂", "売", "作", "造", "創", "切", "入",
    "知", "座", "眠", "困", "残", "減", "曲", "通", "終", "始", "移", "断", "誇",
    "祈", "張", "貼", "握", "守", "参", "治", "直", "至", "渡", "登", "昇", "乗",
    "載", "折", "織", "練", "太", "光", "滑", "散", "迫", "誤", "謝", "罵", "悟",
    "配", "割", "祭", "宿", "黙", "怠", "劣", "限", "量", "計", "測", "図", "謀",
    "盛", "掘", "彫", "塗", "被", "縛", "絞", "削", "探", "怒", "叱", "殴", "蹴",
    "刈", "狩", "飾", "釣", "吊", "回", "戻", "譲", "語", "余", "照", "破", "当",
    "返", "映", "写", "振", "触", "煽", "焦", "陥", "遮", "潜", "凝", "曇", "巡",
    "祟", "捗", "判", "有", "贈", "喋", "頑張", "威張", "見送", "受け取", "受取",
    "怒鳴", "踏ん張", "群が", "乗り切",
    "掛か", "懸か", "関わ", "変わ", "代わ", "替わ", "加わ", "備わ", "教わ",
    "終わ", "始ま", "集ま", "決ま", "止ま", "留ま", "泊ま", "詰ま", "挟ま",
    "埋ま", "捕ま", "助か", "浸か", "見つか", "見付か", "授か", "上が", "下が",
    "繋が", "広が", "拡が", "曲が", "転が", "起こ", "溜ま", "貯ま", "染ま",
    "固ま", "収ま", "治ま", "納ま", "静ま", "高ま", "深ま", "強ま", "弱ま",
    "刺さ", "交わ", "混ざ", "交ざ",
    "わか", "分か", "すわ", "ねむ", "こま", "はし", "かえ", "つく", "のぼ",
    "くば", "しゃべ", "やぶ", "あた", "めく", "もど", "はかど", "こだわ",
    // 送り仮名を含む現代の標準表記。上の「当」は送り仮名を持たない古い書き方で、
    // 「当たる」「当たります」は語幹が「当た」なので引けていなかったのだ
    "当た",
    // 上に漢字の形（上が・下が・掛か・頑張・回・残）が載っている語の仮名書き。
    // 仮名で書かれる頻度が高い基幹動詞なのだ
    "あが", "さが", "かか", "がんば", "まわ", "のこ",
    // 「入る」の仮名書き。上の「入」は漢字の側で、仮名で書かれる「はいる」を
    // 引く道が無かったのだ（「お風呂はいらねば」「はいります」）
    "はい",
    // 「ある」「なる」「やる」は使用頻度がとびぬけて高い基幹動詞なのだ
    "あ", "な", "や",
    // 「とる（取る・撮る・採る）」もラ行五段なのだ。上の「取」「撮」「採」の仮名書き。
    // 西日本の「〜とる」（＝「〜ておる」＝標準語の「〜てる」）も同じ活用で、
    // 上の「お（おる）」を「て」ごと縮めた形なのだ（「決まっとる」「泊まっとる」）
    "と",
    // 「おる（居る・折る・織る）」もラ行五段なのだ。関西・謙譲でよく使われる
    // （「犯人おるな」「祈っております」）
    "お",
  ],
  // ワ行五段。「用い」「報い」「老い」「強い」「悔い」は上一段なのだ
  い: [
    "買", "使", "思", "言", "会", "逢", "笑", "洗", "払", "迷", "通", "誘", "従",
    "願", "争", "疑", "習", "揃", "狂", "舞", "奪", "補", "担", "扱", "酔", "吸",
    "這", "覆", "賄", "庇", "慕", "伴", "漂", "行", "合", "違", "救", "呪", "祝",
    "整", "養", "装", "競", "問", "沿", "添", "構", "拾", "追", "叶", "戦", "闘",
    "縫", "誓", "潤", "匂", "臭", "狙", "襲", "背負", "喰ら", "味わ", "賑わ",
    "出会", "手伝", "向か", "食ら", "貰",
    // 「食う」もワ行五段なのだ。「食ら（食らう）」は載っていたが素の形が無かったのだ
    "食",
    // この行はワ行五段の終止形を引くためだけでなく、連用形名詞（「占い」「気遣い」）を
    // 形容詞（「高い」「易い」）と分けるためにも引かれるのだ。連用形名詞は定義上
    // ワ行五段の連用形なので、この表に載っていない語は形容詞に読まれてしまうのだ。
    // 下の6語は終止形としての出番はほぼ無いが、連用形名詞の側で要るのだ
    "占", "遣", "集", "償", "商", "憩", "弔",
    // ワ行五段の被覆漏れ。この行は終止形（「歌う」）と連用形名詞（「願い」）の
    // 両方を引くので、漏れると「歌うんだ」が「歌うんなのだ」と撥音を取り残すのだ
    "歌", "唄", "謳", "飼", "乞", "請", "恋", "憂", "惑",
    // 仮名書きの「ならう」は入れないのだ。接続助詞・断定の仮定形「なら」と同形で、
    // 「明日ならいません」の「なら」まで語幹に読んで「明日ならわない」を作るからなのだ。
    // 「習」は漢字で上に載っているので、失うのは仮名書きの「ならいます」だけなのだ
    "もら", "つか", "おも", "わら", "あら", "はら", "まよ", "さそ", "したが",
    "ねが", "うたが", "そろ", "うば", "ちが", "すく", "あつか", "てつだ",
    "むか", "かま", "たたか", "ねら", "ひろ",
    // 補助動詞「〜てしまう」とその口語形（「〜ちゃう」「〜じゃう」「〜ちまう」）。
    // 「食べてしまいました」→「食べてしまったのだ」
    "しま", "ちゃ", "じゃ", "ちま", "じま",
    // 「という」の口語縮約「〜ちゅう／〜っちゅう」も同じワ行五段（＝「言う」）なのだ
    // （「よかったやんっちゅう」＝「よかったやんという」）
    "ちゅ",
    // 「言う」の仮名書き。縮約形の「ちゅ」を載せておきながら、元の語を
    // 載せていなかったのだ。「という」「っていう」「そういう」「ガサガサいう」の
    // ように仮名で書かれる頻度がとびぬけて高い基幹動詞なのだ
    // （終止形「いう」・連用形「いい」・未然形「いわ」・音便形「いっ」）
    "い",
  ],
};

// 体言と同形の五段語幹に付ける番人（語幹の直前に置く先読み）。
// 「話」は動詞「話す」の語幹だが体言でもあるのだ。
// 体言の「話」を数え上げることはできないのだ。「〜話」は生産的な複合名詞で
// （「うわさ話」「こぼれ話」「バカ話」「ないしょ話」）、前部はいくらでも作れるからなのだ。
// 数え上げられるのは逆側、つまり動詞「話す」が取れる直前の語のほうなのだ。
// 動詞の直前に立てるのは
//   格助詞・係助詞（「計画を」「先生に」「彼と」「電話で」「私は」「僕も」「駅へ」）
//   その語尾の「ら」（「これから」「歩きながら」「終わったら」「暇なら」）
//   副詞・形容詞の連用形の語尾（「ゆっくり」「あまり」／「よく」「詳しく」）
//   文頭
// のどれかで、これは閉じた類なのだ。
// 「昔話」「世間話」「無駄話」は下のサ行の漢字ガードで塞がるのだ。
// 逆に文頭限定にしてはいけないのだ。動詞「話す」は目的語や修飾語を伴うのが普通で、
// 文頭に立つほうが珍しいからなのだ。
//
// 肯定条件（直前が格助詞か文頭のときだけ五段に読む）も試して戻したのだ。
// 動詞「話す」の直前は閉じた類だと思ったが、そうではなかったのだ。
// 「また話します」「もう話しません」「少し話します」「たくさん話します」のように
// 副詞・時間詞が普通に立つので、白名簿は必ず穴が開いて
// 「もう話しないのだ」という非文を作るのだ（実測24語48形）。
// 否定リストの穴は稀な複合名詞（うわさ話・こぼれ話）にしか出ないのに対し、
// 肯定リストの穴は「また」「もう」「少し」という日常語に出るのだ。
// どちらも完全にはならないので、期待損の小さい否定リスト側を採るのだ。
const STEM_GUARD = {
  話: "(?<!その|この|あの|どの|[なのい]|立ち)",
};

// 上一段動詞（語幹がい段で終わり「る」が付く）。現代語では新語がこの型にならない
// 閉じた類なのだ（新しい動詞は「ググる」のようにラ行五段か、可能動詞の下一段になる）。
// 漢語＋「じる」（「感じる」「応じる」）だけは今も増えるが、「じ」の段には五段が
// 無いので表に載せなくても一意に決まるのだ。
// 未然形・音便形は「表に無い語＝上一段の読み」が既定なのでこの表は要らない。
// 終止形（〜ます）だけは既定が五段（い段→う段）なので、ここで打ち消すのだ
const ICHIDAN_STEMS = {
  い: ["用", "率", "報", "悔", "強", "老"],
  き: ["起", "生", "飽", "尽", "で"], // 「で」＝「できます」
  ぎ: ["過"],
  ち: ["落", "満", "朽"],
  に: ["似", "煮"],
  び: ["伸", "延", "浴", "詫", "帯", "錆", "滅", "綻"],
  // テ形の直後の「み」は補助動詞「みる」で、上一段なのだ（「見てみます」
  // 「読んでみます」）。既定の五段（い段→う段）に落ちると「見てむ」になってしまう
  み: ["試", "顧", "鑑", "染", "て", "で"],
  り: ["借", "足", "懲"],
};

// 五段動詞の命令形は え段で終わるのだ（「死ね」「直せ」「戻れ」「眠れ」）。
// 表層は一段動詞の連用形（＝そのまま名詞になる形。「間違え」「重み付け」「調べ」）と
// 同じなので、直前が その行の五段語幹かどうかを表に問うて分けるのだ。
// え・け・て の3つは表に載る語幹でも衝突が残るので初めから外すのだ
//   え（ワ行）…「間違え」（違）  け（カ行）…「重み付け」「届け」（付・届）
//   て（タ行）…テ形の「見て」「打って」
// 語幹を「漢字を含むもの」に限るのも同じ理由なのだ。ラ行の「あ」「な」「や」を許すと
// 「あれ」「なれ」「やれ」——指示語や助動詞——まで命令形に読んでしまうのだ。
// ★ 以前はここが「漢字で終わる語幹」だったのだ。理由として書いてあったのは
// 上のとおり「仮名だけで書かれた1字の語幹は指示語・助動詞と分けられない」だけなのに、
// 実装はそれよりずっと強く、送り仮名を含む語幹まで丸ごと落としていたのだ——
//   起こせ 動かせ 飛ばせ 伸ばせ 落とせ 済ませ 走らせ 働かせ 減らせ 鳴らせ（サ行67語）
//   終われ 始まれ 集まれ 止まれ 上がれ 下がれ 広がれ 曲がれ 変われ 助かれ（ラ行80語）
//   楽しめ 惜しめ 苦しめ（マ行16語）／ 浮かべ（バ行9語）／ 揺らげ 和らげ（ガ行11語）
// この183語は語幹に漢字を持っていて「仮名だけの語幹」ではないのだから、
// 書いてある理由がそもそも当たらないのだ。理由の範囲まで条件を戻すのだ。
// 純粋に仮名だけの語幹（「あれ」「なれ」「やれ」「とれ」「よめ」「いそげ」）は
// これまでどおり落ちたままなのだ——そこが本当に分けられない側なのだ
const IMPERATIVE_ROW = { せ: "し", ね: "に", べ: "び", め: "み", れ: "り", げ: "ぎ" };
// え段（五段の命令形・可能動詞の語幹）から、その行の い段（連用形）への写像。
// 活用表 GODAN_STEMS を引くための鍵なのだ。
// え段で終わる形が五段の活用なのか一段動詞そのものなのかは、
// え段の直前がその行の五段語幹かどうかで決まるのだ
//   「振ってい＋け」…カ行五段「行く」の命令形（表に「い」がある）
//   「お風呂入って＋ね」…ナ行五段の表は「死」だけなので五段ではない＝一段「寝る」
const E_TO_I = {
  え: "い", け: "き", げ: "ぎ", せ: "し", て: "ち",
  ね: "に", べ: "び", め: "み", れ: "り",
};
// ★ 語幹表を引くだけでは足りないのだ。
// え・け・て を外したのは「その3段だけが一段連用形の名詞と衝突するから」ではなく、
// 手元の反例がたまたまその3段だったからにすぎないのだ。
// れ・め・せ・べ・げ も同じだけ衝突するのだ。五段 X-る／X-む／X-ぐ のほとんどに
// 一段の対（X-れる／X-める／X-げる）があり、その連用形はそのまま名詞になるからなのだ
//   品切れ 売り切れ 一切れ 手入れ 仕入れ 受け入れ ひび割れ 前触れ 泥塗れ
//   気休め 醤油絡め 塗装剥げ …（35語を総当たりして28語が非文になったのだ）
// 段を落として逃げるのではなく、命令形と連用形名詞を分ける条件を書くのだ。
// 分かれ目は語幹の直前にあるのだ:
//   命令形は文の述語まるごとなので、直前は 文頭・空白・記号 か
//   述語の前に置ける助詞（「うわ／死ね」「震えて／眠れ」「世界へ／戻れ」「お前が／直せ」）
//   連用形名詞は「名詞＋語幹」の複合語なので、直前は前部名詞の末尾——
//   漢字・カタカナ・送り仮名（品／切れ、手／入れ、泥／塗れ、気／休め、差し／入れ）
// 助詞は次の1字に限るのだ。同じ1字でも複合語の内部に現れうるものは入れないのだ
//   「し」…接続助詞だが五段サ行の連用形語尾でもある（差し入れ・押し込め）
//   「か」…「ばか騒ぎ」の「か」と分けられない
//   「の」…連体修飾の「の」は述語の前に立てないので、そもそも要らないのだ
// 「わ」「あ」は助詞ではなく感動詞の末尾なのだ（「うわ」「さあ」「じゃあ」）
//
// 助詞のほかに副詞も述語の前に立てるのだ（「早く帰れ」「ゆっくり休め」「少し黙れ」）。
// 助詞と違って副詞は1字では終わらないので、上の1字の類には入らないのだ。
// 副詞は閉じた類なので数え上げられるのだ。名詞の前部（「うわさ話」の「うわさ」）と
// 違って、いくらでも新しい語が作れるということが無いからなのだ。
// だから許可リストを書いても穴が開かないのだ。数え上げるのは3つの形なのだ
//   形容詞の連用形「〜く」（早く・よく・強く・詳しく）
//   促音を含む擬態語副詞「〜っ〜り」（ゆっくり・しっかり・はっきり・ぐっすり）
//   語として挙げるほか無い副詞（少し・すぐ・もう・たくさん・はよ・みんな）
// 「り」の1字だけを通してはいけないのだ。連用形名詞の前部もラ行の連用形で
// 終わるからなのだ（「売り／切れ」「盛り／付け」）。促音があれば擬態語副詞と決まるので、
// 「っ」を必須にして分けるのだ。
//
// ★ 3つめだけが語の列挙なので、なぜ形の類にできないのかを書いておくのだ。
// 日本語の副詞には形態の目印が無いのだ。「少し」「すぐ」「もう」「たくさん」「はよ」に
// 共通するのは末尾の仮名だけで、その仮名を開くと連用形名詞の前部（送り仮名）まで
// 通ってしまうのだ——「差し／入れ」「売り／切れ」「盛り／付け」がその形なのだ。
// 「し」を上の1字の助詞リストから外してあるのとまったく同じ理由なのだ。
// 一般化できるところは既に一般化してあるのだ。この見張りは語幹の直前しか見ないので、
// 末尾が助詞と同じ仮名で終わる副詞はもう通っているのだ——「もっと飲め」「ちゃんと帰れ」
// 「さっさと直せ」「きちんと並べ」は「と」で通っていて、列挙は要らないのだ。
// 列挙が要るのは、末尾の仮名を開くと送り仮名まで通ってしまう語だけなのだ。
//
// この6語が測っていないことも書いておくのだ。6語のうち5語はテスト1件と1対1で、
// 残る1語（「もう」）はどのテストにも対応しないのだ。閉じた類なので語を足すのは
// 正しいのだが、いま並んでいる長さは「出会った文の数」でしかないのだ。
// 新しい副詞に出会ったらここに足すのだ。足しても穴は開かないのだ——
// 見るのは語幹の直前だけで、副詞は名詞の前部にならないからなのだ。
//
// 呼びかけの体言（「お前死ね」「バカ死ね」）は通せないのだ。呼びかけに立てる体言は
// 開いた類で、名詞前部（「塗装剥げ」）とまったく同じ形だからなのだ。
// 「みんな」だけは副詞用法があるので（「みんな食べた」）ここに置いてあるが、
// 「みんな死ね」の「みんな」は実際には呼びかけなのだ。だから兄弟の
// 「お前死ね」「バカ死ね」「こいつ死ね」「おまえ帰れ」「全部死ね」は通らないままなのだ。
// そこは表では埋まらない側なのだ
const IMPERATIVE_ADV =
  "[ぁ-ゖ一-龯々]く|[ぁ-ゖ]っ[ぁ-ゖ]り|少し|すぐ|もう|たくさん|はよ|みんな";
const IMPERATIVE_LEAD =
  `(?<=^|[がをにへとではもらばてわあ]|${IMPERATIVE_ADV}|[^\\p{L}\\p{N}])`;
// タ行五段の命令形（「待て」「立て」）は、テ形（「〜て」）と字形がまったく同じなのだ。
// 表に問うだけでは足りないのだ——タ行五段の語幹はどれも下一段・可能動詞と対を成すので、
// 「一戸建て」「子育て」「組み立て」のような連用形名詞の末尾も表に載ってしまうからなのだ。
// 命令形は文節の頭に立つので、五段命令形と同じ前部の番人（助詞・副詞・文頭）を掛けるのだ。
// これを掛けないと「一戸建て」→「一戸建つのだ」と語幹が壊れるのだ
const TA_IMPERATIVE_RE = new RegExp(
  IMPERATIVE_LEAD + "(?:" + GODAN_STEMS.ち.map((t) => (STEM_GUARD[t] ?? "") + t).join("|") + ")$",
  "u",
);
const isTaImperative = (off, str) => TA_IMPERATIVE_RE.test(str.slice(0, off));
const IMPERATIVE_RE = new RegExp(
  IMPERATIVE_LEAD +
    "(?:" +
    Object.entries(IMPERATIVE_ROW)
      .map(
        ([e, row]) =>
          `(?:${GODAN_STEMS[row]
            .filter((s) => /[一-龯々]$/u.test(s))
            .map((s) => (STEM_GUARD[s] ?? "") + s)
            .join("|")})${e}`,
      )
      .join("|") +
    ")$",
  "u",
);

// 語幹表を行ごとの正規表現にまとめる。
// サ行だけは語幹の直前が漢字なら漢語サ変の熟語の末尾なので除くのだ
// （「進出し」「解消し」「電話し」「補足し」「退治し」「開催し」）。
// 数字も同じく除くのだ。数詞の直後の1字は助数詞で、それに付く「し」はサ変だからなのだ
// （「3回します」「2周します」。除かないと助数詞の「回」がサ行五段の「回す」に
// 化けて「3回すのだ」になる）。半角・全角の両方を見る。
// ただし助数詞そのものは漢語ではないので、その直後の漢字は漢語サ変の後半ではないのだ
// （「5回押します」の「押」）。漢字の直前が数字なら、その漢字は助数詞であって
// 熟語の前半ではないので、除外の対象から戻すのだ。
// この戻しは「数詞＋助数詞＋和語動詞」（「5回／押します」「5個／渡します」
// 「3分／蒸らします」）を拾うためのものだが、同じ字面が「数詞＋漢語サ変」
// （「2／発表します」）にも読めるのだ。分けるには 2字が熟語をなすかを知る要があり、
// 一般には漢語の辞書が要る。ただし衝突するのは「後半の漢字がこのサ行の語幹表に
// 載っている漢語」に限られるので、表と突き合わせれば数え上がるのだ。
// 表の1字語幹（話・出・返・…・表・現・足・増・離）を後半に持つ漢語サ変で、
// 前半が助数詞にもなる字は次の6語だけなのだ:
//   分離（分）／発表・発現・発足（発）／倍増（倍）／通話（通）
// この6語のときだけ助数詞への戻しをやめて漢語サ変に読むのだ。
// 「回帰」（回）「列記」（列）は表に載る後半を持つが戻さないのだ。
// 「3回帰します」「3列記します」は数量詞の読み（3回／3列）のほうが普通で、
// 「回」「列」は助数詞としての頻度がはるかに高いからなのだ。
// 他の行には漢語サ変との衝突が無く、複合動詞の語幹が漢字に続く形
// （「見送り」「持ち帰り」）を拾いたいので、この条件は付けないのだ。
//
// 体言と同形の語幹には STEM_GUARD の先読みを頭に付けるのだ
//
// 数詞の直後の漢字を助数詞と読み直すときに外す漢語サ変（上のコメントの6語）
const KANGO_AFTER_NUM = "分離|発表|発現|発足|倍増|通話";
const stemRe = (kana, stems) =>
  new RegExp(
    (kana === "し"
      ? `(?:^|[^一-龯々0-9０-９]|(?<=[0-9０-９])(?!${KANGO_AFTER_NUM})[一-龯々])`
      : "") +
      `(?:${stems.map((s) => (STEM_GUARD[s] ?? "") + s).join("|")})$`,
    "u",
  );
const GODAN_RE = Object.fromEntries(
  Object.entries(GODAN_STEMS).map(([k, v]) => [k, stemRe(k, v)]),
);
const ICHIDAN_RE = Object.fromEntries(
  Object.entries(ICHIDAN_STEMS).map(([k, v]) => [k, stemRe(k, v)]),
);
// c = 連用形の末尾仮名、off = その位置、str = 文全体
const isGodan = (c, off, str) =>
  GODAN_RE[c] !== undefined && GODAN_RE[c].test(str.slice(0, off));
const isIchidan = (c, off, str) =>
  ICHIDAN_RE[c] !== undefined && ICHIDAN_RE[c].test(str.slice(0, off));
// サ行だけに付いている「直前が漢字なら除く」という番人は、連用形「し」が
// 漢語サ変の語幹の末尾（「電話し」「進出し」）と同形になることへの備えなのだ。
// 終止形「す」の側にはその紛れが無いのだ——漢語サ変の終止形は「する」であって、
// 「電話す」「進出す」という形は無いからなのだ。
// 番人を終止形にまで効かせると、助詞を挟まない体言＋動詞の複合
// （「野菜刺す」「手紙出す」）が、直前が漢字というだけで動詞と認められなくなるのだ。
// 体言と同形の語幹に付く STEM_GUARD（「その話」を除く番人）は残すのだ
const SA_SHUSHI_RE = new RegExp(
  `(?:${GODAN_STEMS.し.map((s) => (STEM_GUARD[s] ?? "") + s).join("|")})$`,
  "u",
);

// 口語の否定「〜ん」（＝助動詞「ぬ」）は未然形に付くのだ。既に拾っているのは
// ラ行五段の「わからん」・サ変の「せん」・関西の「へん」だけなのだ。
// もう一つ、え段＋「ん」という大きな類があるのだ。可能動詞（五段のえ段＋「る」）と
// 一段動詞の未然形は語幹と同形なので、否定はそのまま え段＋「ん」になる
//   使えん＝使えない  書けん＝書けない  見えん＝見えない  寝れん＝寝れない
// これも「ラーメン」「ごめん」「たいへん」のような体言の末尾と字形が同じなのだ。
// 体言の側は数え上げられないが、え段の直前がその行の五段語幹かどうかは
// 活用表が答えを持っているのだ（「使」はワ行五段の表にあり、「ごめ」の「ご」は
// マ行五段の表に無い）。表を引ける側で決めるのだ
const E_NEGATION = /([えけげせてねべめれ])ん$/u;
const isPotentialNegation = (s) => {
  const m = E_NEGATION.exec(s);
  return m !== null && isGodan(E_TO_I[m[1]], m.index, s);
};
// 「ない」の口語形「ねえ／ねー」（「止まらねえ」＝「止まらない」）。
// 「ない」と同じ形容詞型の終止形なので、そのまま「のだ」を接げるのだ。
// 感動詞・終助詞の「ねえ」（「ねえねえ」「いいねえ」）と字形が同じなので、
// 直前が五段の未然形（あ段）で、その手前がその行の語幹かを活用表に問うて分けるのだ
const A_TO_I = {
  わ: "い", か: "き", が: "ぎ", さ: "し", た: "ち",
  な: "に", ば: "び", ま: "み", ら: "り",
};
// サ変の口語否定「せん」（＝「しない」）。サ変の語幹は漢語かカタカナ語なので、
// 「せん」の直前は 漢字・カタカナ か、述語の前に置ける助詞 か 文頭に限られるのだ
// （「勉強せん」「気にせん」「何もせん」）。
// ひらがなの直後の「せん」は体言の末尾なのだ（「まいせん」「せんべい」）。
// 無条件に否定と読むと「出発前はまいせんのだ」という非文になるのだ
const SEN_NEGATION = /(?:^|[一-龯々ァ-ヺ]|[がをにへとではもらばてわあ]|[^\p{L}\p{N}])せん$/u;
// 口語否定の「ん」（＝助動詞「ぬ」）で終わっているかを活用表に問うのだ。
// 「ぬ」は未然形にしか付かない助動詞なので、直前の段と、その手前が
// その行の語幹かどうかで決まるのだ。体言の末尾の「ん」（「みかん」「ラーメン」
// 「みかちゃん」）とは、そこでしか分けられないのだ。
//   ラ行五段 …「わからん」。カ変の「こん」は擬音（「ぺこん」）を巻き込むので入れない
//   サ変    …「せん」（＝「しない」）。直前がサ変の語幹か助詞か文頭のときだけなのだ。
//              ひらがなの直後は体言の末尾なのだ（「まいせん」）
//   関西    …「へん」。未然形は あ段（五段）か え段（一段）なので、その直後に限るのだ。
//              い段・お段の直後は体言の一部なのだ（「たいへん」「このへん」）
//   え段    … 可能動詞・一段の未然形（「使えん」「書けん」「見えん」）。
//              え段の直前をその行の五段語幹の表に問うて「ごめん」と分けるのだ
//   カ行    …「かん」。体言と字形が重なるので語幹表に問うのだ（「行かん」は表にあり、
//              「じかん」の「じ」は無い）。「あかん」「いかん」は語幹に分けられない
//              一語の関西語なので名指しで通すのだ
// ★ この述語は2か所で使うのだ——下の字形の判定と、「〜んか」の規則の番人なのだ。
// 同じ問いを2度書くと必ず食い違うので、1つにまとめてあるのだ。
// ★ 五段一般の未然形（あ段）＋「ん」は入れていないのだ。「及ばん」「勝たん」を
// 拾える代わりに、敬称の「〜さん」（「隠さん！」の「隠さ」はサ行五段の語幹表にある）と
// 語尾の「〜わん」（「行きたいわん」）まで否定に読むからなのだ。
// 全コーパス13618件で改善2・悪化2の相殺だったので入れずに戻したのだ。
// 敬称の「さん」は数え上げられない開いた類で、コーパスが小さく見せているだけなのだ
const isColloquialN = (s) =>
  /らん$/u.test(s) ||
  SEN_NEGATION.test(s) ||
  /[わかがさたなばまらえけげせてねべめれ]へん$/u.test(s) ||
  isPotentialNegation(s) ||
  (/かん$/u.test(s) &&
    (/[あい]かん$/u.test(s) || isGodan("き", s.length - 2, s)));
// サ変の語幹の直後であることを見張る後読み。上の SEN_NEGATION と同じ条件を、
// 置換規則から使えるよう「直前の1字を食わない」形に書き直したものなのだ。
// サ変の語幹になれるのは名詞なのだ。名詞の表記は
//   漢字・カタカナ（長音符を含む）・ラテン文字・数字 で終わるか、
//   漢字に送り仮名が続く形（「半田付け」「読み書き」「片付け」）
// のどちらかなのだ。ほかに、述語の前に置ける助詞の直後と文頭も立てるのだ。
// ひらがなだけで書かれた語は、サ変の語幹なのか別の語の末尾なのかが表記から読めないので
// 降ろすのだ（SEN_NEGATION が「まいせん」を体言に倒しているのと同じ理屈なのだ）。
// ★ 送り仮名の枝は SEN_NEGATION には無いのだ。「せん」の側に足すと「まいせん」を
// 拾いかねないが、こちらは「しよ」で終わる体言そのものが無いので足せるのだ。
// ★ 助詞は SEN_NEGATION より狭く「をにもは」に絞るのだ。SEN_NEGATION の
// 「ら」「て」「で」を通すと、動詞の連用形・断定の語尾まで助詞に見えて
// 「暮らし＋よ」「果てし＋よ」を巻き込み、「でしょ」の打ち間違い「でしよ」まで
// サ変に読んでしまうからなのだ（実測して外したのだ）
const SAHEN_LEAD =
  "(?<=^|[一-龯々ァ-ヺーゝゞA-Za-z0-9０-９]|[一-龯々][ぁ-ゖ]{1,2}|" +
  "[をにもは]|[^\\p{L}\\p{N}])";
// 「〜なさい」の形をしているが命令ではなく1語になった挨拶。
// 「おやすみ」「おかえり」は表に載る五段語幹（休む・帰る）と字形が同じなので、
// 活用表だけでは分けられず、語として名指しで除くほかないのだ
const GREETING_NASAI = /(?:おやすみ|おかえり|お休み|お帰り|ごめん)なさい/u;

// 仮名だけで書かれた撥音便の過去形（「のんだ」「よんだ」「たのんだ」）。
// 説明の「んだ」（「そうなんだ」→「そうなのだ」）と表層がまったく同じなので、
// 「ん」の手前が撥音便を起こす行（マ・バ・ナ行五段）の語幹かどうかで分けるのだ。
// 漢字で書かれた語幹は別のルールで拾うので、仮名で終わる語幹だけを集める
const ONBIN_N_STEMS = [...GODAN_STEMS.み, ...GODAN_STEMS.び, ...GODAN_STEMS.に]
  .filter((s) => /[ぁ-ゖ]$/u.test(s));
// 同じ表を「〜んで」（撥音便のテ形）の側でも引くのだ。
// 仮名書きの語幹＋「ん」で終わっていれば、その「ん」は撥音便であって
// 口語否定の「ん」ではないのだ（「えらん（選ん）」「からん（絡ん）」「つかん（掴ん）」）
const ONBIN_N_RE = new RegExp(`(?:${ONBIN_N_STEMS.join("|")})ん$`, "u");
// 「〜んで」の位置に立つ口語否定なのだ。ここだけ番人が1枚多く要るのだ——
// 「〜んで」は マ・バ・ナ行五段の撥音便のテ形でもあるからなのだ（「読んで」「選んで」）。
// 漢字で書かれた語幹は isColloquialN のどの枝も否定と認めない（漢字の直後の「ん」は
// どの段でもないのだ）ので、紛れるのは仮名で書かれた語幹だけなのだ。
// その仮名語幹は撥音便の表（ONBIN_N_STEMS）に集めてあるので、当たれば撥音便に倒すのだ
// （「えらん（選）」「からん（絡）」「つかん（掴）」）。
// ★ ただしラ行五段の未然形として活用表が裏づけるものは、そちらを採るのだ。
// 「わからん」は表の「わか」＋未然形の「ら」＋「ん」で、末尾3字が「からん」に
// 見えるのは字面の偶然だからなのだ（「わ」＋「絡ん」という語は無いのだ）。
// 活用表が長いほうの語幹を持っている側が勝つ、という切り分けなのだ。
// ★ 仮名形が表に無い語（「並ぶ」「膨らむ」は漢字の「並」「膨」しか載っていない）は
// 分けられないままなのだ。「ならんで」「ふくらんで」は否定の側に倒れるのだ。
// ただし「ならんで」は関西では「ならないよ」でもあって、表層では決まらないのだ
// ★「らん」「らへん」の「ら」はラ行五段の未然形なのだから、活用表に裏づけさせるのだ。
// isColloquialN の「らん」枝だけが活用表を引いていなくて（他の枝は全部引いているのだ）、
// 「そこらへん」「すずらん」「ごらん」のような体言の末尾まで否定と読んでいたのだ。
// 承認版ではその誤判定が「〜んで」を無条件に無変換にする防波堤に阻まれて表に出て
// いなかっただけで、防波堤を外した以上ここで裏を取る要があるのだ
const RA_MIZEN_RE = /ら(?:へ)?ん$/u;
const raBacked = (s) => {
  const m = RA_MIZEN_RE.exec(s);
  return m === null || isGodan("り", m.index, s);
};
const isColloquialNBeforeDe = (s) =>
  isColloquialN(s) &&
  raBacked(s) &&
  (!ONBIN_N_RE.test(s) ||
    (/らん$/u.test(s) && isGodan("り", s.length - 2, s)));

// 「〜ます」の直前に来る連用形の末尾仮名を終止形へ戻す表
// （「お知らせします」→「お知らせする」、「感じます」→「感じる」）
const MASU_STEM = {
  // 五段：い段 → う段
  い: "う", き: "く", ぎ: "ぐ", ち: "つ", に: "ぬ",
  ひ: "ふ", び: "ぶ", み: "む", り: "る",
  // サ変・上一段
  し: "する", じ: "じる",
  // 一段：え段 → え段＋る
  え: "える", け: "ける", げ: "げる", せ: "せる", ぜ: "ぜる",
  て: "てる", で: "でる", ね: "ねる", へ: "へる", べ: "べる",
  め: "める", れ: "れる",
};
// 連用形＋「ます」を 終止形＋tail に直す置換関数を作る。
// い段の既定は MASU_STEM の い段→う段（＝五段の終止形）なので、
// 五段の表を引く必要があるのはサ行だけなのだ（「話します」→「話すのだ」。
// 既定の「する」だと「話するのだ」になってしまう）。
// 上一段は既定を打ち消すために表を引く
// （「起きます」→「起きるのだ」。既定のままだと「起くのだ」になってしまう）
const masu = (tail) => (_m, c, off, str) =>
  (isIchidan(c, off, str)
    ? c + "る"
    : isGodan(c, off, str)
      ? GODAN_ROW[c].u
      : MASU_STEM[c]) + tail;
// 「ます」の直前に立てる仮名（＝連用形の語尾）。この表に無い仮名の「ます」は
// 「だます」「済ます」のように語幹の一部なので、ます形として扱ってはいけないのだ
const MASU_STEM_CLASS = `[${Object.keys(MASU_STEM).join("")}]`;
// 丁寧の意向形「ましょう」の後ろに立てる終助詞なのだ。
// 「ましょう」は「ます」の未然形＋推量の「う」で、活用の位置は「ます」と同じなので、
// 立てる終助詞も「ます」の並びとそのまま同じなのだ
// （老人語の「〜ましょうな」・力む「〜ましょうぞ」も同じ位置なのだ）。
// 「ましょう」を受ける枝は4本あるのだ——カ変「来る」／テ形＋カ変／
// 送り仮名を持たない漢字1字の一段／連用形の表——ので、同じ並びを4回書くと
// 必ず食い違うのだ。1か所にまとめてあるのだ
const MASHOU_SFP = "(?:よね|よな|わよ|わね|わな|なあ|[よねわなぞぜ])";

// 用言（動詞・形容詞）の終止形の末尾。ここで終わる語には「な」を挟まず「のだ」を付ける。
// 「う」は意向形・様態の「そう/よう/どう/ありがとう」と紛れるので、お段の直後を除く。
// 拗音「ゃゅょ」の直後の「う」は除かないのだ。「〜てしまう」の口語形「〜ちゃう」
// 「〜じゃう」がワ行五段の活用そのもので、拗音の直後に活用語尾の「う」が立つからなのだ
const YOGEN = "(?:[^おこごそぞとどのほぼもろよ]う|[くぐすずつぬぶむるいた])";
// 用言の終止形＋語尾 のルールを作る（$1 に終止形の末尾が入る）。
// nd と同じく、字形の類だけでは「その語が用言か」を見ていないのだ。
// 「時間やな」「早起きやな」「人類やぞ」の「ん」「き」「い」…は体言の末尾なのだ。
// 活用表に問うて、用言でなければ規則を降ろすのだ（yogenGuard）
const yr = (tail, rep) => [new RegExp(`(${YOGEN})${tail}$`), yogenGuard(rep)];
// 関西の形容詞「ええ」（＝「いい」）は え段で終わる終止形なのだ。
// 現代語で え段で終わる終止形はこの語だけ（他はすべて一段動詞の連用形・命令形）なので、
// 字形の類（YOGEN）では表せず、語として1つだけ挙げるほかないのだ。
// 口語否定の「ん」（＝「ぬ」）も終止形だが、体言の末尾の「ん」（「みかん」）と
// 字形が同じなので、未然形になりうる段（ら・か・せ・へ）に続くものだけを終止形と認めるのだ
const YOGEN2 = `(?:${YOGEN}|ええ|[らかせへ]ん)`;
// 説明の「ん」（んです／んだ）の直前は用言の終止形か「な」「の」に限られる。
// この番人を挟まないと「みかんです」の語幹の「ん」まで削って「みかのだ」になる。
// ★ ただし字形の類（YOGEN）は「く・つ・た・い で終わる仮名」でしかなく、
// その語が用言かどうかは何も見ていないのだ。体言の末尾にも同じ字形は現れるので
// （「かんたん」の「た」「しんぶん」の「ぶ」「たろうくん」の「く」）、
// 字形だけで通すと語幹の「ん」ごと削って「かんたのだ」「しんぶのだ」と語が壊れるのだ。
// 下の isYogenEnd で活用表に問うて分けるのだ（ndGuard）
const nd = (tail, rep) => [
  new RegExp(`(${YOGEN}|ええ|な|の)ん${tail}$`),
  ndGuard(rep),
];

// ---------------------------------------------------------------------------
// 用言かどうかを活用表に問う
// ---------------------------------------------------------------------------
// ★ YOGEN は「く・つ・た・ぶ… で終わる仮名」という字形の類でしかなく、
// その語が本当に用言かどうかは何も見ていないのだ。だから
// 「あいつ」「いつ」「あなた」「ぜんぶ」「ふたつ」「ぼく」「もうすぐ」「そいつ」
// までが用言に見えて、「あいつだろう」→「あいつのだ」という非文になるのだ。
// 手掛かりは既に手元にあるのだ。五段の語幹表は連用形（い段）を鍵に引けるので、
// 終止形（う段）を連用形に写せば「降る→降り はラ行の表にあるか」と問えるのだ。
// 「あいつ」の「つ」もタ行の表に問えて、「あい」が語幹でないので用言ではないと決まるのだ。
//
// う段（五段の終止形の語尾）→ い段（連用形の語尾）。活用表を引くための鍵なのだ
const U_TO_I = {
  う: "い", く: "き", ぐ: "ぎ", す: "し", つ: "ち",
  ぬ: "に", ぶ: "び", む: "み", る: "り",
};
// お段（五段の意向形の語尾の直前）→ い段（連用形の語尾）。
// 五段の意向形「〜おう」は、歴史的には未然形＋助動詞「う」が融合したものなのだ。
// 行は連用形とまったく同じなので、お段を い段に写せば同じ語幹表を引けるのだ
//   飲も→飲み（マ行）  行こ→行き（カ行）  やろ→やり（ラ行）  使お→使い（ワ行）
// サ行（そ）も載せるのだ。様態の「そう」と字形が重なるが、意向形の「そ」は
// サ行五段の語幹の直後にしか立たないので、表を引けば分かれるのだ
// （下の意向形の規則の註を見るのだ）。
// ハ行（ほ）は行そのものが現代語に無いので載せないのだ
const O_TO_I = {
  お: "い", こ: "き", ご: "ぎ", そ: "し", と: "ち",
  の: "に", ぼ: "び", も: "み", ろ: "り",
};
// 過去の助動詞「た」の直前に立てる仮名。
// 音便形（「書いた」「待った」「読んだ」「話した」）と
// 一段・上一段の連用形（え段・い段。「食べた」「起きた」）に限られるのだ。
// あ段・う段・お段の直後の「た」は活用語尾ではなく語の一部なのだ
// （「あなた」「うた」「かた」「ふた」）
// ★ 撥音「ん」は入れないのだ。撥音便を起こすのはマ・バ・ナ行五段だけで、
// その行の過去は必ず「だ」に濁るからなのだ（読んだ・飛んだ・死んだ）。
// つまり「ん」＋清音の「た」という過去形は活用表のどこにも存在しないのだ。
// 入れておくと体言の末尾の「んた」が用言に見えて
// 「あんただろう」→「あんたのだ」「かんたんだが」→「かんたのだ」と語が壊れるのだ。
// テ形の「て」で「ん」を外したのとまったく同じ理屈なのだ（TE_CONTRACT）
const PAST_LEAD = /[いきぎしちにひみりじびぴえけげせぜてでねへめれべぺっ]$/u;
// 一段動詞の連用形の語尾（＝終止形の「る」の直前）。
// え段は活用語尾にしか現れない形なので、ここが え段なら一段動詞と決まるのだ
const ICHIDAN_LEAD_CHARS = "えけげせぜてでねへべめれいきぎしちにひみりじび";
const ICHIDAN_LEAD = new RegExp(`[${ICHIDAN_LEAD_CHARS}]$`, "u");
// s が用言（動詞・形容詞）の終止形で終わっているかを活用表に問うのだ。
// 表で確かめられた時だけ用言と認め、確かめられなければ体言に倒すのだ。
// 取り違えの害が片側にしか無いからなのだ。体言を用言と読むと
// 「あいつのだ」「ぜんぶのだ」という非文になるが、用言を体言と読んでも
// 「降るなのだ」と語尾が重なるだけで語そのものは壊れないのだ
const isYogenEnd = (s) => {
  const off = s.length - 1;
  if (off < 0) return false;
  const c = s[off];
  const head = s.slice(0, off);
  // 五段の終止形は う段。連用形（い段）に写して語幹表に問うのだ
  // （「降る」→「降り」はラ行の表にある／「あいつ」→「あいち」はタ行の表に無い）
  if (U_TO_I[c] !== undefined && isGodan(U_TO_I[c], off, s)) return true;
  // サ行五段の終止形は漢語サ変ガードを外して問うのだ（上の SA_SHUSHI_RE）
  if (c === "す" && SA_SHUSHI_RE.test(head)) return true;
  if (c === "る") {
    // 一段動詞の終止形は 連用形＋「る」なのだ（「食べる」「起きる」「してる」）。
    // 連用形の え段・い段は活用語尾にしか現れない形なのだ
    if (ICHIDAN_LEAD.test(head)) return true;
    // 語幹が漢字・カタカナで終わる動詞は連用形の仮名が表に出ないので、
    // 表を引く鍵が無いのだ（「見る」「出る」「降る」「ググる」）。
    // 「る」で終わる体言は「ボール」のようにカタカナの「ル」で終わるので衝突しないのだ
    if (/[一-龯々ァ-ヺーゝゞ]$/u.test(head)) return true;
    // サ変「する」・カ変「くる」は活用表の外の不規則動詞なので名指しで通すのだ
    if (/[すく]$/u.test(head)) return true;
    // 敬語のラ行五段特殊活用（いらっしゃる／おっしゃる／なさる／くださる／ござる）。
    // 終止形は普通のラ行五段だが、連用形だけが「〜り」ではなく「〜い」に崩れるのだ。
    // 語幹表は連用形（い段）を鍵に引く作りなので、この5語をラ行の表に足すと
    // 「いらっしゃります」という実在しない連用形を表に書き込むことになるのだ。
    // 表には嘘を書けないので、終止形を見るここで名指しで通すのだ。
    // 上の「ますか」系の特殊活用の規則とまったく同じ、数え上げられる閉じた類なのだ
    if (/(?:いらっしゃ|おっしゃ|なさ|くださ|ござ)$/u.test(head)) return true;
  }
  // 形容詞の終止形は「い」。閉じた類だが仮名書きが多く、表では覆いきれないのだ。
  // 語幹が漢字・カタカナで書き分けられていれば形容詞と決まるのだ
  // （「高い」「楽しい」「広がり易い」。「きれい」「ぐらい」「みたい」は仮名だけなので体言・形容動詞）。
  // ★ ただし「漢字語幹＋い」には形容詞でないものが混じるのだ——連用形名詞
  // （動詞の連用形がそのまま名詞になったもの）なのだ。
  //   間違い 勘違い 知り合い 狙い 願い 支払い 扱い 誘い 争い 戦い 出会い 匂い 手伝い
  // これを形容詞と読むと「あいつのだ」とまったく同じ非文（「間違いのだ」）になるので、
  // 「取り違えの害は片側にしか無い」という前提がここだけ崩れているのだ。
  // 連用形名詞は動詞から作られる開いた類なので語としては数え上げられないが、
  // 定義上「五段動詞の連用形（い段）」なのだから、表を引ける側にあるのだ。
  // ワ行五段の語幹表に載っていれば連用形名詞と決まるのだ
  // （願う・違う・合う・狙う・払う は表にあり、形容詞「高い」「易い」「安い」の
  //  語幹は載っていない）。表で分かる側があるなら、そちらに問うのだ。
  // 「臭い」だけは形容詞とも連用形名詞（＝匂い）とも読めて表では決着しないのだ。
  // その1語は体言に倒れるが、語尾が重なるだけで語は壊れないのだ
  // 仮名だけで書かれる形容詞のうち、否定の「ない」と「いい／よい」は
  // 活用体系そのもの（助動詞・基幹形容詞）なので通すのだ
  // 仮名だけで書かれる形容詞のうち、語尾の形で決まる類も通すのだ。
  //   「〜しい」…シク活用の語尾（「美味しい」「めずらしい」「うれしい」）。
  //     体言・形容動詞にこの終わり方は無いので、語を数え上げずに形で決まるのだ
  //   「〜っぽい」「〜らしい」「〜にくい」「〜やすい」「〜づらい」「〜がたい」「〜くさい」
  //     …形容詞を作る接尾辞。接尾辞は閉じた類なので数え上げられるのだ
  if (
    c === "い" &&
    ((/[一-龯々ァ-ヺーゝゞ]$/u.test(head) && !isGodan("い", off, s)) ||
      /[ないよ]$|し$|っぽ$|にく$|やす$|づら$|がた$|くさ$/u.test(head))
  )
    return true;
  // 願望の助動詞「たい」も形容詞型の活用で、連用形（い段・え段）に付くのだ
  // （「行きたい」「食べたい」）。比況の「みたい」は体言に付く形容動詞型なので
  // 「のだ」ではなく「なのだ」なのだ。表層が同じ「み」の段だけは、
  // マ行五段の語幹表に問う専用の規則が受け持っているので、ここからは外すのだ
  if (/[いきぎしちにひりじびぴえけげせぜてでねへめれべぺ]たい$/u.test(s)) return true;
  // その「み」の段も、活用表に問えば分かれるのだ。マ行五段の連用形（「休みたい」）と
  // 上一段の連用形（「試みたい」／テ形の直後の補助動詞「みる」＝「見てみたい」）だけが
  // 願望の「たい」を取れるのだ。比況の「みたい」は体言に付くので、
  // どちらの表にも載らない「猫」「してる」はここで落ちるのだ
  if (s.endsWith("みたい")) {
    const o = s.length - 3;
    if (isGodan("み", o, s) || isIchidan("み", o, s)) return true;
  }
  // 過去の「た」。直前の仮名が音便形・連用形の形をしているかで分けるのだ
  if (c === "た" && (PAST_LEAD.test(head) || /[^ぁ-ゖ]$/u.test(head))) return true;
  return false;
};
// ★ 表には第三の答えが要るのだ。
// 語幹が仮名だけの「〜い」は、形容詞（つらい・すごい・やばい・きつい）とも
// 形容動詞（きれい）とも体言（ぐらい・みたい）とも読めるのだ。
// 語幹が仮名書きなので数え上げる道が無く、活用表には手掛かりが一つも無いのだ。
// 「用言／体言」の二択に押し込めば、どちらへ倒しても片側は必ず非文になるのだ
//   用言に倒す→「ぐらいのだ」   体言に倒す→「つらいなのだ」
// 「判定が付かなければ体言に倒す。害は片側にしか無い」という上の建て付けは、
// ここでは成り立っていないのだ。だからここだけは第三の答えを返すのだ。
//
// 第三の答えの中身は語尾ごとに違うのだ。「承認済みの版がその語尾に返していた答え」を
// そのまま返すのだ——表で決着が付かない以上、こちらから動かす根拠が無いからなのだ。
// 承認版は語尾ごとに違う機構を使っていたので、答えも語尾ごとに違うのだ
//   でしょう／だろう … 「なのだ」（字形の類に通していなかった）
//   でしょうか／だろうか … 「のだ？」（字形の類 YOGEN に通していた）
//   ですけど／ですから … 無変換（そもそも規則が無かった）
// これで、決着しない語では承認版と1文字も変わらないことが保証されるのだ。
// 「コーパスに11行しか無いから測れなかった」という穴が開かないのだ
const isUndecidableI = (s) =>
  s.endsWith("い") && /[ぁ-ゖ]$/u.test(s.slice(0, -1));
// 用言なら yes、体言なら no、表で決着が付かなければ unsure を接ぐ置換関数を作るのだ。
// 語尾（でしょう／だろう など）の直前までを活用表に問うて分ける。
// unsure を省くと no と同じ（＝従来どおり体言に倒す）なのだ。
// unsure に null を渡すと、マッチをそのまま返して文ごと無変換にするのだ
const yogenSplit =
  (yes, no, unsure = no) =>
  (m, off, str) => {
    const s = str.slice(0, off);
    if (isYogenEnd(s)) return yes;
    if (!isUndecidableI(s)) return no;
    return unsure === null ? m : unsure;
  };

// ---------------------------------------------------------------------------
// 「この規則は適用外なのだ」と告げる印
// ---------------------------------------------------------------------------
// 番人（置換しても文字列が変わらない規則）は「この文は変換しない」と決めて
// 打ち切るものなのだ。それとは別に「自分は当たらないので次の規則に任せる」と
// 言いたい場面があるのだ。字形では当たるが活用表に問うと用言でなかった、という形なのだ
// （「かんたんだが」は nd の字形には当たるが、「かんた」は用言ではないのだ）。
// 正規表現だけでは表を引けないので、置換関数からこの印を返して規則を降ろすのだ。
// 降りた先では体言として扱う規則（「〜だが」→「〜なのだが」）が受け止めるのだ。
// 私用領域の符号位置なので、実データの本文には現れないのだ
const RULE_PASS = "\uE000";
// 置換テンプレート（"$1のだけど$2"・"$&"）を捕獲群で展開する。
// 番人を関数に移すと正規表現側の $1 展開が効かなくなるので、自前で展開するのだ
const expandRep = (rep, m, groups) =>
  rep.replace(/\$(\d|&)/gu, (_, d) => (d === "&" ? m : (groups[+d - 1] ?? "")));
// 字形の類（YOGEN）で捕まえた1つめの捕獲群までを活用表に問い、
// 用言でなければ RULE_PASS を返して規則を降ろす番人を作るのだ。
// 表で決着の付かない仮名語幹の「〜い」（「やばいんです」「つらいですけど」）は
// 承認版と同じく用言に倒すのだ。ここを体言に倒す版は既に測って撤退してあるのだ
// （改善1・悪化6）。表が「用言ではない」と答えた時だけ降ろすのだ
// 用言でなかったときの降り方は2つあるのだ。
//   RULE_PASS … 次の規則に任せる。下に体言を受ける規則があるときはこちらなのだ
//     （「これはうにゅうですか」は下の「ですか」→「なのだ？」が受けるのだ）
//   stop=true … その文は変換しないと決めて打ち切る。下に受け手が無いときなのだ。
//     裸の終助詞（「〜ね」「〜な」「〜よ」）には体言を受ける規則が無く、
//     降ろすと最後の字形の判定まで落ちて終助詞ごと「なのだ」を接ぐのだ
//     （「仲良くねなのだ」「あっぶねなのだ」）。語の切れ目が読めていないのだから、
//     ここは無変換に留めるのが正しいのだ（誤変換より無変換のほうがよいのだ）
const yogenGuard = (rep, extra = [], stop = false) =>
  (...a) => {
    const str = a[a.length - 1];
    const off = a[a.length - 2];
    const m = a[0];
    const groups = a.slice(1, a.length - 2);
    const g1 = groups[0];
    if (extra.includes(g1)) return expandRep(rep, m, groups);
    const s = str.slice(0, off + g1.length);
    if (isYogenEnd(s) || isUndecidableI(s)) return expandRep(rep, m, groups);
    return stop ? m : RULE_PASS;
  };
// 用言＋裸の終助詞。用言と確かめられなければ無変換に留める版なのだ（上の stop）
const yrStop = (tail, rep) => [
  new RegExp(`(${YOGEN})${tail}$`),
  yogenGuard(rep, [], true),
];
// 説明の「ん」の直前は用言の終止形のほかに次の3つが立てるのだ。
//   「な」…形容動詞の連体形（「そうなんです」「好きなんだ」）
//   「の」…準体助詞（「行くのなんです」）
//   「ええ」…関西の形容詞（「ええんや」）
// この3つは説明の「ん」が付く形と分かっているので、表に問わずに通すのだ
const ndGuard = (rep) => yogenGuard(rep, ["な", "の", "ええ"]);

// 音便の直後で濁った過去の助動詞「だ」（＝「た」）なのだ。
// 撥音便（マ・バ・ナ行五段）は「ん」を、イ音便（ガ行五段）は「い」を残すのだ
//   飲んだ 読んだ 遊んだ 死んだ ／ 泳いだ 脱いだ 急いだ
// 断定の「だ」とまったく同じ字形なので、断定と読むと音便形の「ん」「い」ごと
// 削って「飲んなのだが」と語幹が壊れるのだ。体言の末尾の「ん」（みかん・ラーメン）や
// 形容動詞の「い」（きれいだが）と分けるには、その手前がその行の五段語幹かを
// 活用表に問うほかないのだ。音便を起こす行は決まっているので、表で決まる側なのだ
const isOnbinPast = (s) => {
  if (s.endsWith("ん"))
    return ["み", "び", "に"].some((c) => isGodan(c, s.length - 1, s));
  if (s.endsWith("い")) return isGodan("ぎ", s.length - 1, s);
  return false;
};
// 過去の「だ」なら「た」と同じく用言の言い切りなので「のだ〜」を接ぎ、
// 断定の「だ」なら体言に付いているので「な」を挟むのだ
const daSplit = (tail) => (_m, off, str) =>
  isOnbinPast(str.slice(0, off)) ? "だの" + tail : "なの" + tail;

// 連用形＋「ません」を 未然形＋tail に直す（否定の「ない」は未然形に付く）。
// 未然形が連用形と変わるのは五段だけなのだ（い段→あ段）。
// 一段・上一段・サ変の未然形は連用形と同形なので、仮名をそのまま残す
//   書きません → 書かないのだ（五段）
//   起きません → 起きないのだ（上一段。表に無いのでそのまま）
//   食べません → 食べないのだ（下一段）
//   勉強しません → 勉強しないのだ（サ変）
const nai = (tail) => (_m, c, off, str) =>
  (isGodan(c, off, str) ? GODAN_ROW[c].a : c) + tail;

// 連用形＋「ました」を 音便形＋過去＋tail に直す。
// 音便が起きるのは五段だけで、行ごとに形が決まっているのだ
//   書きました → 書いたのだ（イ音便）  飲みました → 飲んだのだ（撥音便）
//   待ちました → 待ったのだ（促音便）  話しました → 話したのだ（音便なし）
// 一段・上一段・サ変は連用形にそのまま「た」が付くのだ（「食べた」「起きた」「した」）
const mashita = (tail) => (_m, c, off, str) => {
  if (!isGodan(c, off, str)) return c + "た" + tail;
  // 「行く」だけはイ音便でなく促音便なのだ（「行いた」ではなく「行った」）。
  // 仮名書きの「いく」（「ついていきました」）も同じ語なのだ
  if (c === "き" && /[行逝い]$/u.test(str.slice(0, off))) return "った" + tail;
  return GODAN_ROW[c].onbin + GODAN_ROW[c].past + tail;
};

// 動詞のテ形の語尾。「で」はガ・ナ・バ・マ行の音便形にしか付かないので、
// 直前は必ず「ん」か「い」なのだ（「読んで」「泳いで」）。
// この条件を付けないと「できます」の「で」までテ形とみなしてしまう
const TE = "(?:[んい]で|て)";
// テ形の「て」「で」を1字だけ捕まえる形。直前がテ形を作れる形かを見張るのだ。
// 「て」の直前に立てるのは 五段の音便形（イ音便「い」・促音便「っ」・サ行「し」）と
// 一段・上一段・カ変の連用形（え段・い段）だけなのだ。
// 語幹が漢字で連用形の仮名が現れない一段動詞（見て・出て・着て・似て・経て）も
// あるので、漢字も通すのだ。
// ★ 撥音「ん」は入れないのだ。撥音便に付くテ形は必ず「で」に濁る（読んで・飛んで）ので、
// 「ん」＋清音の「て」というテ形は存在しないのだ。この1点だけで
// 「うんてん」「せんてん」のような仮名書きの体言が、テ形の縮約「〜てん」と
// 取り違えられなくなるのだ（「うんてるのだ」という語幹の壊れを防ぐ）。
// 「で」の側は上の TE と同じく「ん」「い」に限るのだ（「かでん」は「か」なので落ちる）
const TE_CONTRACT = `((?<=[っ一-龯々${ICHIDAN_LEAD_CHARS}])て|(?<=[んい])で)`;

// 疑問詞。これがある文は、終助詞「か」が無くても・「？」が打たれていなくても
// 相手に答えを求める真の疑問文なのだ（「どう距離を置くか」）。
// 「なんか」「なんて」「いつも」「どうせ」のように語の一部になっている形は
// 疑問詞ではないので除くのだ
const QWORD =
  /何|誰|だれ|なぜ|どこ|どちら|どっち|どれ|いくら|いくつ|なん(?![かてと])|いつ(?![もの])|どう(?![もせぞや])/u;

// ---------------------------------------------------------------------------
// 丁寧語を常体に落としてから、後ろに残った語尾を掛け直す
// ---------------------------------------------------------------------------
// ★ 丁寧語の規則は語尾ごとに書かれているのだ（「ますか」「ますね」「ますから」
// 「ました」「ましたか」…）。だから表に書かれていない組み合わせが漏れるのだ——
// 「ましたっけ」「ましたけど」がそれなのだ。「ありますか」は書いてあるので通り、
// 「使えましたっけ」は書いていないので漏れる、という形の穴なのだ。
// 組み合わせを1つずつ足すのは数合わせなので、そうはしないのだ。
// 丁寧の助動詞は活用の一番外側に立つのだから、それだけを常体に落としてしまえば、
// 後ろに残った語尾は常体の規則がそのまま受け持てるのだ。
//   使えましたっけ  → （常体化）使えたっけ  → （「っけ」の規則）使えたのだっけ？
//   払ってましたけど → （常体化）払ってたけど → （「けど」の規則）払ってたのだけど
// 常体化そのものは既にある masu / mashita / nai をそのまま使うのだ（同じ活用表なのだ）。
// この関数は、常体に直した文をもう一度この規則表に掛け直すだけなのだ。
//
// ★ 規則に当たらなかったとき（番人に当たったときも含む）は null を返すのだ。
// 「ますように」「ますので」「ますが」のように後ろに立っているのが文末の語尾ではなく
// 接続の助詞なら、常体に直しても文はそこで終わっていないのだ。
// 常体の規則表は、そういう形を助詞止めの番人で無変換に留める作りになっているので、
// 「規則が答えを返したか」をそのまま「文末の語尾だったか」の判定に使えるのだ。
//
// ★ 文末限定の規則（"final"。依頼のテ形）は使わないのだ。行が文末かどうかは
// 呼び出し側の文脈（quoted・midSentence）で決まるもので、ここには渡っていないからなのだ
function applyTailRules(s) {
  for (const [re, rep, finalOnly] of ZUNDA_RULES) {
    if (finalOnly === "final") continue;
    if (!re.test(s)) continue;
    const conv = s.replace(re, rep);
    if (conv.includes(RULE_PASS)) continue;
    return conv === s ? null : conv; // 番人に当たったら「答えなし」なのだ
  }
  return null;
}
// 丁寧形を常体 plain に直したうえで、後ろに残った語尾 tail を規則表に掛け直すのだ。
// head は語幹（丁寧形より前）で、そこは触らないのだ。
// 規則が答えなければ（＝後ろに立っているのが文末の語尾ではない）RULE_PASS を返して
// 規則を降ろすのだ。掛け直した規則が head まで食い込んでいた時も同じく降ろすのだ
const relayTail = (head, plain, tail) => {
  const conv = applyTailRules(head + plain + tail);
  return conv !== null && conv.startsWith(head)
    ? conv.slice(head.length)
    : RULE_PASS;
};

const ZUNDA_RULES = [
  // --- 特殊な語（誤った活用を防ぐため最優先） ---
  // 「すみません」の表記ゆれ（「すいません」・カタカナ書き）は同じ謝罪の定型句
  [/(?:すみません|すいません|スミマセン|スイマセン)$/, "すまないのだ"],
  // 挨拶・謝罪の定型句は、字形が用言の活用形でも述語ではないのだ。
  //   「よろしく」…形容詞「よろしい」の連用形だが、挨拶としては体言のように立つ
  //   「ごめんなさい」…「ごめん」＋「なさい」で、「い」で終わるが形容詞ではない
  // 字形どおりに読むと「よろしく」はカ行五段の終止形、「ごめんなさい」は
  // 形容詞の終止形と見えるので、「よろしくのだ」「ごめんなさいのだ」という
  // 非文になるのだ。挨拶は数え上げられる閉じた類なので表に持てるのだ
  [/(?:よろしく|よろしゅう|ごめんなさい|ゴメンナサイ)$/u, "$&なのだ"],
  // 「ごめんあそばせ」は尊敬の「あそばす」の命令形で終わる挨拶なのだ。
  // 命令形は言い切りに開けず、「なのだ」も接げないので無変換にするのだ
  [/(?:ごめんあそばせ|ごきげんよう)$/u, "$&"],
  // 存在動詞「ある／ござる」の否定は「ない」で不規則（「あらない」とは言わない）。
  // 一般の「〜ません」→未然形＋「ない」の規則より先に処理するのだ
  [/(?:あり|ござい)ませんか$/, "ないのだ？"],
  [/(?:あり|ござい)ませんでした$/, "なかったのだ"],
  [/(?:あり|ござい)ません(?:ね|よ)?$/, "ないのだ"],
  // 上の3本に書かれていない語尾が後ろに残る形（「ありませんことよ」）。
  // 下の一般の丁寧語の常体化に落ちると活用表どおり「あらない」を作ってしまうので、
  // 不規則な常体「ない」に直してから、残った語尾を規則表に掛け直すのだ
  [
    /(?:あり|ござい)ませんでした([ぁ-ゖ]+)$/u,
    (_m, tail, off, str) => relayTail(str.slice(0, off), "なかった", tail),
  ],
  [
    /(?:あり|ござい)ません([ぁ-ゖ]+)$/u,
    (m, tail, off, str) => relayTail(str.slice(0, off), "ない", tail),
  ],
  // 敬語のラ行五段特殊活用。この5語だけ連用形が「〜り」ではなく「〜い」になるのだ
  // （「いらっしゃる／おっしゃる／なさる／くださる／ござる」）。
  // 上の「ござい」と合わせて閉じた類なので、まとめて表に持てるのだ。
  // 下のワ行五段（い段→わ）に落とすと「いらっしゃわない」という非文になるので、
  // 活用表より先に処理する
  [/(いらっしゃ|おっしゃ|なさ|くださ)いますか$/, "$1るのだ？"],
  [/(いらっしゃ|おっしゃ|なさ|くださ)います(?:ね|よ)?$/, "$1るのだ"],
  [/(いらっしゃ|おっしゃ|なさ|くださ)いました$/, "$1ったのだ"],
  [/(いらっしゃ|おっしゃ|なさ|くださ)いませんでした$/, "$1らなかったのだ"],
  [/(いらっしゃ|おっしゃ|なさ|くださ)いません(?:ね|よ)?$/, "$1らないのだ"],
  // 上の4本に書かれていない語尾が後ろに残る形（「おっしゃいましたね」「なさいましたけど」）。
  // 下の一般の丁寧語の常体化に落ちると、この5語の連用形「〜い」を普通の連用形と読んで
  // 「おっしゃいたのだ」と語幹が壊れるのだ。「ません」側にだけ受け皿があって
  // 「ます」「ました」側が開いていたのだ。過去は促音便で「〜った」なのだ
  [
    /(いらっしゃ|おっしゃ|なさ|くださ)い(ます|ました|ません)([ぁ-ゖ]+)$/u,
    (_m, kei, pol, tail, off, str) =>
      relayTail(
        str.slice(0, off),
        kei + (pol === "ます" ? "る" : pol === "ました" ? "った" : "らない"),
        tail,
      ),
  ],
  // 「ある／ござる」の過去も同じく、上の3本に無い語尾が残る形を受けるのだ
  // （「ございましたね」「ありましたけど」）。常体は不規則で「あった」なのだ
  [
    /(?:あり|ござい)ました([ぁ-ゖ]+)$/u,
    (_m, tail, off, str) => relayTail(str.slice(0, off), "あった", tail),
  ],
  // 謙譲の「いたす」（＝「する」の謙譲語）。直前は漢語サ変の語幹なので
  // （「感服いたします」＝「感服する」）、サ行五段の語幹表を引く道では拾えないのだ。
  // 表の「いた」には漢字の直前を除く番人が付いていて（漢語サ変の「〜し」を守るため）、
  // 「感服いた」がその番人に当たって既定のサ変に落ち「感服いたするのだ」になるのだ。
  // 「いたす」自体はサ行五段なので、その活用のまま常体に戻すのだ
  // （「感服いたします」→「感服いたすのだ」。「感服いたするのだ」を防ぐ）
  [/いたしますか$/u, "いたすのだ？"],
  [/いたします(?:ね|よ)?$/u, "いたすのだ"],
  [/いたしました$/u, "いたしたのだ"],
  [/いたしません(?:ね|よ)?$/u, "いたさないのだ"],
  // カ変「来る」は連用形が「来（き）」で、表層に活用語尾の仮名が現れないのだ。
  // い段の表では拾えないので、この1語だけ別に持つのだ
  // （「来ます」→「来るのだ」。無変換に落ちると「来ますのだ」という非文になる）
  // ★ 丁寧の意向形「ましょう」は「ます」の未然形＋推量の「う」で、
  // 活用の位置は「ます」とまったく同じなのだ。だから後ろに立てる終助詞も同じで、
  // 「ますね」「ますよ」が書いてあるのに「ましょうね」「ましょうよ」だけが
  // 書かれていない、という形の穴が開いていたのだ。
  // 「ましょう」を持つ枝すべてに、「ます」の枝と同じ終助詞を行き渡らせるのだ
  [/来ますか$/, "来るのだ？"],
  [/来ましょうか$/, "来るのだ？"],
  [/来ます(?:ね|よ)?$/, "来るのだ"],
  [new RegExp(`来ましょう${MASHOU_SFP}?$`), "来るのだ"],
  // テ形の直後の「き」も同じカ変「来る」なのだ（「行ってきます」「持ってきました」）。
  // テ形に続く補助動詞は曖昧さが無いので、表層だけで判別できるのだ。
  // テ形の「で」は必ず撥音便・イ音便の後に立つ（「読んで」「泳いで」）ので、
  // 直前の仮名まで見て「できます」の「で」と取り違えないようにする
  [new RegExp(`(${TE})きますか$`), "$1くるのだ？"],
  [new RegExp(`(${TE})きましょうか$`), "$1くるのだ？"],
  [new RegExp(`(${TE})きます(?:ね|よ)?$`), "$1くるのだ"],
  [new RegExp(`(${TE})きましょう${MASHOU_SFP}?$`), "$1くるのだ"],
  [new RegExp(`(${TE})きました$`), "$1きたのだ"],
  // カ変の未然形は「こ」なのだ（「行ってこない」。「行ってきない」は非文）
  [new RegExp(`(${TE})きませんか$`), "$1こないのだ？"],
  [new RegExp(`(${TE})きませんでした$`), "$1こなかったのだ"],
  [new RegExp(`(${TE})きません(?:ね|よ)?$`), "$1こないのだ"],
  // 同じく語幹が漢字で終わり、連用形に仮名が現れない一段動詞（「見ます」「出ます」）。
  // 一段動詞は開いた類だが、送り仮名を持たない語幹は漢字1字のこれだけなのだ
  [/([見出寝着似煮得経])ますか$/, "$1るのだ？"],
  [/([見出寝着似煮得経])ましょうか$/, "$1るのだ？"],
  [/([見出寝着似煮得経])ます(?:ね|よ)?$/, "$1るのだ"],
  // ★ この表には「ましょう」の枝が一本も無かったのだ。「寝ましょう」は
  // 連用形が漢字1字で終わるので上の MASU_STEM_CLASS の枝には入れず、
  // 「寝ましょうなのだ」と丁寧の意向形を抱えたまま断定が接がれていたのだ
  [new RegExp(`([見出寝着似煮得経])ましょう${MASHOU_SFP}?$`), "$1るのだ"],
  // 助動詞の「みたい」（「猫みたいです」）は形容動詞型なので「みたいなのだ」、
  // マ行五段の連用形＋願望の「たい」（「休みたい」「飲みたい」）は形容詞なので
  // 「休みたいのだ」なのだ。表層はどちらも「みたい」で同じだが、
  // 分かれ目は「み」がマ行五段の活用語尾かどうかの一点なのだ。
  // それは活用表そのものが答えを持っているので、マ行の語幹表を引いて分けるのだ
  // （「休／飲／読」は表にあり、「してる／猫」は無い）。
  // ★ 「み」が活用語尾になる道はもう一つあるのだ。上一段の連用形なのだ
  // （「試みたい」「顧みたい」）。中でもテ形の直後の「み」は補助動詞「みる」と
  // 決まるのだ（「見てみたい」「読んでみたい」「やってみたい」）。
  // 比況の「みたい」は体言に付く助動詞なので、テ形の直後には立てないからなのだ。
  // その「て」「で」は既に上一段の語幹表（ICHIDAN_STEMS.み）に載っているので、
  // 一段の側にも同じ問いを投げれば分かれるのだ
  [
    /みたい(?:です|だ)?(?:よね|よな|ね|よ|わ)?$/u,
    (_m, off, str) =>
      isGodan("み", off, str) || isIchidan("み", off, str)
        ? "みたいのだ"
        : "みたいなのだ",
  ],
  //
  // 数詞＋助数詞（「5さい」「3こ」）を体言として扱う規則も置かないのだ。
  // 助数詞は閉じた類ではなく、数字の直後の仮名1〜2字を機械的に助数詞とみなすと
  // 「18です」「7から」「300でも」の助動詞・助詞まで数詞の一部として飲み込んで
  // 「18ですなのだ」「7からなのだ」という非文を作るからなのだ。
  //
  // 引用の助詞「と」＋形式動詞「いう」は接続表現で、文末の言い切りではない
  // （「というか」「ってか」）。末尾の「か」を疑問の終助詞と読むと文が分断されるのだ
  [/(?:と|って)いうか$/u, "$&"],
  [/ありがとうございます$/, "ありがとうなのだ"],
  [/ありがとうございました$/, "ありがとうなのだ"],
  // 「〜でございます」は丁寧な断定なので「なのだ」に落とす
  [/でございます$/, "なのだ"],
  [/でございました$/, "だったのだ"],
  // 挨拶・呼びかけの「〜ございます」は「ある」の丁寧形ではないので
  // 「おはようございます」→「おはようあるのだ」にしてはいけないのだ。
  // 「ござる」もラ行の特殊活用で連用形が「ござい」なのだ。下の活用表に落とすと
  // 「ございたのだ」という非文になるので、ここで畳んでおく
  [/ございます$/, "なのだ"],
  [/ございました$/, "だったのだ"],
  // 末尾が「だ」でも断定ではない副詞。断定の「だ」ルールに食われて
  // 「まだ」→「まなのだ」になるのを防ぐ
  [/(まだ|いまだ|ただ|とんだ)$/, "$&なのだ"],

  // --- 五段動詞の音便＋過去の「んだ」「いだ」。説明の「んだ」より先に処理する ---
  // 説明の「んだ」の直前は必ず仮名（「行くんだ」「そうなんだ」）なので、
  // 漢字の直後の「んだ／いだ」は過去形とみなす（「読のだ」「泳いなのだ」を防ぐ）
  [/([一-龯々])んだ(?:よね|よな|よ|ね|な|ぜ|ぞ|わ|もん)?$/, "$1んだのだ"],
  [/([一-龯々])いだ(?:よね|よな|よ|ね|な|ぜ|ぞ|わ|もん)?$/, "$1いだのだ"],
  // 仮名で書かれた語幹の撥音便＋過去（「ウイスキーのんだ」「本をよんだ」）。
  // 漢字の手掛かりが無いので、マ・バ・ナ行五段の語幹表を引いて過去形と決めるのだ。
  // 表に無ければ説明の「んだ」（「そうなんだ」）として下の nd に落ちる
  [
    new RegExp(
      `(?:${ONBIN_N_STEMS.join("|")})んだ(?:よね|よな|よ|ね|な|ぜ|ぞ|わ|もん)?$`,
      "u",
    ),
    (m) => m.replace(/んだ(?:よね|よな|よ|ね|な|ぜ|ぞ|わ|もん)?$/u, "んだのだ"),
  ],

  // 補助動詞「〜ている」の口語縮約「〜てる」は、説明の「ん」の前で「てん」に縮むのだ
  // （「キレられてんだよ」＝「キレられてるんだ」）。表層の「ん」は「る」の変化形なので、
  // 「る」に戻してから「のだ」を付けるのだ（「キレられてんなのだ」を防ぐ）。
  // 推量「だろう」が続く形（「訓練受けてんだろなー」＝「受けてるんだろう」）も
  // 同じ縮約なのだ。「て」はどの用言の類にも属さない仮名なので、
  // 下の nd（用言の終止形＋「ん」）では拾えないのだ。
  // ★ 「て」「で」の字が見えただけではテ形ではないのだ。仮名書きの体言の途中にも
  // 同じ字は現れるからなのだ（「うんてん」「かでん」「せんでん」）。
  // これを縮約と読むと「うんてるのだ」と語幹を削って壊すのだ。
  // テ形を作れる形が直前にあるかを TE_CONTRACT で見張って分けるのだ
  // ★ 「っ」の直後の「てん」には、その縮約とは別のものが混ざっているのだ。
  // 引用の助詞「って」＋形式動詞「言う」の縮約なのだ
  // （「しろってんだ」＝「しろというのだ」「なんだってんだ」＝「何だというのだ」）。
  // 見分けは「っ」が何なのかの一点なのだ。補助動詞の側の「っ」は五段動詞の促音便で、
  // 引用の側の「っ」は助詞「って」の一部なのだ。
  // 促音便を起こすのはラ行・タ行・ワ行の五段だけなので、「っ」の手前がその3行の
  // 語幹かを活用表に問えば分かれるのだ（「行っ」「待っ」「やっ」「知っ」は表にあり、
  // 「しろっ」「なんだっ」「するっ」は無いのだ）。
  // 引用の「って」は引用される文（命令形・終止形・断定）に直に付くので、
  // テ形が立てない位置なのだ。表が「促音便ではない」と答えたらそちらなのだ
  [
    /ってんだ(?:よね|よな|よ|ね|な|ぜ|ぞ|わ|もん)?$/u,
    (m, off, str) =>
      ["り", "ち", "い"].some((c) => isGodan(c, off, str))
        ? RULE_PASS
        : "というのだ",
  ],
  [new RegExp(`${TE_CONTRACT}んだろう?(?:ね|よ|な|なあ)?$`, "u"), "$1るのだ"],
  [
    new RegExp(`${TE_CONTRACT}んだ(?:よね|よな|よ|ね|な|ぜ|ぞ|わ|もん)?$`, "u"),
    "$1るのだ",
  ],
  // ★ 説明の「ん」に断定「だ」を伴わず終助詞だけが付いた形もあるのだ
  // （「熊出るようになってんな」＝「なってるんだな」の「だ」落ち、「知ってんね」）。
  // 下の nd には「ん」＋断定（nd("だ…")）と「ん」＋終助詞だけ
  // （nd("(?:よね|よな|ね|な|よ|わ)")）の2本が並んでいるのに、
  // テ形の縮約の側は「んだ」の1本しか無かったのだ。
  // 「て」はどの用言の類（YOGEN）にも属さない仮名なので、nd の側では拾えないのだ。
  // 拾えていなかったせいで「なってんななのだ」と縮約を抱えたまま断定が接がれていたのだ。
  // 番人は上の「んだ」とまったく同じ TE_CONTRACT なのだ——直前がテ形を作れる形
  // （促音便・イ音便・一段の連用形・漢字語幹）でなければ、それは仮名書きの体言の
  // 途中の「て」なのだ（「うんてんな」「せんでんな」「かでんな」）
  [
    new RegExp(`${TE_CONTRACT}ん(?:よね|よな|よ|ね|な|ぜ|ぞ|わ)$`, "u"),
    "$1るのだ",
  ],

  // --- 「ん」＋断定（んです/んだ 系）。「です」「だ」より先に処理する ---
  // 疑問の終助詞「か」の後ろにも終助詞は重ねられるのだ（「〜んですかね」
  // 「〜んですかねぇ」）。落とさないと「か」だけが畳まれて「いうんですのだ？」と
  // 丁寧形が残るのだ。「ね」は問いかけを和らげるだけで意味を足さないので落とすのだ
  nd("ですか(?:ねえ|なあ|ね|よ|な)?", "$1のだ？"),
  // 「〜んでしょう」は推量なので「のだろう」に開く。終助詞「ね」は残す
  // （「安定してるんでしょうねぇ」→「安定してるのだろうねぇ」）
  nd("でしょうね", "$1のだろうね"),
  nd("でしょう", "$1のだろう"),
  // 疑問詞「なん（何）」の「ん」は語の一部で、説明の「ん」ではないのだ。
  // 下の nd に食われると「何」が消えて「なのだろう」になってしまうので先に畳む。
  // ただし「何なんだろう」のように疑問詞の後ろにもう一つ「ん」が立つ形は、
  // そちらが説明の「ん」なので、この番人からは外して nd に流すのだ
  [/(?<!何|なん)(なん|何)だろう?$/u, "$1なのだ"],
  // 常体の推量「〜んだろう」も同じ形なのだ（「何なんだろう」→「何なのだろう」）。
  // 下の裸の「だろう」→「なのだ」に食われると説明の「ん」が残って
  // 「何なんなのだ」と重なってしまうので、ここで先に畳むのだ
  // 終助詞「な」「なあ」「よ」の付いた形も同じなのだ（「自覚してしまうんだろうな」）。
  // 落とさずに下の裸の「だろう」に流すと説明の「ん」が残って
  // 「してしまうんなのだ」になるのだ
  nd("だろうか", "$1のだろうか"),
  nd("だろうね", "$1のだろうね"),
  nd("だろう?(?:なあ|な|よ)?", "$1のだろう"),
  // 終助詞は「よね」のように2つ重ねられるので、まとめて落とすのだ
  // （「入ったんですよね」→「入ったのだ」。「入ったんなのだ」を防ぐ）
  nd("です(?:よね|よな|わね|よ|ね|わ)?", "$1のだ"),
  nd("だよね", "$1のだ"),
  // 理由の「〜んだから」（＝「〜のだから」）。断定「だ」の後ろの「から」は
  // 接続助詞ではなく理由を押し出す言いさしで、文はそこで終わっているのだ
  // （「一番だいすきなんだからね」→「一番だいすきなのだ」）
  nd("だから(?:ね|よ|な|なあ|さ)?", "$1のだ"),
  // 「〜んだけどね」「〜んですけどぉ」。終助詞は落とさずに残す
  // （落とすと「楽しいのだけど」と逆接で終わって座りが悪いのだ）
  nd("だけど(ね|よ|な)?", "$1のだけど$2"),
  nd("ですけど(ね|よ|な)?", "$1のだけど$2"),
  // 終助詞は「よね」「よな」「わね」のように2つ重ねられる。1つしか許さないと
  // 「あるんだよな」が「あるんなのだ」と撥音を残したまま壊れるのだ
  // 逆接の言いさし「〜んだが」「〜んですが」。後ろに続くはずの節が省かれた形で、
  // 文はそこで終わっているのだ（「上がってるんだが」）。
  // 「が」を残すと下の助詞止めの番人に落ちて文全体が無変換になってしまう
  nd("だが", "$1のだ"),
  nd("ですが", "$1のだ"),
  // 断定「だ」＋接続助詞「し」の言いさしも同じ形なのだ（「集まってる集団だし」）。
  // 「し」は本来もう一つの節を並べる助詞で、その節が省かれて文がそこで終わっているのだ。
  // 「〜んだが」「〜んだけど」とまったく同じ言いさしなので、同じ場所で同じ形に畳むのだ
  nd("だし", "$1のだ"),
  // 説明の「ん」＋丁寧の過去「でした」。常体は「のだった」なのだ
  // （「行ったんでした」→「行ったのだった」）。
  // 「ん」を残すと「行ったんだったのだ」と説明の「ん」と断定が重なるのだ。
  // 確認の「っけ」が付く形は下の「〜んだっけ」とまったく同じ自問なので、
  // 同じように疑問符を添えるのだ（「出るんでしたっけね」→「出るのだったっけ？」）
  nd("でしたっけ(?:ねえ|なあ|ね|よ|な)?", "$1のだったっけ？"),
  nd("でした(?:ねえ|なあ|ね|よ|な)?", "$1のだった"),
  // 疑問詞「なん（何）」の「ん」は語の一部で、説明の「ん」ではないのだ。
  // 下の nd に食われると「何」が消えて「なのだっけ？」になってしまうので先に畳む
  [/(なん|何)だっけ$/u, "$1なのだっけ？"],
  // 終助詞「な」の付いた「〜んだっけな」は自分に思い出させる自問なので、
  // 疑問符は付けないのだ（「表現するんだっけな」→「表現するのだっけ」）。
  // 「な」を残すと「のだっけななのだ」と終助詞が重なるのだ
  nd("だっけ(?:なあ|な)", "$1のだっけ"),
  // 確認の「〜んだっけ」（「行ったんだっけ」→「行ったのだっけ？」）
  nd("だっけ", "$1のだっけ？"),
  // 方言・老人語の断定「じゃ」は「だ」と同じ働きなのだ
  // （「かつてはそうじゃったんじゃ」→「そうじゃったのだ」）
  nd("じゃ", "$1のだ"),
  // 関西の断定「や」は共通語の「だ」に対応するのだ。だから説明の「ん」＋「や」は
  // 「んだ」＝「のだ」とまったく同型で、同じように畳めるのだ
  // （「進むんや」→「進むのだ」「お前が怒られてるんやないんや」→「〜ないのだ」）。
  // 関西では終助詞の「で」「わ」「ねん」が断定の後ろに立つ（「ええんやで」）ので
  // 一緒に落とすのだ
  nd("や(?:で|わ|ねん|よ|ね|な|なあ)?", "$1のだ"),
  // ★ 関西の推量「やろ」は共通語の「だろ（う）」に対応するのだ。断定「や」＝「だ」の
  // 未然形＋推量という組み立てまで共通語とまったく同じなのだ。
  // だから説明の「ん」＋「やろ」は「んだろう」＝「のだろう」と同型で、
  // 上の nd("だろう…") の並びにそのまま対を置けるのだ
  // （「なんでこんなにカロリー少ないんやろか」→「〜少ないのだろうか」）。
  // 上の nd("や…") では拾えないのだ。あちらの終助詞の並びに「ろ」は無く、
  // 「ろ」は終助詞ではなく推量の助動詞の一部だからなのだ。
  // 拾えていなかったせいで「少ないんやろかなのだ」と語尾を抱えたまま断定が
  // 接がれていたのだ。
  // 「か」の後ろの「な」は詠嘆の終助詞なので一緒に落とすのだ（「か」＋「な」＝「かな」）。
  // ★ 疑問詞「なん（何）」の「ん」は語の一部で、説明の「ん」ではないのだ。
  // 上の「なんだろう」に置いてある番人とまったく同じものが「やろ」にも要るのだ。
  // 置かないと nd が「な」を説明の「ん」の直前と読んで「なん」の「ん」ごと削り、
  // 「なんやろ」→「なのだろう」と疑問詞が消えてしまうのだ。
  // 「何なんやろ」のように疑問詞の後ろにもう一つ「ん」が立つ形は、そちらが
  // 説明の「ん」なので番人から外して nd に流すのも上とまったく同じなのだ
  [/(?<!何|なん)(なん|何)やろ(?:か)?(?:なあ|な)?$/u, "$1なのだ"],
  nd("やろか(?:なあ|な)?", "$1のだろうか"),
  nd("やろ(?:なあ|な|ね|よ)?", "$1のだろう"),
  // 「〜っす」は「です」の口語形なので、丁寧語と同じに畳む
  // （「あるんすか」→「あるのだ？」「無理っす」→「無理なのだ」）。
  // 「です」と同じ位置に立つのだから、終助詞の付き方も「です」と同じなのだ
  // （「思うんすよね」＝「思うんですよね」）。上の nd("です…") と対にしておくのだ
  nd("すか(?:ねえ|なあ|ね|よ|な)?", "$1のだ？"),
  nd("す(?:よね|よな|わね|よ|ね|わ)?", "$1のだ"),
  // ★ 「にゃ」は終助詞「な」の猫語形なのだ（「そうなんだにゃ」）。
  // 「な」とまったく同じ位置——断定「だ」の直後——にしか立たないので、
  // 「な」の並びにそのまま足せるのだ。
  // 「にゃ」で終わる体言（「こんにゃく」「にゃんにゃん」）と字形が重なるが、
  // ここは断定「だ」の直後という位置に限っているので巻き込まないのだ
  nd("だ(?:よね|よな|わね|わな|よ|ね|な|にゃ|わ|もん)", "$1のだ"),
  nd("だ", "$1のだ"),
  // 説明の「ん」に断定を伴わず終助詞だけが付いた形（「無くなってるんよな」）。
  // 「だ」系より後に置かないと「〜んだよ」を横取りしてしまう
  nd("(?:よね|よな|ね|な|よ|わ)", "$1のだ"),

  // --- 補助動詞「〜ている」の否定（活用表より先に処理する） ---
  // 「〜ています」の「い」は上一段「いる」の連用形なので、未然形もそのまま「い」なのだ
  // （「食べていません」→「食べていないのだ」）。
  // テ形の直後の「います」は必ず補助動詞なので、この形は表層だけで判別できるのだ
  [/([てで])いませんか$/, "$1いないのだ？"],
  [/([てで])いませんでした$/, "$1いなかったのだ"],
  [/([てで])いません(?:ね|よ)?$/, "$1いないのだ"],

  // --- 疑問（長い語尾を先に） ---
  [new RegExp(`(${MASU_STEM_CLASS})ましたか$`), mashita("のだ？")],
  [/ましたか$/, "たのだ？"],
  // 「〜ません」は連用形＋丁寧の否定。常体の「ない」は未然形に付くので、
  // 五段は連用形（い段）を未然形（あ段）に戻してから付ける
  // （「行きませんか」→「行かないのだ？」。「行きないのだ」を防ぐ）
  [new RegExp(`(${MASU_STEM_CLASS})ませんか$`), nai("ないのだ？")],
  [/ませんか$/, "ないのだ？"],
  [/([てで])いますか$/, "$1いるのだ？"],
  [new RegExp(`(${MASU_STEM_CLASS})ますか$`), masu("のだ？")],
  [new RegExp(`(${MASU_STEM_CLASS})ましょうか$`), masu("のだ？")],
  // 断定の「な」・準体助詞の「の」＋常体の推量「だろう（か）」。
  // 「なの」「〜るの」はそれ自体が言い切りの一部なので、残したまま断定を足すと
  // 「問題なのなのだ」「そうするのなのだ」と断定が二重になるのだ。
  // 「〜なのでしょう」を「なのだ」に畳むのとまったく同じ形なのだ。
  // 疑問符は付けないのだ。「〜のだろうか」は自分に問う形で、
  // 疑問符を付けると他人への問いかけに意味が変わってしまうからなのだ
  // 準体助詞の「の」は用言の連体形に付くのだ。体言の末尾の「の」（「もの」「私の」
  // 「ここの」）と字形が同じなので、直前を活用表に問うて分けるのだ。
  // 分けないと「そういうものだろう」の「もの」を「も」＋準体助詞と読んで
  // 「そういうものだ」と断定が抜けた形になるのだ
  [
    /(な?)のだろう(?:か|ね|よ)?$/u,
    (m, na, off, str) =>
      na === "な" || isYogenEnd(str.slice(0, off)) ? na + "のだ" : "のなのだ",
  ],
  // 用言に続く「でしょうか/だろうか」は「な」を挟まない。
  // 用言かどうかは字形では決まらないので活用表に問うのだ
  // （「いつでしょうか」の「つ」はタ行の表に無いので体言なのだ）
  // 仮名語幹の「〜い」は表では決着しないのだ。承認版はここを字形の類（YOGEN）で
  // 用言に倒していたので、決着しない語では同じ「のだ？」を返すのだ
  [/でしょうか$/u, yogenSplit("のだ？", "なのだ？", "のだ？")],
  // 準体助詞「の」＋丁寧語（「あかんのですか」→「あかんのだ？」）。
  // 「の」を残したまま「なのだ」を付けると「あかんのなのだ」になるのだ
  [/のですか$/, "のだ？"],
  // 用言＋です（「高いですか」→「高いのだ？」。「高いなのだ」を防ぐ）。
  // ここは「でしょう」「だろう」と違って活用表に問うていないのだ。
  // 理由は下の「です」の項に書いてあるのだ
  yr("ですか", "$1のだ？"),
  [/ですか$/, "なのだ？"],
  [/だろうか$/u, yogenSplit("のだ？", "なのだ？", "のだ？")],
  // 用言＋「かどうか」は疑問の従属節なので「のだろうか」に開く
  // （「終わるかどうかなのだ」のような途中で切れた形を防ぐ）
  yr("かどうか", "$1のだろうか"),
  [/かどうか$/, "かどうか"], // 用言以外は判別できないので無変換
  // 「かしら」は終止形・体言のどちらにも付く。直前が断定の「な」・準体助詞の「の」なら
  // それは既に言い切りの一部なので、重ねずに「のだ」へ畳むのだ
  // （「〜なのかしら」→「〜なのだ？」。「〜なののだ？」を防ぐ）
  [/なのかしら$/, "なのだ？"],
  [/のかしら$/, "のだ？"],
  yr("かしら", "$1のだ？"),
  [/かしら$/, "なのだ？"],
  // 意向形＋「かな」は「行こうかな」の形で活用が復元できないので触らない
  // （「変えようかなあ」→「変えようのだ？」のような破壊を防ぐ）
  [/[おこごそぞとどのほぼもろよ]うか(?:なあ|な)?$/, "$&"],
  // 「い」で終わる体言（形式名詞・複合語）＋「か」。表層は形容詞の終止形と同じなので、
  // 下の用言＋「か」に食われて「おなかいっぱいのだ」になってしまうのだ。
  // 体言なので「なのだ」を挟むのだ（数え上げは下の体言リストと同じ閉じた類）
  [/(いっぱい|一杯|のせい|の所為|はず|筈|お願い|おねがい)か(?:なあ|な)?$/u, "$1なのだ"],
  // ★ 形式名詞＋終助詞「か」（「そういうことか」「4時間弱ってとこか」「そういうわけか」）。
  // 下の体言＋「か」は 漢字・カタカナで終わる語にしか掛からないのだ。仮名だけで
  // 書かれた体言は「いか」「すいか」「みっか」「ほのか」のように「か」までで1語の
  // ことがあって、終助詞の「か」と切り分けられないからなのだ。
  // ところが形式名詞は仮名で書かれるのが普通なので、その網から丸ごと漏れているのだ。
  // 形式名詞は連体修飾を受けて初めて立つ体言で、それ自体では何も指さない語なのだ。
  // 数は決まっていて新語が入らない閉じた類なので、語として数え上げれば開けるのだ
  // （前部の連体修飾のほうは開いた類だが、こちらは数え上げられる側なのだ）。
  // ★ 「もの」は外すのだ。「〜ものか」は反語で強い否定を表すので、疑問に開くと
  // 意味が反転するからなのだ（下に「もんか」の規則を置いていないのと同じ理由なのだ）。
  // ★ 「つもり」「あたり」「かわり」はラ行の連用形なので、下の「〜り＋か」が
  // 既に受けているのだ。ここに重ねて書く要は無いのだ。
  // ★ 仮名で「〜ことか」と書かれた別の語（「まことか」＝誠か、「たわけか」＝戯けか、
  // 「おとこか」＝男か）まで拾うが、それも体言なので「なのだ」を挟む答えは同じなのだ
  [
    /(こと|とこ|ところ|わけ)か(?:なあ|な)?$/u,
    (_m, c, off, str) => c + (QWORD.test(str) ? "なのだ？" : "なのだ"),
  ],
  // 副助詞「とか」「なんか」「なんて」の直後の「か」は語の一部ではなく終助詞なのだ
  // （「アマプラ版とかか」）。落とさないと「とかかなのだ」と「か」が二重に残る
  [
    /(?:とか|なんか|なんて)か(?:なあ|な)?$/u,
    (m, off, str) =>
      m.replace(/か(?:なあ|な)?$/u, "") + (QWORD.test(str) ? "なのだ？" : "なのだ"),
  ],
  // 確認の「じゃん」＋「か」（「ふつうの町のコンビニじゃんか」）。
  // 下の口語否定「ん」＋「か」に食われると「じゃんのだ？」という非文になるのだ。
  // 「じゃん」は既に言い切りなので、単独の「じゃん」と同じ扱いに畳むのだ
  yr("じゃんか", "$1のだ"),
  [/じゃんか$/u, "なのだ"],
  // 説明の「の」＋「かな」。先に処理しないと「の」だけ残って
  // 「いったののだ？」と重複するのだ。
  // 準体助詞「の」を伴う「のか」「のかな」は、聞き手に説明を求める形なので
  // 疑問符を付けたままにするのだ（「〜じゃない鯖なのか」「あるのかな」）
  [/のか(?:なあ|な)$/, "のだ？"],
  [/のか$/, "のだ？"],
  // 「〜かな」「〜かい」は用言の終止形に付いた時だけ疑問として開く。
  // 直前の活用が崩れている形（「どうすっかな」「あんのんかい」）は終止形を
  // 復元できないので、削らずに無変換へ逃がす（番人）。
  // 準体助詞を挟まない裸の「かな」は自分に向けた推量で、聞き手への問いではないのだ
  // （「そんなに無視するかなあ」）。だから疑問符は原文の句読点と疑問詞に委ねるのだ
  [
    new RegExp(`(${YOGEN})かな(?:あ)?$`),
    (_m, c, off, str) => c + (QWORD.test(str) ? "のだ？" : "のだ"),
  ],
  // ★ 裸の「かな」の番人（無変換）は、この位置ではなく体言＋「か」の並びの
  // 後ろに移したのだ。「かな」は疑問の終助詞「か」＋詠嘆の「な」なので、
  // 「か」を受けられる語はそのまま「かな」も受けられるのだ。ところが番人が
  // 用言の直後にしか置かれていなかったので、体言＋「かな」（「ドロップアイテムかな」
  // 「終わりかな」「6時かな」）が一つ残らずここで打ち切られていたのだ。
  // 体言側の「か」の規則はどれも自前の番人（漢字・カタカナで終わること、
  // 形容動詞語幹の除外）を持っているので、そこまで降ろしても仮名だけの語
  // （「そうかな」「いいかな」「どうかな」）は開かないのだ
  yr("かい", "$1のだ？"),
  [/かい$/, "$&"],
  // 方言の疑問「〜かや」も同じ扱い
  yr("かや", "$1のだ？"),
  // 詠嘆の「〜かあ」は問いかけではないので終助詞だけ落とす（「6時かあ」→「6時なのだ」）
  yr("かあ", "$1のだ"),
  [/かあ$/, "なのだ"],
  // 前の節から読点で切り離された裸の「か」は、付く先の述語を持たないのだ
  // （「楽しく仕事しようよ、か…」は引用の反芻）。終助詞として畳めないので触らない
  [/[、，][\s]*か$/u, "$&"],
  // 用言の終止形＋終助詞「か」は「か」を落として言い切りにするのだ
  // （「あかんかのだ」を防ぐ）。ただし疑問符は付けないのだ。
  // 終止形に直に付く「か」は他人への問いかけではなく、自分に言い聞かせる意志・自問
  // （「今日はこのへんにしておくか」「30%も寝るか」「見とくか」）か、
  // 気づきの詠嘆であることが多く、「のだ？」にすると意味が問いかけに反転するからなのだ。
  // 本当に問いかけたい時は書き手が「？」を打つのだ。その「？」は文の区切り記号として
  // 出力に残るので、疑問文は疑問文のまま出るのだ（「行くか？」→「行くのだ？」）。
  // 疑問符を付けるかどうかの判断を、こちらで推測せず原文の句読点に委ねるのだ。
  // 念押しの「かね」だけは問いかけにしか使わないので疑問符を付ける。
  // 文中に疑問詞があれば答えを求める真の疑問文なので、その時も疑問符を付けるのだ
  [new RegExp(`(${YOGEN})かね$`), "$1のだ？"],
  [
    new RegExp(`(${YOGEN})か$`),
    (_m, c, off, str) => c + (QWORD.test(str) ? "のだ？" : "のだ"),
  ],
  // 説明の「ん」＋「か」（「メモリ容量足りるんかね」→「足りるのだ？」）。
  // 直前が用言の終止形なら説明の「ん」（＝「の」）なのだ。口語否定の「ん」は
  // 未然形（あ段）に付くので、この条件で取り違えないのだ
  [new RegExp(`(${YOGEN})んか(?:ね)?$`), "$1のだ？"],
  // ラ行五段の未然形＋口語否定「ん」＋「か」は、下の「らん」と同じく常体に戻すのだ
  // （「そんな変わらんか」→「そんな変わらないのだ」）。
  // 疑問符を付けないのは用言＋「か」と同じ理由なのだ。ラ行の否定に付く「か」は
  // 相手への問いではなく自分で確かめる自問（「変わらんか」「知らんか」）だからなのだ。
  // 念押しの「かね」だけは問いかけにしか使わないので疑問符を付ける
  [/らんかね$/u, "らないのだ？"],
  [/らんか$/u, (_m, off, str) => (QWORD.test(str) ? "らないのだ？" : "らないのだ")],
  // 口語否定の「ん」＋終助詞「か」も同じ疑問（「あかんか」→「あかんのだ？」）。
  // ★ この規則は「ん」を残して「のだ？」を接ぐので、直前の「ん」が
  // 口語否定の「ん」であることを確かめなければならないのだ。字形だけで通すと
  // 体言の末尾の「ん」（「みかちゃん」「ひゃくまん」「ラーメン」）まで
  // 否定に見えて、体言に「な」を挟まない非文になるのだ
  // （「みかちゃんか！」→「みかちゃんのだ！」）。
  // 上の (YOGEN)んか が説明の「ん」を先に取っているので、ここに落ちてくるのは
  // 口語否定の「ん」か体言の末尾の「ん」のどちらかなのだ。
  // 分けられるのは活用表だけなので、下の字形の判定と同じ述語に問うのだ。
  // 表が否定だと答えなければ、その「ん」は体言の末尾なのだ。「ん」を語に残したまま
  // 終助詞の「か」だけを落として「なのだ」を接ぐのだ（「おなかいっぱいか」→
  // 「おなかいっぱいなのだ」・「気のせいか」→「気のせいなのだ」と同じ扱いなのだ）。
  // 疑問符を付けないのも同じ理由なのだ——体言に直に付く「か」は問いかけではなく
  // 自問・詠嘆で、問いたい時は書き手が「？」を打つのだ。
  // ★ 降ろす（RULE_PASS）のでは駄目なのだ。「んか」を受ける規則は下に無く、
  // 最後の字形の判定まで落ちると終助詞ごと「なのだ」を接いで
  // 「みかちゃんかなのだ」になるからなのだ
  [
    /んか(?:ね)?$/u,
    (_m, off, str) =>
      isColloquialN(str.slice(0, off + 1)) ? "んのだ？" : "んなのだ",
  ],
  // 「〜もんか」だけを取り出して疑問に開く規則は置かないのだ。「行くもんか」は
  // 反語で強い否定を表すので、疑問形にすると意味が反転してしまうからなのだ
  // 文末の「しか」に「ないのだ」を補う規則も置かないのだ。副助詞の「しか」と、
  // 語の一部の「しか」（「たしか」「やむなし＋か」「鹿」）は表記で区別できず、
  // 「名前はたしか」→「たしかないのだ」のような非文を作るからなのだ
  // 文語の否定「なし」（＝「ない」）＋「か」は詠嘆・反語の言いさしで、言い切りでは
  // ないのだ（「値上げもやむなしか」）。「か」を落とすと反語が疑問に変わり、
  // 残したまま体言扱いにすると「やむなしかなのだ」という非文になるので触らない。
  // 「たしか」のような形容動詞語幹と区別できるのは「なし」の形をしている時だけなのだ
  [/なしか$/u, "$&"],
  // ラ行五段の連用形「〜り」は体言として使われる（「あり」「つもり」「終わり」）。
  // その直後の「か」は語の一部ではなく終助詞なので、落として疑問形にするのだ
  // （「というのはありか」→「というのはありなのだ？」）。
  // 「〜り」で終わる形容動詞語幹はほとんど無いので、い段全体（「たしか」の「し」、
  // 「どうにか」の「に」）に広げず、ラ行だけに限るのだ。
  // 「ありか」は可否を問う慣用の言い回しで、独り言ではなく相手に判断を求める形なのだ。
  // だからその1語だけは疑問符を付けるのだ。慣用句でない「〜り」（「秋の始まりか」
  // 「終わりか」）は気づきの詠嘆なので、他の「か」と同じく原文の句読点に委ねるのだ
  [
    /([ぁ-ゖ]り)か(?:ね|なあ|な)?$/u,
    (_m, c, off, str) =>
      c + (c === "あり" || QWORD.test(str) ? "なのだ？" : "なのだ"),
  ],
  // 体言＋終助詞「か」も「か」を落とすのだ（「映画かなのだ」を防ぐ）。
  // 漢字1文字でも同じことなのだ（「ああ声優の方か」→「声優の方なのだ」）。
  // 巻き込みたくないのは「静か」「確か」のように「か」までが1語の形容動詞語幹で、
  // これは新語の作られない閉じた類なので数え上げられるのだ。
  // 「明らか」「柔らか」のように送り仮名を挟む形も同じく語の一部なので除く。
  // 疑問符を付けないのは用言＋「か」と同じ理由なのだ。体言＋「か」は
  // 気づき（「ああ声優の方か」「もうこんな時間か」）であることが多いので、
  // 疑問符の有無は原文の句読点と疑問詞に委ねるのだ
  [
    /([一-龯々])(?<!静|確|愚|厳|温|細|豊|密|僅|微|遥|円|定|疎|柔ら|明ら|滑ら|平ら|安ら|清ら|大ま|細ま|穏や|爽や|鮮や|健や|速や|賑や|和や|冷や)かね$/u,
    "$1なのだ？",
  ],
  [
    /([一-龯々])(?<!静|確|愚|厳|温|細|豊|密|僅|微|遥|円|定|疎|柔ら|明ら|滑ら|平ら|安ら|清ら|大ま|細ま|穏や|爽や|鮮や|健や|速や|賑や|和や|冷や)か(?:なあ|な)?$/u,
    (_m, c, off, str) => c + (QWORD.test(str) ? "なのだ？" : "なのだ"),
  ],
  // カタカナ語＋ひらがなの「か」も同じく体言＋終助詞。カタカナ語の内部に
  // ひらがなは現れないので、この「か」は必ず語の外側の終助詞なのだ
  // （「カウンセリングか」→「カウンセリングなのだ」）
  [/([ァ-ヺ][ァ-ヺーヽヾ]+)かね$/u, "$1なのだ？"],
  [
    /([ァ-ヺ][ァ-ヺーヽヾ]+)か(?:なあ|な)?$/u,
    (_m, c, off, str) => c + (QWORD.test(str) ? "なのだ？" : "なのだ"),
  ],
  // ★ ラテン文字・数字で終わる語＋ひらがなの「か」も同じく体言＋終助詞なのだ
  // （「平均13t/sか」「GitHubか」）。理屈はカタカナ語とまったく同じで、
  // ラテン文字・数字の内部にひらがなは現れないのだから、その直後の「か」は
  // 必ず語の外側の終助詞なのだ。表記の類が違うだけで同じ規則なのだ
  [/([A-Za-z0-9０-９][A-Za-z0-9０-９/.\-+%％]*)かね$/u, "$1なのだ？"],
  [
    /([A-Za-z0-9０-９][A-Za-z0-9０-９/.\-+%％]*)か(?:なあ|な)?$/u,
    (_m, c, off, str) => c + (QWORD.test(str) ? "なのだ？" : "なのだ"),
  ],
  // ★ 裸の「かな」の番人はここなのだ（上の「かい」の項に理由を書いてあるのだ）。
  // ここまで降りてきた「かな」は、用言でも 漢字・カタカナ・ラテン文字で終わる
  // 体言でもない——つまり仮名だけで書かれた語の直後なのだ（「そうかな」「いいかな」
  // 「どうかな」「だめかな」）。「か」までで1語なのか終助詞なのかが表記から
  // 読めないので、承認版と同じく無変換に留めるのだ
  [/かな(?:あ)?$/, "$&"],

  // --- 丁寧語 ---
  // 丁寧の過去否定「〜ませんでした」は常体では「〜なかった」。
  // 「でした」の規則に食われて「〜ませんだったのだ」になるのを防ぐのだ
  [new RegExp(`(${MASU_STEM_CLASS})ませんでした$`), nai("なかったのだ")],
  [/ませんでした$/, "なかったのだ"],
  [/でした$/, "だったのだ"],
  // 丁寧の過去「〜ました」は常体では「〜た」。五段は連用形が音便形に変わるので
  // 表で引いてから付けるのだ（「書きました」→「書いたのだ」。「書きたのだ」を防ぐ）
  [new RegExp(`(${MASU_STEM_CLASS})ました$`), mashita("のだ")],
  [/ました$/, "たのだ"],
  [new RegExp(`(${MASU_STEM_CLASS})ません(?:ね|よ)?$`), nai("ないのだ")],
  [/ません$/, "ないのだ"],
  // ★ 「ましょう」＋終助詞（「がんばりましょうよ」）をここに1本ずつ書く要は無いのだ。
  // 下の「語尾の一般化」（relayTail）に「ましょう」を入れてあるので、
  // 丁寧の意向形を終止形に落としたあと、残った終助詞は常体の規則が受け持つのだ。
  // 実測したのだ——ここに終助詞つきの枝を足しても、連用形の表で引ける語幹
  // 12語×終助詞12種の144通りで出力は1つも変わらなかったのだ。
  // 組み合わせを1つずつ足すのは数合わせなので置かないのだ
  [new RegExp(`(${MASU_STEM_CLASS})ましょう$`), masu("のだ")],
  [/([てで])います[よね]?$/, "$1いるのだ"],
  // 理由の「〜ますから」は理由だけを言い残す言いさしで、文はそこで終わっているのだ
  // （「今日はゲームやらせていただきますからね」）。丁寧形を常体に戻して畳むのだ。
  // 「から」を残すと下の「から＋終助詞」に落ちて「〜ますからなのだ」になるのだ
  [
    new RegExp(`(${MASU_STEM_CLASS})ますから(?:ね|よ|な|なあ)?$`),
    masu("のだ"),
  ],
  // 終助詞は「よね」「よな」「わね」のように2つ重ねられるのだ。
  // 「ん」＋断定（nd）と用言＋終助詞（yr）は既に2連を許しているのに、
  // 丁寧の「ます」だけが1つしか許していなかったのだ。
  // 1つしか許さないと「戻りますよね」「入りますな」が下の規則に落ちて
  // 「戻りますよねなのだ」と丁寧形を抱えたまま断定が接がれるのだ。
  // 老人語の「〜ますな」・力む「〜ますぞ」も同じ位置に立つ終助詞なのだ
  [
    new RegExp(
      `(${MASU_STEM_CLASS})ます(?:よね|よな|わよ|わね|わな|なあ|[よねわなぞぜ])$`,
    ),
    masu("のだ"),
  ],
  [new RegExp(`(${MASU_STEM_CLASS})ます$`), masu("のだ")],
  // ★ ここまでが「丁寧語＋この語尾」を1つずつ書いた規則なのだ。
  // 書かれていない組み合わせ（「ましたっけ」「ましたけど」「ませんけど」…）は
  // 上の applyTailRules に任せるのだ。丁寧の助動詞だけを常体に落として、
  // 後ろに残った語尾をこの規則表にもう一度掛けるのだ。
  // 直前が連用形の語尾（MASU_STEM_CLASS）であることを求めるのは、上の規則群と
  // まったく同じ番人なのだ——「だます」「済ます」の「ます」は語幹の一部だからなのだ。
  // 語尾が文末の語尾でなければ applyTailRules が null を返すので、
  // 規則を降ろして（RULE_PASS）下の番人に任せるのだ（「ますように」「まして」）。
  // ★ 後ろに残る部分をひらがなだけに限るのだ。文末に残る語尾は終助詞・接続助詞・
  // 確認の助詞で、どれも仮名で書かれるからなのだ。ここを何でも通す形にすると、
  // 行の途中の丁寧語まで拾って後半を丸ごと語尾とみなしてしまうのだ
  // （「ありがとうございましたってレシートを…」→「ございたって…」と語幹が壊れたのだ。
  //  実測して塞いだのだ）
  // ★「ませんでした」は丁寧の助動詞が二重に立った形なのだ（「ません」＋「でした」）。
  // 「ません」だけを常体化して「でした」を文末の語尾とみなすと
  // 「読まないでしたのだけど」という非文になるのだ。過去の否定なので
  // 常体は未然形＋「なかった」なのだ。「ません」より先に受けるのだ
  [
    new RegExp(`(${MASU_STEM_CLASS})ませんでした([ぁ-ゖ]+)$`, "u"),
    (m, c, tail, off, str) =>
      relayTail(str.slice(0, off), nai("なかった")(m, c, off, str), tail),
  ],
  [
    // ★ 丁寧の意向形「ましょう」もこの受け口に入れるのだ。丁寧の助動詞「ます」の
    // 未然形＋推量の「う」で、活用の一番外側に立つ点は「ます」「ました」「ません」と
    // 同じだからなのだ（「行きましょうかね」「やめましょうけど」）。
    // 常体化の先は上の「ましょう」の枝と同じ終止形なのだ
    new RegExp(`(${MASU_STEM_CLASS})(ましょう|ます|ました|ません)([ぁ-ゖ]+)$`, "u"),
    (m, c, pol, tail, off, str) => {
      const head = str.slice(0, off);
      // 「すみません／すいません」は謝罪の定型句で、活用ではないのだ
      // （表の一番上で1語として扱っているのだ）。丁寧語の常体化に掛けると
      // 「済む」の否定として読んで「すみない」を作ってしまうので、ここで降ろすのだ
      if (/(?:すみ|すい)$/u.test(head + c)) return RULE_PASS;
      const plain =
        pol === "ます" || pol === "ましょう"
          ? masu("")(m, c, off, str)
          : pol === "ました"
            ? mashita("")(m, c, off, str)
            : nai("ない")(m, c, off, str);
      return relayTail(head, plain, tail);
    },
  ],
  // 丁寧な命令「〜なさい」は「なさる」の命令形で、直前は連用形なのだ
  // （「乗りなさい」＝「乗れ」）。「ます」とまったく同じ位置に立つので、
  // 同じ活用表を引いて終止形に戻すのだ（「乗りなさい」→「乗るのだ」）。
  // 「い」で終わるので、放っておくと形容詞の終止形と読まれて
  // 「乗りなさいのだ」という非文になるのだ。
  // 連用形かどうかは「ください」と同じ3つの条件で確かめるのだ
  // （え段＝一段確定／五段の表／上一段の表／サ変の「し」）。
  // 表で行が決まらない仮名は語の切れ目が読めないので触らない
  // （「これをみなさい」の「み」は五段の表にも上一段の表にも無いので「むのだ」を防ぐ）。
  // 「おやすみなさい」「おかえりなさい」は挨拶として1語になっていて命令ではないのだ。
  // どちらも表に載る語幹に見えてしまう（「かえ」はラ行五段の表にある）ので、
  // 語として名指しで除くのだ。
  // ★ 接頭辞「お／ご」を伴う形（「お待ちなさい」「おやめなさい」「およしなさい」）も
  // 除くのだ。これは尊敬の命令で、「お」は動詞の一部ではないのだ。
  // 終止形に戻しても「お」は残るので「お待つのだ」「おやめるのだ」という非文になるし、
  // 「お」を落とすと「およしなさい」の「よし」のように表に無い語幹が
  // サ変に落ちて「よするのだ」と語幹ごと崩れるのだ。
  // 「おきなさい（起き）」「おくりなさい（送り）」のように語頭が「お」の動詞まで
  // 巻き込むが、取り違えの害は片側にしか無いのだ。尊敬の命令を素の動詞と読むと
  // 非文になるのに対し、素の動詞を尊敬の命令と読んでも無変換に落ちるだけなのだ。
  // 「ください」の尊敬の依頼とまったく同じ切り分けで、同じ形の条件を使うのだ
  // （文末の文節＝仮名漢字の連なりの中に「お／ご」があるか）
  [
    new RegExp(`(${MASU_STEM_CLASS})なさい(?:よ|ね|な)?$`),
    (m, c, off, str) =>
      GREETING_NASAI.test(str) ||
      /[おご][ぁ-ゖ一-龯々]*$/u.test(str.slice(0, off + 1)) ||
      !(
        /[えけげせぜてでねへべめれ]/u.test(c) ||
        c === "し" ||
        isGodan(c, off, str) ||
        isIchidan(c, off, str)
      )
        ? m
        : masu("のだ")(m, c, off, str),
  ],
  // 語幹が漢字で終わり連用形に仮名が現れない一段動詞（上の「〜ます」と同じ表）
  [/([見出寝着似煮得経])なさい(?:よ|ね|な)?$/, "$1るのだ"],
  // 断定の「なの」＋丁寧の推量（「彼らの生きる意味なのでしょう」）。
  // 「なの」は既に言い切りの一部なので、残したまま「なのだ」を付けると
  // 「意味なのなのだ」と断定が二重になるのだ
  [/なのでしょう?(?:ね|よ)?$/u, "なのだ"],
  // 用言＋準体助詞「の」＋丁寧の推量は「のだろう」に開くのだ
  // （「そうなるのでしょうね」→「そうなるのだろう」）
  yr("のでしょう?(?:ね|よ)?", "$1のだろう"),
  // 丁寧の推量「でしょう」。「でしょう」は「です」の未然形＋推量なので、
  // 「です」とまったく同じ位置に立つのだ。用言の終止形には直に付き
  // （「雲が広がり易いでしょう」→「広がり易いのだ」）、
  // 体言・形容動詞には断定の「な」を挟むのだ（「明日は雨でしょう」→「雨なのだ」）。
  // どちらかは字形では決まらない——「いつ」「ぼく」「ふたつ」の末尾は
  // 用言の終止形とまったく同じ仮名だからなのだ——ので活用表に問うて分けるのだ
  [/でしょう?(?:ね|よ)?$/u, yogenSplit("のだ", "なのだ")],
  // 理由の「〜ですから」は上の「〜ますから」とまったく同じ言いさしなのだ
  // （「これから夏ですからね」）。丁寧語を常体に戻さないと下の「から＋終助詞」に
  // 落ちて「夏ですからなのだ」と丁寧語が残るのだ。
  // ただし説明の「ん」・準体助詞の「の」の直後は別なのだ。「ん」「の」は
  // それ自体が言い切りの一部なので、丁寧語だけ落とすと
  // 「大人なんなのだ」「行くのなのだ」と重なってしまうのだ。
  // 「〜のだから」に開ける形だが、理由の言いさしを断定に変えてしまうので触らない
  [/[んの]ですから(?:ね|よ|な|なあ)?$/u, "$&"],
  // ★ 「です」と同じ接続なので、「です」で撤退した判断はここにも効くのだ。
  // 「です／ですけど／ですから」の直前は仮名書きの形容詞が多く、
  // その語幹は活用表に載せる道が無いのだ（下の「です」の項に実測がある）。
  // 「です」は大量にあるので測れたが、「ですから」はコーパスに2行しか無くて
  // 測れなかっただけで、構造はまったく同じなのだ。
  // 表で決着しない語は承認版どおり無変換に落とすのだ（「きついですから」）
  [/ですから(?:ね|よ|な|なあ)?$/u, yogenSplit("のだ", "なのだ", null)],
  // 用言＋です（「高いですね」→「高いのだ」）。
  // ★ ここだけは活用表に問うていないのだ。「でしょう」「だろう」と同じ接続なので
  // 同じ判定に通すのが筋なのだが、実測すると割に合わなかったのだ。
  // 「です」の直前は圧倒的に形容詞が多く、その形容詞の語幹は仮名で書かれるからなのだ
  // （「美味しい」「めずらしい」「すごい」「うれしい」「〜っぽい」）。
  // 活用表に問う道は、五段動詞のように語幹を数え上げられる類にしか効かないのだ。
  // 形容詞は閉じた類ではあるが、その語幹は仮名書きで、しかも
  // 「きれい」「ぐらい」「みたい」のような体言・形容動詞と字形が重なるので、
  // 表を作っても穴が開くのだ。
  // 4470件のコーパスで測ると、表に通した場合の改善は1件（「5さいです」→「5さいなのだ」）、
  // 悪化は6件（「美味しいです」「めずらしいですね」「すごいですね」「うれしいです」
  // 「〜っぽいです」×2 がすべて「〜なのだ」に落ちる）だったのだ。
  // 「体言＋です」→「のだ」は承認版から残る未達なので、grammar-cases.json に
  // known 付きで記録してあるのだ
  // 「にゃ」は終助詞「な」の猫語形なので、「ね」「よ」と同じ位置に立つのだ
  // （「nostter、ホームがロードされないですにゃ」→「ロードされないのだ」）
  yr("です(?:よね|よ|ね|にゃ|わ)?", "$1のだ"),
  [/ですよね$/, "なのだ"],
  [/です(よ|ね|にゃ|わ)$/, "なのだ"],
  // ★ 形式名詞「もの」＋断定。前のラウンドで「こと」「とこ」「ところ」「わけ」を
  // 形式名詞として数え上げたとき、「もの」だけを外したのだ。理由は「〜ものか」が
  // 反語だからで、それは「か」の枝に限った話なのだ。「〜ものだ」に反語の紛れは無く、
  // 「だ」は素直な断定なので「ものなのだ」に開けるのだ。
  // ★ 承認版でここが無変換だったのは、下の「既にずんだもん語尾」の枝
  // （/のだ$/ と /のです(?:ね|よ)?$/）が「ものだ」「ものです」の末尾3字を
  // 準体助詞「の」＋断定と読んで、変換済みとみなして降ろしていたからなのだ。
  // 両者は活用表で完全に分かれるのだ——準体助詞の「の」は連体形にしか付かず、
  // 現代語の連体形の末尾は う段・「い」・「た」・「な」・「の」で、
  // 「も」で終わる連体形は一つも無いのだ。だから「ものだ」の「の」は
  // 準体助詞ではありえず、必ず体言「もの」の一部なのだ。
  // 形式名詞でない「もの」（「けものだ」「きものだ」）も体言なので答えは同じなのだ
  [
    /もの(?:だ(?:よね|よな|よ|ね|な|にゃ|ぜ|ぞ|わ)?|です(?:ね|よ)?)$/u,
    "ものなのだ",
  ],
  // 準体助詞「の」＋です（「〜するのです」→「〜するのだ」）
  [/のです(?:ね|よ)?$/, "のだ"],
  [/です$/, "なのだ"],
  // 依頼の「ください」には付き方が3つあるのだ。
  //   テ形＋ください（補助動詞）      「買ってください」→「買ってほしいのだ」
  //   お＋連用形＋ください（尊敬の依頼）「お待ちください」→ 触らない
  //   体言＋ください（授受動詞）      「ログボください」→「ログボほしいのだ」
  // 動詞に直に付いた「ください」を「ほしい」に開くと「お待ちほしい」という非文に
  // なるので、そこだけ無変換にするのだ。連用形かどうかは上の活用表で判定する。
  // 尊敬の依頼は接頭辞「お／ご」を必ず伴うのだ（「待ちください」とは言わない）ので、
  // それも条件にするのだ。これが無いと「水割りください」「大盛りください」の
  // 連用形から出来た体言まで動詞と読んで無変換にしてしまうのだ
  // （「割」「盛」はサ行・ラ行五段の語幹でもあるからなのだ）。
  // 終助詞「よ/ね/な」が付いた形も同じ扱いにする（「買ってくださいよ」）
  [/([てで])ください(?:よ|ね|な)?$/, "$1ほしいのだ"],
  [
    new RegExp(`(${MASU_STEM_CLASS})ください(?:よ|ね|な)?$`),
    (m, c, off, str) =>
      // 接頭辞「お／ご」が文末の文節の中にあるか。
      // 「お」から語尾までの字数では切らないのだ。接頭辞が付く先は複合動詞でもよく
      // （「お問い合わせ」「お召し上がり」「お買い求め」「お受け取り」）、
      // 語幹の長さに上限が無いからなのだ。字数で切ると、その数を超えた語だけが
      // 体言と読まれて「お問い合わせほしい」という非文になる。
      // 代わりに、句読点・記号・カタカナ・英数字で切れない仮名漢字の連なり
      // ＝文末の文節を見て、その中に「お／ご」があるかを問うのだ。
      // 取り違えの害は片側にしか無いのだ。尊敬の依頼を体言と読むと
      // 「お待ちほしい」という非文になるが、体言を尊敬の依頼と読んでも
      // 無変換に落ちるだけ（「お店で水割りください」）なので、
      // 「お／ご」が見えたら開かない側に倒すのだ
      /[おご][ぁ-ゖ一-龯々]+$/u.test(str.slice(0, off + c.length)) &&
      // え段は一段動詞の連用形にしかならない（「お知らせください」「お任せください」）。
      // い段は体言の末尾でもありうるので、五段・上一段の表で確かめるのだ
      (/[えけげせぜてでねへべめれ]/u.test(c) ||
        isGodan(c, off, str) ||
        isIchidan(c, off, str))
        ? m
        : c + "ほしいのだ",
  ],
  // 「ご＋漢語＋ください」は漢語サ変動詞への尊敬の依頼なのだ（「ご確認ください」＝
  // 「ご確認なさってください」）。「ご飯ください」のような体言も同じ形をしているが、
  // 取り違えても無変換に落ちるだけで非文は作らないのだ
  [/ご[一-龯々]{1,4}ください(?:よ|ね|な)?$/u, "$&"],
  [/ください(?:よ|ね|な)?$/, "ほしいのだ"],
  // 「くださる」は「くれる」の敬語で依頼の意味なので「ください」と同じ扱いにする
  // （「ログボくださり」→「ログボほしいのだ」）
  [/くださ[りるれ]$/, "ほしいのだ"],
  // 授受動詞の依頼形は「くれ／ください／ちょうだい」の3語で閉じた類なので、
  // 残る「ちょうだい」も同じ「ほしいのだ」に開くのだ。
  // 「い」で終わるが形容詞ではないので、用言＋「のだ」より先に処理する
  [/ちょうだい(?:よ|ね|な)?$/, "ほしいのだ"],
  // テ形＋「くれ」も依頼の命令形なので「ほしいのだ」に開く。
  // 「て」「で」を保存しないと「読んでくれ」が「読んてほしいのだ」になるのだ
  [/([てで])くれ(?:よ|ね|な)?$/, "$1ほしいのだ"],

  // --- のだ / なの 系（既にずんだもん語尾） ---
  // 既に「のだ」で終わっている文に終助詞が付いた形は終助詞だけ落とす
  // （「気がするのだよな」→「気がするのだ」。「のなのだ」になるのを防ぐ）
  [/のだ(?:よね|よな|よ|ね|な|ぜ|ぞ|わ|もん)$/, "のだ"],
  [/なのだ$/, "なのだ"],
  [/のだ$/, "のだ"],
  // 断定の「なの」＋終助詞（「そういう名前のGPUなのよ」「そうなのね」）。
  // 終助詞だけ落として「なの」を残すと「なのなのだ」と重なるので、
  // 「なの」ごと「なのだ」に畳むのだ
  // ★ ここも終助詞の並びが用言側（yrStop）より狭かったのだ。
  // 「な」「なあ」「わ」「ぞ」「ぜ」「にゃ」が抜けていたせいで、
  // 「リスペクトとか皆無なのな」→「皆無なのななのだ」と語尾が重なっていたのだ。
  // 終助詞は同じ位置に立つ同じ語なのだから、「の」の後ろでだけ並びが変わる
  // 理由は無いのだ（「〜のよ」が通って「〜のな」が通らないのは穴なのだ）
  [/なの(?:よね|よな|なあ|ね|よ|さ|な|わ|ぞ|ぜ|にゃ)っ?$/u, "なのだ"],
  [/なの$/, "なのだ"],
  // 用言＋準体助詞「の」＋終助詞（「あそびにきてもいいのよ」
  // 「会場音のみに切り替えられるのね」）。「の」は言い切りの一部なので、
  // 終助詞と一緒に「のだ」へ畳むのだ（「いいのよなのだ」を防ぐ）。
  // 属格の「の」は用言では終わらないので巻き込まないのだ（「ぼくのね」）
  // 終助詞の並びは上の「なの」と同じにするのだ（「もう行くのな」「食べるのわ」）。
  // 「もの」「ぼくの」のような属格・形式名詞の「の」を巻き込まないのは
  // yr が直前を活用表に問うているからで、並びを広げても番人は変わらないのだ
  yr("の(?:よね|よな|なあ|ね|よ|さ|な|わ|ぞ|ぜ|にゃ)っ?", "$1のだ"),

  // --- 口語の断定 ---
  [/じゃない$/, "じゃないのだ"],
  // 用言＋「じゃん」は「のだ」、体言＋「じゃん」は「なのだ」
  yr("じゃん", "$1のだ"),
  [/じゃん$/, "なのだ"],
  // 関西の「〜やん」「〜やんけ」は「じゃん」と同じ確認の断定なのだ
  // （「マヨライスやん」→「マヨライスなのだ」「前と全く同じやんけ」→「同じなのだ」）。
  // 関西弁の文なので、直前の終止形も関西の形（「ええ」「あかん」）が来るのだ。
  // 字形の類では拾えないので YOGEN2 で引くのだ（「ええやん」→「ええのだ」）
  [new RegExp(`(${YOGEN2})やん(?:け)?$`), "$1のだ"],
  [/やん(?:け)?$/, "なのだ"],
  // 関西の断定「や」（＝「だ」）。「や」は並列助詞でもある（「本や雑誌」）が、
  // 並列助詞は必ず後ろに語を伴うので文末には立てないのだ。
  // だから文末の「や」は断定と決まる。終助詞「で」「わ」「ねん」を伴う形も同じなのだ
  [new RegExp(`(${YOGEN2})や(?:で|わ|ねん)$`), "$1のだ"],
  // 断定「や」に立つ終助詞は「で」「わ」「ねん」だけではないのだ。
  // 「や」は「だ」とまったく同じ位置に立つのだから、「だ」に対して持っている
  // 終助詞の並びがそのまま「や」にも立つのだ
  //   〜やな＝〜だな  〜やぞ＝〜だぞ  〜やぜ＝〜だぜ  〜やろ＝〜だろ
  // 用言に付くか体言に付くかは、「だろう」と同じく活用表に問うて分けるのだ
  // （「決まっとるやろ」→「決まっとるのだ」／「起きる時間やな」→「時間なのだ」）。
  // 関西の文には関西の終止形が立つので、「ええ」「あかん／わからん／せん／へん」も
  // 用言の側に数えるのだ（上の YOGEN2 と同じ内訳なのだ）。
  // ★ 体言の側には2つ番人が要るのだ。
  //   ひらがなだけで終わる語は「いや」「へや」「つや」「もしや」のように
  //   「や」までで1語のことが多く、断定の「や」と切り分けられないのだ。
  //   体言はほぼ必ず漢字・カタカナを含むので、直前2字以内にそれを求めるのだ
  //   （「早起きやな」は「起」で通り、「いやな」は通らないのだ）。
  //   もう1つは「やろ」なのだ。体言の直後の「やろ」は「やる」の意向形
  //   （「一緒にやろ」「これやろ」）と字形がまったく同じで、表にも手掛かりが無いのだ。
  //   用言の終止形の直後なら意向形はありえない（終止形は「やる」の目的語に
  //   なれないのだ）ので、「やろ」は用言の側でだけ受けるのだ
  [
    /や(?:ろ|なあ|な|ぞ|ぜ)$/u,
    (m, off, str) => {
      const s = str.slice(0, off);
      if (isYogenEnd(s) || /(?:ええ|[らかせへ]ん)$/u.test(s)) return "のだ";
      if (m === "やろ") return RULE_PASS;
      // 仮名だけで終わる語は断定の「や」と語の一部の「や」が分けられないのだ。
      // 決められない時は変換しないのだ（誤変換より無変換のほうがよいのだ）
      if (!/[一-龯々ァ-ヺーゝゞ][ぁ-ゖ]{0,2}$/u.test(s)) return m;
      return "なのだ";
    },
  ],
  // 体言＋断定の「や」（「俺や」→「俺なのだ」）。ひらがなで終わる語は
  // 「いや」「じゃあ」のように「や」までが1語のことが多く切り分けられないので、
  // 漢字・カタカナで終わる体言に限るのだ
  [/([一-龯々]|[ァ-ヺ][ァ-ヺーヽヾ]*)や(?:で|わ|ねん)?$/u, "$1なのだ"],
  // ★ 方言・老人語の断定「じゃ」は共通語の「だ」に対応するのだ
  // （「冷水浴びて朝食食って、一日をスタートじゃ」→「スタートなのだ」）。
  // 説明の「ん」＋「じゃ」（「そうじゃったんじゃ」）は上の nd で処理済みなので、
  // ここに来るのは裸の断定なのだ。
  // 関西の「や」とまったく同じ位置に立つので、同じ形の2本立てにするのだ——
  // 用言の終止形の直後なら「のだ」、体言の直後なら「なのだ」なのだ。
  // 用言かどうかは字形の類では拾えない（方言の文には方言の終止形が立つ）ので
  // YOGEN2 で引くのだ。
  // 体言の側を漢字・カタカナで終わる語に限るのも「や」と同じ理由なのだ。
  // ひらがなで終わる語は「〜ちゃ」「〜んじゃ」（＝「〜ては」「〜んでは」の縮約）と
  // 切り分けられないからなのだ（「食べちゃ」「飲んじゃ」は言いさしで文末ではないのだ）
  // ★用言側は字形の類（YOGEN2）ではなく活用表に問うのだ。
  // 字形のままだと「そいつじゃ」「ふたつじゃ」「あいつじゃ」の体言の末尾を
  // 用言と読んで「そいつのだ」と語幹ごと削るのだ（「や」の側は isYogenEnd を
  // 引いているので正しく無変換なのだ。同じ形と書いてあったが別物だったのだ）
  [/じゃ$/u, (_m, off, str) => (isYogenEnd(str.slice(0, off)) ? "のだ" : RULE_PASS)],
  [/([一-龯々]|[ァ-ヺ][ァ-ヺーヽヾ]*)じゃ$/u, "$1なのだ"],
  [/だった$/, "だったのだ"],
  // 「〜たろ」は「〜ただろう」の縮約なので過去の「のだ」に戻す
  // （「言ったろ」→「言ったのだ」。下の「〜ろ」番人より先に処理するのだ）。
  // 「〜たろう」まで拾うと人名の「のすたろう」を壊すので「ろ」止まりにするのだ
  [/たろ$/, "たのだ"],
  // 方言の推量「〜じゃろ（＝だろう）」（「なんじゃろ」→「なんなのだ」）
  [/じゃろう?$/, "なのだ"],
  // 常体の推量「だろう」。「だろう」は断定「だ」の未然形＋推量なので、
  // 上の「でしょう」とまったく同じ接続なのだ。用言の終止形には直に付き
  // （「明日は雨が降るだろう」→「降るのだ」）、体言には断定の「な」を挟むのだ
  // （「明日は雨だろう」→「雨なのだ」「犯人はあいつだろう」→「あいつなのだ」）。
  // 「あいつ」「ぼく」「ふたつ」「あなた」の末尾は用言の終止形と同じ仮名なので、
  // 字形ではなく活用表に問うて分けるのだ
  [/だろう?(?:ね|よ|なあ|な)?$/u, yogenSplit("のだ", "なのだ")],
  [/である$/, "なのだ"],
  [/だなあ$/, "なのだ"],
  // 体言＋断定「だ」＋「けど」＋終助詞（「そうだけどね」）も同じ言いさしなのだ。
  // 終助詞ごと畳まないと「そうだけどねなのだ」と接続助詞に断定が接いだ非文になる
  // 「読んだけどね」の「だ」も上の「だが」と同じ過去なのだ
  [/だけど(?:なあ|ねえ|ね|よ|な)$/u, daSplit("だけど")],
  [/だけど$/, daSplit("だけど")],
  // 「にゃ」は終助詞「な」の猫語形なのだ（「株式だと自由効かなくなるからダメだにゃ」）。
  // 上の nd（「〜んだにゃ」）と対にして、断定「だ」の直後の並びにも足すのだ
  [/だ(よね|よな|よ|ね|な|にゃ|ぜ|ぞ|わ|もん)$/, "なのだ"],
  // 断定＋終助詞のあとにさらに仮名が続く形は、話者ごとのキャラ語尾
  // （「〜だよぷく」「〜だねゾ」）。未知の語尾は無限にあって列挙できないので、
  // 終助詞ごと落として素の断定に戻すのだ。
  // 続く仮名が「い」「ん」で始まる場合は「〜だない」「〜だなんて」のような
  // 普通の語尾なので除く（「ほどではまだない」を「ほどではまなのだ」に壊さないため）
  [/だ(?:よね|よな|よ|ね|な|ぜ|ぞ|わ)(?![いん])[ぁ-ゖ]{1,2}$/, "なのだ"],
  [/だ$/, "なのだ"],

  // --- 終助詞（用言の直後なら終助詞を落として「のだ」にする） ---
  // 方言の終助詞「ずら」は落とす（「寝るズラなのだ」の語尾二重を防ぐ）
  yr("(?:ずら|ズラ)", "$1のだ"),
  // 「あるな」→「あるのだ」「怖いな」→「怖いのだ」（「あるなのだ」を防ぐ）。
  // 理由・納得の終助詞「もん」「もんな」（＝「〜のだもの」）も同じ扱いなのだ
  // （「わからないもんな」→「わからないのだ」）。体言の「物」と字形は同じだが、
  // 「物」なら連体修飾の途中で文が終わらないので、行末に来た時は終助詞なのだ
  // 逆接の言いさし「〜けど」（「こうなるけど」「気がするけどねえ」）。
  // 「〜んだけどね」（nd で処理済み）とまったく同じ形なので、同じく「のだけど」に開くのだ。
  // ★ 以前は終助詞が付いた形だけに限っていたのだ。裸の「〜けど」は次の節が続く途中なのか
  // そこで言い残して終わっているのかが表層では決まらないので、無変換に留めていたのだ。
  // その線引きを外して裸の「けど」も開くことにしたのだ。理由は2つあるのだ。
  //   ① 開いても「けど」は残るのだ（「気になるけど」→「気になるのだけど」）。
  //      接続助詞をそのまま残して間に「のだ」を挟むだけなので、後ろに節が続いていても
  //      文がそこで終わっていても、どちらの読みも壊れないのだ。
  //      「〜てね」を叙述に変えると依頼が消えるのとは事情が違うのだ。
  //   ② 全コーパス6373件で A/B を測ったのだ。改善31件・悪化0件だったのだ。
  //      裸の「けど」で終わる行は審査済みコーパス7617行のうち31行あって、
  //      無変換のまま残っていた形の中でいちばん大きな類だったのだ。
  // これが無いと「けどなのだ」「けどねえなのだ」と接続助詞に断定が接いだ非文になる。
  // 丁寧語＋「けど」は先に常体へ戻すのだ。「です」「ます」の「す」は
  // 用言の終止形の「す」（「話す」「押す」）と字形が同じなので、
  // 下の yr に落ちると丁寧の助動詞を用言と読んで
  // 「無駄ですのだけど」「行きますのだけど」という非文になるのだ。
  // 「〜んですけど」（nd で処理済み）とまったく同じ言いさしなので、同じ形に畳むのだ
  [
    new RegExp(`(${MASU_STEM_CLASS})ますけど(?:なあ|ねえ|ね|よ|な)?$`),
    masu("のだけど"),
  ],
  // 上の「ですから」と同じなのだ。表で決着する語だけ開いて
  // （「高いですけどね」→「高いのだけど」「無駄ですけどね」→「無駄なのだけど」）、
  // 仮名語幹の「〜い」は承認版どおり無変換に落とすのだ（「つらいですけど」）
  [
    /ですけど(?:なあ|ねえ|ね|よ|な)?$/u,
    yogenSplit("のだけど", "なのだけど", null),
  ],
  // ★ 口語否定の「ん」＋逆接の「けど」（「知らんけど」）はここに置いていないのだ。
  // 規則そのものは書けるのだ——下の yr は用言の終止形を字形の類（YOGEN）で引き、
  // 口語否定の「ん」はその類に入っていない（体言の末尾の「ん」と字形が同じだからなのだ）
  // ので、活用表に問う isColloquialN を番人にすれば分かれるのだ。
  //     [/ん(?:けれども?|けど)(?:なあ|ねえ|ね|よ|な)?$/u,
  //      (m, off, str) => (isColloquialN(str.slice(0, off + 1)) ? "んのだけど" : m)]
  // 実測では全コーパス14031件で 改善14・悪化0 だったのだ。
  // それでも入れていないのは、grammar-cases.json の
  // 「けど＋言いさし・番人」＝「100万あれば買えるんちゃう知らんけど」（無変換を期待）と
  // 正面から衝突して 落ちた -1 になるからなのだ。
  // あの番人が記録している事故は nd 系（説明の「ん」）を「んけど」まで広げて
  // 「しらのだけど」と「ん」ごと削った件で、「ん」を残すこの形とは別の規則なのだ。
  // 番人の期待値を書き換える権限はこちら側に無いので、申告に回して入れないのだ
  // ★ 口語否定「〜ん」＋言いさしの「けど」（「知らんけど」「届いてへんけど」）。
  // 「ん」は用言の終止形の字形（YOGEN）に無いので yr では拾えないのだ。
  // 「ん」を残したまま活用表（isColloquialN）に問うて開くのだ——
  // 「ん」ごと削ると「しらのだけど」と語幹が壊れるので、そこが番人なのだ。
  // 承認版の裸の「けど」の枝（「気になるけど」→「気になるのだけど」）と同じ形で、
  // 接続助詞を残して間に「のだ」を挟むだけなので、後ろに節が続く読みも壊れないのだ。
  // 全コーパス14031件で 改善14・悪化0 なのだ
  [
    /ん(?:けれども?|けど)(?:なあ|ねえ|ね|よ|な)?$/u,
    // raBacked は「らん」「らへん」の「ら」をラ行五段の未然形として活用表に
    // 裏づけさせる番人なのだ（「そこらへん」「すずらん」を体言に留めるのだ）
    (m, off, str) => {
      const head = str.slice(0, off + 1);
      return isColloquialN(head) && raBacked(head) ? "んのだけど" : m;
    },
  ],
  yr("けれども?(?:なあ|ねえ|ね|よ|な)?", "$1のだけど"),
  yr("けど(?:なあ|ねえ|ね|よ|な)?", "$1のだけど"),
  // 「ぜよ」は土佐の終助詞で、「ぞ」＋「よ」が1語になったものなのだ
  // （「推敲したことないぜよ」）。終助詞は重ねて置けるので、「よね」「よな」と
  // 同じくひとまとまりで落とすのだ。落とさないと変換そのものが起きないのだ
  // 「〜っす」は「です」の口語形なのだ（「嬉しいっす」→「嬉しいのだ」）。
  // 体言に付いた形は「なのだ」だが、直前がひらがなだと「おはのっす」のような
  // 崩した挨拶と区別できないので、漢字・カタカナで終わる体言に限るのだ
  yr("っす(?:よ|ね|わ)?", "$1のだ"),
  [/([一-龯々ァ-ヺー])っす(?:よ|ね|わ)?$/u, "$1なのだ"],
  // 「〜っす」は裸の終助詞（「〜ね」「〜よ」）より先に置くのだ。
  // 「す」は用言の終止形にも立つ仮名なので、「ダメっすね」は下の終助詞の規則の
  // 字形にも当たるのだ。そちらが先に当たると、活用表が「ダメっす」は用言では
  // ないと答えた時点で無変換に留まって、「です」の口語形として畳む機会を失うのだ
  // 「わよ」「わね」「わな」も同じ2連なのだ（「大学生のレポートよりひどいわよ」）。
  // 断定の後ろ（nd の「だわね」「だわな」）では既に2連を許していたのに、
  // 用言に直に付く側だけが「わ」1つで止まっていたのだ。
  // 落とさないと「ひどいわよなのだ」と終助詞を抱えたまま断定が接がれるのだ
  // 「わい」も終助詞「わ」の一類なのだ（「泳いでやるわい」＝「泳いでやるよ」）。
  // 「わ」1つで止めていると「やるわいのだ」と終助詞を抱えたまま接いでしまうのだ。
  // 直前が用言の終止形の字形であることを求めるのだ。ただしこれは字形の類であって
  // 活用表ではないのだ——「こわい」「あじわい」が無事なのは「こ」「じ」が字形の類に
  // 入っていないからで、この番人が働いた結果ではないのだ（監査で実測して分かったのだ）。
  // だから「い」で終わる体言＋「わい」は落ちるのだ（「結婚のおいわい」→「おいのだ」、
  // 「野菜のくわい」「ずわい」「たわい」）。全コーパス6373件で0件のハパクスなので
  // 受け入れているが、直すには isYogenEnd に通す要があるのだ
  // ★ 「にゃ」も終助詞「な」の一類なのだ（「カスタムビルドを依頼して寝るにゃ」）。
  // 断定の後ろ（上の「〜だにゃ」）と同じく、用言の終止形の直後にも立つのだ。
  // ★ 終助詞の直後の促音「っ」は引き伸ばしと同じ飾りなのだ（「べったん、出すぞっ」）。
  // 促音は語末に立たない音なので、終助詞の後ろの「っ」は語の一部ではありえず、
  // 言い切りを強めるために添えた印なのだ。終助詞ごと畳んで落とすのだ。
  // 下に「行末の『っ』は活用が復元できないので触らない」という番人があるが、
  // ここは終助詞が読めているので活用は復元できているのだ——その番人が守っているのは
  // 「しよっ」「行こっ」のように終助詞ではない促音化なのだ。
  // 依頼のテ形＋「よ」＋促音（「やめてよっ」「聞いてよっ」）を巻き込まないのは、
  // 「て」が用言の終止形の字形（YOGEN）に入っていないからなのだ
  yrStop(
    "(?:もんな|もん|なあ|よね|よな|わよ|わね|わな|わい|ぜよ|な|にゃ|ね|よ|ぞ|ぜ|わ)っ?",
    "$1のだ",
  ),
  // 「ねえ／ねー」は否定の「ない」の口語形なのだ（「止まらねえ」＝「止まらない」）。
  // 「ない」と同じ形容詞型の終止形なので、そのまま「のだ」を接げるのだ。
  // 感動詞・終助詞の「ねえ」（「ねえねえ」「そうかねえ」）と字形が同じなので、
  // 直前が五段の未然形（あ段）で、その手前がその行の語幹かを活用表に問うて分けるのだ
  // （「止ま＋ら」はラ行五段の表にあり、「そう＋か」はカ行五段の表に無い）。
  // 表に無ければ活用が読めないので触らないのだ。
  // ★ ただし「が」だけは例外なのだ。「ない」は否定の助動詞であると同時に
  // 存在を否定する形容詞でもあり、そちらは未然形ではなく格助詞「が」の直後に立つのだ
  // （「お金がねえ」＝「お金が無い」）。ガ行五段の語幹表に載っていない「が」は
  // 活用語尾ではなく格助詞なのだから、そこで「ない」と読んでよいのだ。
  // 直前を漢字・カタカナに限るのは、間投助詞の「ねえ」（「それがねえ…」）と
  // 分けるためなのだ。格助詞「が」の前に立つ体言は文節の頭なので、
  // 仮名で書かれた語の途中とは切れ方が違うのだ。
  // ★★ その形容詞の「ない」は、口語では格助詞が落ちて体言に直に付くのだ
  // （「意味ねえ」＝「意味がない」「関係ねえ」「金ねえ」）。
  // 助詞が落ちても体言の末尾が文節の頭であることは変わらないので、
  // 「が」の枝と同じ番人——漢字・カタカナで終わること——をそのまま使えるのだ。
  // 漢字語幹の形容詞の音便形（「汚ねえ」＝汚い、「危ねえ」＝危ない）も同じ形なのだ。
  // 残る紛れは体言・形容動詞語幹＋終助詞の「ねえ」（「素敵ねえ」「大変ねえ」）で、
  // これは表では分けられないのだ。形容動詞語幹を数え上げる表が無く、
  // 存在を否定される体言（意味・関係・時間）と字形がまったく同じだからなのだ。
  // 否定の側に倒すのは、取り違えの害がどちらも「な」を挟むか挟まないかだけで
  // 語が壊れないうえ（「素敵ねえのだ」／「素敵ねえなのだ」）、
  // 体言＋「ねえ」で断定を落とす言い方のほうが稀だからなのだ。
  // 全コーパス6373件では否定の側が2件、終助詞の側は0件だったのだ。
  // ★ 未然形は あ段だけではないのだ。あ段になるのは五段だけで、
  // 一段動詞と可能動詞（五段のえ段＋「る」）の未然形は語幹と同形の え段なのだ
  //   動けねえ＝動けない  使えねえ＝使えない  帰れねえ＝帰れない  泳げねえ＝泳げない
  // これは口語否定の「〜ん」（「使えん」「書けん」）とまったく同じ形で、
  // 同じ問いを活用表に投げれば分かれるのだ——え段を E_TO_I で い段に写して
  // その行の五段語幹かを問うのだ（「動け」→「動き」はカ行の表にある／
  // 「これだけ」の「だ」はカ行の表に無い）。isPotentialNegation と同じ判定なのだ
  [
    /([わかがさたなばまら]|[えけげせてねべめれ]|[一-龯々ァ-ヺーゝゞ])ね[えー]$/u,
    (m, c, off, str) =>
      (A_TO_I[c] !== undefined && isGodan(A_TO_I[c], off, str)) ||
      (E_TO_I[c] !== undefined && isGodan(E_TO_I[c], off, str)) ||
      (c === "が" && /[一-龯々ァ-ヺーゝゞ]$/u.test(str.slice(0, off))) ||
      /[一-龯々ァ-ヺーゝゞ]/u.test(c)
        ? m + "のだ"
        : m,
  ],
  // 形容詞の口語音便形（「小せえ」＝小さい、「高けえ」＝高い、「重てえ」＝重い）。
  // 語幹末のあ段・お段が語尾の「い」と融合して え段の長音になった形なのだ
  // （ちいさ＋い→ちいせえ、たか＋い→たけえ、すご＋い→すげえ）。
  // 語幹が漢字・カタカナで書き分けられていれば形容詞と決まるのは、
  // isYogenEnd の「漢字語幹＋い＝形容詞」とまったく同じ番人なのだ。
  // 語幹が仮名だけの形（「すげえ」「うめえ」「やべえ」）は通せないのだ——
  // 引き伸ばした終助詞・助詞（「だぜえ」「まじでえ」）や、擬音・命令形の引き伸ばし
  // （「いそげー」「じめじめー」「連れてってー」）と表層で分けられないからなのだ。
  // え段も全部は開かないのだ。融合で生じうるのは、形容詞の語幹末に実際に立つ
  // 仮名から来た段だけなのだ——か→け（高い）さ→せ（小さい）た→て（痛い）
  // ま→め（うまい）ら→れ（つらい）ば→べ（やばい）ご→げ（すごい）。
  // 「ぜ」「で」「へ」はどの形容詞の語幹末（ざ・だ・は）からも来ないのだ。
  // その3つは終助詞「ぜ」・助詞「で」・助詞「へ」を引き伸ばした形にしかならないので
  // 初めから外すのだ（「行くぜえ」「まじでえ」を形容詞に読まないため）。
  // 「ねえ」（な→ね。汚い・危ない・きたない）だけは上の口語否定の規則が先に受け持つのだ
  [/[一-龯々ァ-ヺーゝゞ][けげせてべめれ]え$/u, "$&のだ"],
  // ラ行五段の未然形＋口語否定の「ん」（＝「ぬ」）。常体の「ない」に戻してから
  // 語尾を付けるのだ（「まだ上がらんな」→「まだ上がらないのだ」「わからん」→
  // 「わからないのだ」）。終助詞が付いた形も一緒に畳むのだ。
  // 下の「らね」（「いらね」「知らね」）とまったく同じ切り分けで、ラ行に限るのは
  // 他の段の「かん」「せん」「へん」が名詞（「みかん」「線」「たいへん」）と
  // 見分けが付かないからなのだ
  [/らん(?:なあ|よね|よな|な|ね|よ|ぞ|ぜ|わ)?$/u, "らないのだ"],
  // 「〜ないと」は義務の言いさし。終助詞が付いた形もまとめて述語を補う
  // （「考えとかないとなあ」→「考えとかないといけないのだ」）。
  // 下の「と＋終助詞」ルールより先に置くのだ
  [/ないと(?:なあ|ねえ|な|ね)?$/, "ないといけないのだ"],
  // ラ行五段「ある」の連用中止形（「〜があり」「〜がおり」）は文を切らずに次へ続ける形で、
  // 行末に来ると述語が無いまま宙に浮くのだ（「おっさんの危険行動があり」＋次の行）。
  // 中止形は後続の節と時制を共有するので、言い切りに直すなら過去形なのだ
  // （「危険行動があり…通報した」→「危険行動があったのだ」）。
  // 直前を格助詞「が」「も」に限るのは、「というのはあり」のように可否を表す
  // 体言の「あり」（＝アリ）と分けるためなのだ
  [/([がも])あり$/u, "$1あったのだ"],
  // 「〜なきゃ」「〜なくちゃ」は「〜なければ／〜なくては いけない」の省略で、
  // 述語が落ちた形なのだ（「ログを流さなきゃ」→「流さなきゃいけないのだ」）。
  // 上の「ないと」とまったく同じ言いさしなので、同じように述語を補うのだ
  [/(な(?:きゃ|くちゃ))(?:なあ|ねえ|な|ね|よ)?$/u, "$1いけないのだ"],
  // 「〜ねば」は打消の助動詞「ぬ」の仮定形「ね」＋接続助詞「ば」なのだ
  // （「作らねば」＝「作らなければ」）。後ろに続くはずの「ならない」が省かれた
  // 言いさしなので、上の「〜なきゃ」「〜ないと」とまったく同じ形なのだ。
  // 同じように省かれた述語を補って言い切りにするのだ。
  // ★ 「ぬ」は未然形に付くのだ。五段の未然形は あ段なのだ。
  // 体言・擬態語の末尾の「ねば」（「納豆はねばねば」）と分けるには、
  // あ段の手前がその行の五段語幹かを活用表に問うほかないのだ——
  // 口語否定の「ねえ」（「止まらねえ」）とまったく同じ問いなのだ
  // （「作＋ら」はラ行の表にあり、「ねば＋ね」の「ね」はバ行の表に無いのだ）。
  // 下の仮定形の番人（え段＋「ば」）より先に置かないと無変換に落ちるのだ。
  //
  // ★ え段（一段・可能動詞の未然形。「動けねば」「食べねば」）は入れないのだ。
  // 活用としては同じ形なのだが、この枝には効かせすぎを止める番人が書けないのだ——
  // え段＋「ねば」で終わる体言が見つからず、表に無い一段動詞を開いても
  // （「食べねばならないのだ」）正しい日本語になってしまうので、
  // 「潰したら落ちる番人」の形にならないのだ。測れない枝は置かないのだ。
  // 全コーパス7567件でも え段＋「ねば」は0件なのだ
  [
    /([わかがさたなばまら])ねば$/u,
    (m, c, off, str) =>
      isGodan(A_TO_I[c], off, str) ? m + "ならないのだ" : RULE_PASS,
  ],
  // 撥音「ん」・拗音「ゃゅょ」・引用の「と」の直後は名詞の一部ではありえないので、
  // そこに続く終助詞は落として体言扱いにする
  // （「たいへんね」→「たいへんなのだ」「ねなきゃね」→「ねなきゃなのだ」）。
  // 「な」単体を入れると「みんな」「こんな」を、「わ」を入れると「しゃわ」を
  // 巻き込むので入れないのだ
  [/([んゃゅょと])(?:なあ|ねえ|よね|よな|ね|よ)$/, "$1なのだ"],
  // 漢字2字以上・カタカナ2字以上の直後の「な」は語の一部ではありえない（「みんな」
  // 「こんな」のような「な」を含む和語はすべてひらがな書き）ので、断定の「な」
  // （＝口語の「だ」）か連体形の「な」なのだ。どちらも「なのだ」に畳める
  // （「お前もボールな」→「お前もボールなのだ」「大変な」→「大変なのだ」）
  // 終助詞「ね」「よ」「さ」「わ」も同じ理屈で落とせるのだ（「もちろん紫陽花ね」→
  // 「紫陽花なのだ」）。え段で終わる動詞の活用（「訪ね」「重ね」「見せ」）と
  // 字形が重なるが、複合動詞の語幹は必ず送り仮名を挟むので（「書き連ね」「待ち兼ね」）、
  // 漢字が2字以上つながった直後の「ね」は活用語尾ではありえないのだ
  // ★ 終助詞の並びが用言側（yrStop）より狭かったのだ。
  // 用言側は「もんな・もん・なあ・よね・よな・わよ・わね・わな・わい・ぜよ・
  // な・にゃ・ね・よ・ぞ・ぜ・わ」を落とすのに、体言側は1字の「な・ね・よ・さ・わ」
  // しか持っていなかったのだ。終助詞は同じ位置に立つ同じ語なのだから、
  // 前に立つのが用言か体言かで並びが変わるはずが無いのだ。
  // 狭いせいで「食らうとキツイよね」→「キツイよねなのだ」のように、
  // 終助詞を抱えたまま断定が接がれていたのだ。
  // ★ ただし「もん」「もんな」「わい」は体言側には置かないのだ。
  // 「もん」は理由・納得の終助詞で、用言か断定「だ」の直後にしか立たないのだ
  // （「行くもん」「いやだもん」。「だもん」は上の断定の並びが既に受けているのだ）。
  // 体言に直に付く形は無いのに字形だけが「〜もん（者）」と重なるので、
  // 置くと「バカもん」→「バカなのだ」と語を削るのだ。
  // 「わい」も同じく用言の直後の終助詞で、体言＋「わい」は「かわい」「ずわい」
  // 「たわい」と切り分けられないのだ。
  // ★ 終助詞の直後の促音「っ」が飾りなのも用言側と同じなのだ（「大丈夫よっ」）
  [
    /([一-龯々]{2,}|[ァ-ヺ][ァ-ヺーヽヾ]+)(?:よね|よな|にゃ|な|ね|よ|さ|ぞ|わ)っ?$/u,
    "$1なのだ",
  ],
  // ★ 「よね」「よな」「ぜよ」は、上の「漢字2字以上」という番人を掛けずに
  // 漢字1字と送り仮名1字まで届かせられるのだ（「うちの猫よね」「188cmの巨人よな」
  // 「同じよね」「食べ過ぎよね」）。あの番人は え段の「ね」が一段動詞の連用形の
  // 語尾と字形が重なることへの備えなのだ（「訪ね」「重ね」「兼ね」）。
  // 「よ」で始まる2字の終助詞にはその紛れが無いのだ——現代語に「よ」で終わる
  // 活用語尾も接尾辞も無いからなのだ。
  // ★ 送り仮名の枠を い段（「し」を除く）に限るのだ。ここを仮名一般に開いて
  // 実測したら、活用語尾を送り仮名と取り違えて次のように壊れたのだ:
  //   命令形（え段・「ろ」）… 「早く帰れよね」→「早く帰れなのだ」
  //                          「勉強しろよな」→「勉強しろなのだ」
  //   テ形（「て」「で」）  … 「ちゃんと見てよね」→「ちゃんと見てなのだ」（依頼が消える）
  //   準体助詞・助詞（「の」「ら」）… 「これは俺のよね」「理由からよね」
  // い段は活用の側では連用形の語尾だが、連用形は そこで文が終わらない中止法なので
  // 終助詞を伴わないのだ。体言の側では 形容動詞語幹の送り仮名（「同じ」）と
  // 連用形名詞の末尾（「食べ過ぎ」）がこの段なのだ。だから い段だけを通すのだ。
  // 「し」だけは外すのだ——サ変の連用形「し」と同形で、「勉強しよね」
  // （＝「勉強しようね」の縮約）を巻き込むからなのだ。
  // ★ 「わよ」「わね」「わな」はここに置かないのだ。「わ」は あ段＝五段の未然形で、
  // 漢字1字の直後に立つと活用語尾と分けられないのだ（「言わね」＝「言わない」、
  // 関西の「言わな」＝「言わないと」）。この3つは上の漢字2字以上の側だけで受けるのだ
  [
    /([一-龯々ァ-ヺーゝゞ][きぎじちにひみりび]?)(?:よね|よな)っ?$/u,
    "$1なのだ",
  ],
  // ★ 「よ」「ぞ」「ぜ」だけは漢字1字の直後でも通せるのだ（「白い皿よ」「これで本番ぞ」）。
  // 上の番人が漢字2字を求めているのは、1字だと活用語尾・接尾辞と字形が重なるからなのだ——
  //   「ね」…一段動詞の連用形（え段。「重ね」「訪ね」「兼ね」「委ね」）
  //   「な」…命令の「な」（＝「〜なさい」の口語形。「見な」「寝な」「出な」）
  //   「さ」…名詞を作る接尾辞（「高さ」「重さ」「強さ」）
  //   「わ」…五段の未然形・送り仮名（「言わ」「思わ」「終わ」「合わ」）
  // ところが「よ」「ぞ」で終わる活用語尾も接尾辞も現代語には無いのだ。
  // ★「ぜ」は外したのだ。ザ行下一段（混ぜる・交ぜる・爆ぜる・案ずる・論ずる）の
  // 連用形語尾がまさに「ぜ」で、「よぞぜに活用語尾は無い」という理由は事実として
  // 誤りだったのだ（「ごちゃ混ぜ」→「ごちゃ混なのだ」と語幹が壊れたのだ）。
  // 番人の理由が当たらない段にまで番人を掛けていたので、
  // 「白い皿よ」→「白い皿よなのだ」と終助詞を抱えたまま断定が接がれていたのだ。
  // 残る紛れは一段動詞の文語命令形（連用形＋「よ」）だけなのだ。語幹が仮名で終わる形
  // （「食べよ」「見せよ」）は上のえ段＋「よ」の番人が既に受けているので、
  // ここに残るのは語幹が漢字1字の一段動詞だけなのだ。この類は連用形の仮名が
  // 表に出ない——活用表を引く鍵が無い——ので、語として名指しで除くほかないのだ
  [/((?![見出着似煮経得射寝居観診視看干鋳来])[一-龯々])[よぞ]っ?$/u, "$1なのだ"],
  // 漢字1字＋「な」は動詞の連用形＋命令の「な」と同じ形なのだ
  // （「見な」「来な」「寝な」「出な」＝「〜なさい」の口語形）。
  // 「変な」「嫌な」のような連体形とは表層で区別できず、命令を叙述に変えると
  // 意味が反転してしまうので触らないのだ
  [/[一-龯々]な$/u, "$&"],
  // 係助詞「は」＋終助詞は、後ろに続くはずの述語が省かれた言いさしなのだ
  // （「それをあえてつかうのはね」）。文はまだ終わっていないので触らない。
  // 「はね（羽根）」「かねね」のような体言と分けるため、
  // 助詞の「は」であることが確かな形（「のは」「には」「とは」「では」）に限るのだ
  [/[のにとで]は(?:ね|なあ|さ)$/u, "$&"],
  // 終助詞「か」＋「よ」は問いかけではなく反語・詠嘆なのだ
  // （「またかよ」「またゲームかよ」「解けるんじゃないのかよ」）。
  // 相手の答えを求めていないので疑問符を付ける形（「〜のだ？」）には開けないし、
  // 断定に開くと呆れの調子が消えてしまうのだ。
  // 落とし所が無い以上、番人として無変換に留めるのが正しいのだ。
  // これが無いと終助詞を抱えたまま「またかよなのだ」と断定が接がれるのだ
  [/かよ$/u, "$&"],
  // 引用の「と」＋終助詞「な」も同じ言いさしなのだ（「継続するために必要とな」）。
  // 「と」ごと落として言い切りに戻すのだ（「必要とななのだ」を防ぐ）。
  // 直前を漢字に限るのは「おとな」「ふるさとな」のように「とな」が語の一部に
  // なっている形を巻き込まないためなのだ
  [/([一-龯々])とな$/u, "$1なのだ"],
  // 理由の「〜から」＋終助詞（「連携取れていいからなぁ」→「〜いいからなのだ」）
  // 終助詞「さ」も同じ並びなのだ（「12時なんだからさ」「もう遅いからさ」）。
  // 裸の「さ」は名詞を作る接尾辞（「高さ」「ほしさ」）と分けられないが、
  // 接続助詞「から」の直後という位置なら接尾辞ではありえないので通せるのだ
  [/から(?:なあ|ねえ|な|ね|よ|さ)$/, "からなのだ"],
  // 確認の「〜っけ」は「のだっけ」に開く（「なかったっけ」→「なかったのだっけ？」）。
  // 断定の「だ」に付いた「だっけ」は「だ」ごと畳まないと「だのだっけ」と
  // 断定が二重になるのだ（「東京科学大学だっけ」→「東京科学大学なのだっけ？」）
  // 「飲んだっけ」「泳いだっけ」の「だ」は断定ではなく音便の直後で濁った過去なのだ。
  // 断定と読むと「飲んなのだっけ」と音便形の「ん」「い」ごと削るのだ。
  // 「だが」「だけど」「だし」と同じく活用表に問うて分けるのだ
  [/だっけ$/u, daSplit("だっけ？")],
  [/っけ$/, "のだっけ？"],
  [/なあ$/, "なのだ"], // 「買わないとなあ」→「買わないとなのだ」

  // --- 形容動詞・体言的な語は「のだ」ではなく「なのだ」 ---
  // 終助詞が付いた形もまとめて畳むのだ（「むすってとこが好きよ」→「好きなのだ」）。
  // 用言＋終助詞は上の yr で処理済みなので、ここに来るのは体言・形容動詞語幹だけなのだ
  [/(好き|すき|嫌い|きらい|綺麗|きれい|ぐらい|くらい)(?:よね|よな|ね|よ|わ|さ)?$/,
    "$1なのだ"],
  // 「い」で終わるのに用言ではない体言なのだ。形容詞の終止形と表層が同じなので、
  // 放っておくと「おなかいっぱいのだ」「気のせいのだ」という非文になる。
  // 形式名詞「はず」も同じく「ず」で終わるので用言と見分けが付かないのだ。
  // 形式名詞（はず・わけ・つもり・ため・せい）は閉じた類なので数え上げられるのだ。
  // 「わけ」「つもり」「ため」は仮名の既定で体言に落ちるので挙げなくてよい
  [/(?:いっぱい|一杯|のせい|の所為|はず|筈|お願い|おねがい)$/u, "$&なのだ"],
  // 推量の「かも」。終助詞が付いた「かもな」「かもね」も同じ扱いにする
  // （「かもななのだ」と「な」が重なるのを防ぐ）。
  // ★ 「かもしれん」「かもしれへん」も同じ連語「かもしれない」の口語否定なのだ。
  // 「しれ」は下一段動詞「知れる」の未然形（一段の未然形は語幹と同形）で、
  // そこに助動詞「ぬ」の口語形「ん」が付いた形なのだ。
  // これは活用表では引けないのだ。え段＋「ん」を否定と読む枝（isPotentialNegation）は
  // え段の直前がその行の五段語幹かを問うが、ここの語幹は仮名書きの「し」で、
  // ラ行の語幹表に載っているのは漢字の「知」だからなのだ。
  // 表に仮名の「し」を足してはいけないのだ——「おしり」「みしり」の「しり」まで
  // ラ行五段の連用形に読んでしまうからなのだ（表は活用の写しであって、
  // 通したい語のための穴埋めではないのだ）。
  // 「かもしれない」はもともとこの規則が1つの連語として扱っているものなので、
  // その否定の変異形もここで一緒に畳むのだ
  [/かも(?:しれ(?:ん|へん))?(?:なあ|な|ね|よ)?$/u, "かもしれないのだ"],
  // 連体形「ような」は「な」が重なるので1つにまとめる（「ようななのだ」を防ぐ）
  [/ような$/, "ようなのだ"],
  // 「そうか」「そうね」など指示語＋終助詞は終助詞を落とす。
  // 指示語は独立した副詞なので、直前は行頭・句読点か助詞に限る。
  // 語幹が直に続く場合は動詞の意向形・様態であって指示語ではないのだ
  // （「すご＋そうね」「行＋こうね」「書＋こうね」を「〜なのだ」に変えないため）
  [/(^|[、，。\s]|[はもがをにとでやの])(そう|こう|どう)(なあ|よね|か|ね|よ|な)$/u,
    "$1$2なのだ"],

  // --- 助詞・活用形の誤接続を防ぐ ---
  // 促音「っ」は語幹の末尾に立てない音なので、「っ」の直後の う段は用言の
  // 活用語尾ではありえないのだ（「働く」は用言だが「晩しゃっく」は体言）。
  // 用言の終止形と読まれて「晩しゃっくのだ」になるのを防ぐのだ
  [/っ[うくぐすずつぬふぶむる]$/u, "$&なのだ"],
  [/まで$/, "までなのだ"], // 「ここまで」→「ここまでなのだ」
  [/ないで(?:よ|ね|な)?$/, "ないでほしいのだ"], // 「〜しないで」は依頼
  // 文末の一段のテ形（「気を付けて」）を終止形に戻す規則は置かないのだ。
  // 終止形に直せるのは事実だが、文末のテ形には依頼（「詳しく教えて」）と
  // 中止法（「名付けて さくらスクリプト」）と言いさし（「無事に帰れて」）があり、
  // 表層では見分けられない。終止形にすると依頼が叙述に変わって意味が反転するのだ
  // ★ 口語否定の「ん」＋関西の念押しの終助詞「で」なのだ
  // （「わからんで」＝「わからないよ」「もう行かなあかんで」）。
  // 下の「〜るで」「〜たで」とまったく同じ終助詞で、その手前に立つ終止形が
  // 関西の口語否定だという点だけが違うのだ。上の「けど」と同じく、
  // 体言の末尾の「ん」と分けられるのは活用表だけなので isColloquialN に問うのだ。
  // ★ ここには番人が1枚多く要るのだ。「〜んで」はマ・バ・ナ行五段の撥音便の
  // テ形でもあるからなのだ（「読んで」「選んで」「絡んで」）。
  // その切り分けは isColloquialNBeforeDe にまとめてあるのだ
  [
    /んで$/u,
    (m, off, str) =>
      isColloquialNBeforeDe(str.slice(0, off + 1)) ? "んのだ" : m,
  ],
  [/([んい])で$/, "$1で"], // 「読んで」「急いで」はテ形なので変換しない
  // 接続助詞はそのまま。終助詞が付いた形（「できるのにね」「いいのにな」）も同じなのだ。
  // 「のに」は後ろに続くはずの節が省かれた言いさしで、終助詞が添えられても
  // 「のに」が接続助詞であることは変わらないのだ。
  // 番人が終助詞まで見ていないと、裸の「のに」は無変換に留まるのに
  // 「のにね」だけが下の字形の判定まで落ちて「できるのにねなのだ」という
  // 接続助詞に断定が接いだ非文になるのだ
  [/(ので|のに)(?:なあ|ねえ|ね|な|よ|さ)?$/u, "$&"],
  // 限定・例示・不定の副助詞＋「で」は手段・範囲の中止法で文が続く
  // （「この3時間だけで」「日付の話かなんかで」を文末とみなさないのだ）
  [/(?:だけ|のみ|など|ほど|くらい|ぐらい|なんか|とか|か)で$/, "$&"],
  // 関西・中部の念押しの終助詞「で」（＝共通語の「よ」）。
  // 「しっかり応援できるで」→「応援できるのだ」。
  // 直前を「る」「た」に限るのだ。テ形の「んで」「いで」は上で除いてあるが、
  // 他のう段（「近くで」「1個ずつで」）は場所・手段の格助詞「で」を伴う体言と
  // 重なって分けられないからなのだ。副詞の「まるで」だけは除くのだ
  [/(?<!まる)([るた])で$/u, "$1のだ"],
  [/で$/, "なのだ"], // 「すごい状態で」の中止形は断定に戻す
  // 一段動詞の命令形は終止形に直してから付ける（「見せろのだ」を防ぐ）
  [/([えけげせぜてでねへべめれ])ろ$/, "$1るのだ"],
  // それ以外の「〜ろ」は五段の命令形（「がんばれ」系ではない「頑張ろ」）か
  // 意向形の口語短縮で、終止形が復元できないので触らない
  [/ろ$/, "$&"],
  // ★ 程度の補助動詞「すぎる」の連用形＋「て」は依頼にならないのだ。
  // 承認版は下の2つの規則（「て＋終助詞」と行末の裸のテ形）で
  // 「かっこよすぎて」→「かっこよすぎてほしいのだ」と依頼に開いていたが、
  // 「早すぎてほしい」「かっこよすぎてほしい」は非文なのだ——
  // 「〜てほしい」は相手に働きかけて事態を起こさせる形なのに、
  // 「すぎる」は話し手が程度を評価する形で、起こさせる相手がいないからなのだ。
  // ここのテ形は中止法（後ろに続く節が省かれた言いさし）で、
  // 形容詞の「〜くて」（「あまり機会がなくて」→「ないのだ」）とまったく同じ扱いなのだ。
  // 「すぎる」はガ行上一段（すぎ／すぎ／すぎる／すぎる／すぎれ／すぎろ）なので、
  // 連用形「すぎ」に「る」を足せば終止形が復元できるのだ。
  // 仮名の「すぎ」に限るのだ。漢字で書かれた「過ぎて」は本動詞で、
  // そちらは働きかける相手のある事態を指せるので依頼になれるのだ
  // （「早く過ぎてほしい」「電車が通り過ぎてほしい」はどちらも自然な文なのだ）。
  // 仮名で「すぎ」と書かれた本動詞（「30すぎて」）はこの規則に入るが、
  // 同じ上一段なので復元先は「すぎるのだ」で変わらないのだ。
  // 仮名の「すぎ」で終わる体言・助詞は無いので、これ以上の番人は要らないのだ
  // （「杉」「スギ」は漢字・カタカナで書かれ、体言に「て」は接がないのだ）
  [/すぎて(?:よね|よな|[よね])?$/u, "すぎるのだ"],
  // 文末のテ形＋終助詞は依頼なのだ（「ぼくが起きてから塗ってよ」
  // 「一言も添えてね」）。裸のテ形と違って終助詞が付いていれば、
  // 中止法（「名付けて さくらスクリプト」）や言いさし（「無事に帰れて」）ではなく
  // 聞き手に向けた依頼だと決まるので、「〜てほしいのだ」に開けるのだ。
  // ただしタ行五段の命令形＋「よ」（「待てよ」「立てよ」）と表層が同じなのだ。
  // 「て」がテ形の助詞なのかタ行の活用語尾なのかは活用表が答えを持っているので、
  // 直前がタ行五段の語幹かどうかで分けるのだ。
  // ★ 終助詞は2つ重ねられるのだ（「ちゃんと見てよね」「早く来てよな」）。
  // 用言＋終助詞（yrStop）も断定＋終助詞（nd）も既に2連を許しているのに、
  // 依頼のテ形の側だけが1つで止まっていたのだ。1つしか許さないと
  // 「見てよねなのだ」と終助詞を抱えたまま断定が接がれるのだ
  [
    /て(?:よね|よな|[よね])$/u,
    // 3分岐なのだ。タ行の語幹＋「て」は、命令の位置なら命令形（待てよ→待つのだ）、
    // 位置が違えば連用形名詞（一戸建て・子育て）で、そこに「ほしい」を接ぐと
    // 「一戸建てほしいのだ」という非文になるので無変換で止めるのだ
    (m, off, str) =>
      isGodan("ち", off, str)
        ? isTaImperative(off, str)
          ? "つのだ"
          : m
        : "てほしいのだ",
  ],
  // 撥音便・イ音便のテ形（「読んでよ」「急いでね」）も同じ依頼なのだ。
  // 疑問詞の「なんでよ」を巻き込まないよう「な」の直後だけ除くのだ
  [/(?<!な)([んい]で)(?:よね|よな|[よね])$/u, "$1ほしいのだ"],
  // 五段の命令形＋終助詞「よ」は、え段をう段に戻せば終止形になる
  // （「己から振っていけよ」→「振っていくのだ」）。
  // 「て」は上のテ形で処理済みなので、ここでは扱わないのだ。
  // ★ え段＋「よ」は一段動詞の意向形・命令形でもあるのだ
  //   （「お風呂入ってねよ」＝「寝よう」、「食べよ」「見せよ」）。
  //   え段を無条件にう段へ戻すと、一段動詞の語幹まで書き換えて
  //   「入ってぬのだ」という非文になるのだ。
  //   分かれ目は え段の直前がその行の五段語幹かどうかで、活用表が答えを持っているのだ
  //   （「振ってい」はカ行五段の表にあり、「お風呂入って」はナ行五段の表＝「死」に無い）。
  //   表に無ければ一段なので、終止形（え段＋「る」）は復元できても
  //   意向形か命令形かが決まらないので触らないのだ
  [
    /([けげせねべめれ])よ$/,
    (m, c, off, str) =>
      isGodan(E_TO_I[c], off, str) ? GODAN_ROW[E_TO_I[c]].u + "のだ" : m,
  ],
  // 一段の命令形・意向形「〜ろよ」「〜えよ」は終止形を復元できないので触らない
  // （「見てろよ」「食べよ」）
  [/([えけげせぜてでねへべめれろ])よ$/, "$&"],
  // 五段の命令形は終止形（う段）に直してから付けるのだ
  // （「うわ死ね」→「うわ死ぬのだ」「お前が直せ」→「お前が直すのだ」）。
  // 命令を叙述に変えてしまうが、ずんだもん語尾は言い切りの形しか持たないのだ
  [
    IMPERATIVE_RE,
    (m) => m.slice(0, -1) + GODAN_ROW[IMPERATIVE_ROW[m.slice(-1)]].u + "のだ",
  ],
  // サ変の口語命令「〜しな」は終止形に直す（「法人契約しな」→「法人契約するのだ」）。
  // 直前を漢字・カタカナに限るのは「はなしな」のような語中の「し」を拾わないため
  [/([一-龯々ァ-ヺ])しな$/, "$1するのだ"],
  // ラ行五段の未然形＋口語否定「ね」（「いらね」「わからね」「知らね」）は
  // 常体に戻してから付ける。他の行（「かね」「たね」「まね」）は名詞と紛れるので
  // ラ行だけにするのだ
  [/らね$/, "らないのだ"],
  // 間投助詞「さあ」で終わる行は呼びかけの途中なので触らない（「話題はさあ！」）
  [/さあ$/, "$&"],
  // テ形＋「こ」は補助動詞「いく」の意向形の口語短縮なのだ
  // （「アウトカウント増やしてこ」＝「増やしていこう」）。
  // 「〜ちゃお」と同じ縮約なので、同じように終止形に戻すのだ。
  // 「こ」で終わる体言（「そこ」「たまご」）はテ形の直後には立てないのだ。
  //
  // ただし「取ってこ」「買ってこ」「行ってこ」は「〜てくる」なのだ
  // （「〜てこい」の命令形の縮約）。表層は「〜てこ」で完全に同じで、
  // 分かれ目は補助動詞が「いく」か「くる」かという意味だけなのだ。
  // 活用表には答えが無く、前の動詞の語彙で決まる（取得・移動の動詞は「くる」）ので、
  // 語彙表を足さない限り分けられないのだ。
  // 無変換に逃がす手もあるが、それは正しく直せている「増やしてこ」まで失う上に、
  // 「〜ていく」に倒しても出るのは意味のずれで非文ではないのだ。
  // 多いほうの「いく」に倒したままにして、この衝突を記録として残すのだ
  [/([てで])こ$/u, "$1いくのだ"],
  // 「〜ちゃお／〜じゃお」は「〜てしまう」の意向形の口語短縮なので終止形に戻す
  // （「呑んじゃおー」→「呑んじゃうのだ」）
  [/([じち])ゃお$/, "$1ゃうのだ"],
  // 「〜ちゃえ／〜じゃえ」は同じ「〜てしまう」の命令形なので、同じく終止形に戻す
  // （「たべちゃえ」→「たべちゃうのだ」）
  [/([じち])ゃえ$/, "$1ゃうのだ"],
  // 意向形の促音化（「しよっ」「食べよっ」）を終止形に戻す規則は置かないのだ。
  // 直前の1字だけでは意向形と、テ形＋終助詞「よ」＋促音（「やめてよっ」「聞いてよっ」）
  // が区別できず、依頼を進行相の叙述に変えてしまうからなのだ。下の「っ」で無変換にする
  // 促音「っ」は語末に立たない音なので、行末の「っ」は言いさし・引き伸ばしの印
  // （「行こっ」「ちょっ」）。元の活用が復元できないので触らないのだ
  [/っ$/u, "$&"],
  // 仮定形は必ずえ段＋「ば」（「直さなければ」「あれば」）。条件節は言いさしで
  // 文末ではないので触らない（「直さなければなのだ」を防ぐ）
  [/[えけげせぜてでねへべめれ]ば$/u, "$&"],
  // 文語の禁止「〜べからず」は連体形「べからざる」を持つ助動詞「べし」の未然形＋
  // 打消で、現代語の「のだ」を接続できないのだ（「食べるべからずのだ」を防ぐ）。
  // 慣用句として引用される形なので無変換が妥当なのだ
  [/べからず$/u, "$&"],
  // 「ず」で終わる語は用言の終止形ではないのだ。現代語に ザ行五段は無く、
  // 「〜ずる」型（「命ずる」）の終止形は「る」で終わるからなのだ。
  // 文末の「ず」は文語の打消（「うににあらず」「一個にせず」）か、
  // 逆接の接続句（「にもかかわらず」）か、体言の一部（「みず」「くず」）なのだ。
  // 打消・接続句は文が言い切られていないので「のだ」を接げず、
  // 体言かどうかは字形では決められないので、まとめて触らないのだ。
  // 形式名詞の「はず」だけは上で体言として処理済みなのだ
  [/ず$/u, "$&"],
  // サ変の意向形「しよう」の口語縮約「〜しよ」なのだ（「半田付けしよ」＝「半田付けしよう」）。
  // 縮約なので終止形は「する」に戻せるのだ。
  // 五段の意向形（お段＋「う」）を活用表で開いたのと同じ扱いで、意向（勧誘）を
  // 平叙に変えてしまうが、ずんだもん語尾は言い切りの形しか持たないのだ。
  // ★ 「しよ」は体言の末尾（「ひしよ」）とも字形が重なるのだ。分かれ目は直前にあるのだ——
  // サ変の語幹は漢語かカタカナ語なので、直前は 漢字・カタカナ か、述語の前に置ける助詞 か
  // 文頭に限られるのだ（「旅しよ」「脱線しよ」「気にしよ」）。
  // これはサ変の口語否定「せん」（SEN_NEGATION）とまったく同じ番人なのだ。
  // ★ 全部「しよう」に開けるわけではないのだ。素の「しよう」は「仕様」「使用」と
  // 同じ字形なので開けないままなのだ（下の一段の意向形の註と同じ理由なのだ）。
  // 縮約の「しよ」にはその紛れが無い——「仕様」「使用」を「しよ」とは書かないからなのだ
  // ★ 表記の見張りだけでは足りないのだ。「しよ」の「し」が動詞ではなく
  // 直前の語の末尾である読みが3つ残るのだ。どれも表で落とせるのだ。
  //   ① サ行五段の連用形名詞＋終助詞「よ」（「私の暮らしよ」「お話しよ」）。
  //      「し」の手前がサ行五段の語幹かを活用表に問うのだ
  //      （「暮ら」はサ行の表にあり、「植樹」「半田付け」は無いのだ）
  //   ② 用言の終止形＋接続助詞「し」＋終助詞「よ」（「知らないしよ」「安いしよ」
  //      「行くしよ」）。接続助詞「し」は終止形に付くので、直前を isYogenEnd に
  //      問えばよいのだ。裸の「〜し」を無変換に留めている番人と同じ問いなのだ
  //   ③ 形容詞「無し」と断定「だ」＋接続助詞「し」（「宿題なしよ」「集団だしよ」）。
  //      どちらも1語の形態素なので名指しで除けるのだ（開いた類ではないのだ）
  [
    new RegExp(SAHEN_LEAD + "しよ$", "u"),
    (m, off, str) => {
      const head = str.slice(0, off);
      // ★番人は SA_SHUSHI_RE で問うのだ。isGodan("し") は「直前が漢字なら除く」
      // という漢語サ変ガードを内側に持っているので、漢字が直に先行する複合語
      // （物差し・一人暮らし・恩返し）では必ず false を返すのだ。ところが
      // SAHEN_LEAD が通すのはまさにその「漢字が先行する語」なので、
      // 番人と規則が別のものを見ていて素通りしていたのだ（「物差しよ」→「物差するのだ」）
      return SA_SHUSHI_RE.test(head) || isYogenEnd(head) || /[なだ無]$/u.test(head)
        ? RULE_PASS
        : "するのだ";
    },
  ],
  // 一段の意向形は 連用形＋「よう」なのだ（「ネットの森を広げよう」「食べよう」）。
  // え段は活用語尾にしか現れない形なので、え段＋「よう」なら一段動詞と決まるのだ
  // （isYogenEnd が「え段＋る」を一段と認めているのとまったく同じ番人なのだ）。
  // 終止形は え段＋「る」なので、語幹に触れずに戻せるのだ。
  // ★ い段＋「よう」は開かないのだ。上一段の意向形（「起きよう」）と
  // 仮名書きの体言（「ないよう」＝内容、「りよう」＝利用、「きよう」＝器用）が
  // 同じ字形で、活用表には上一段の語幹を数え上げる列が無いからなのだ。
  // サ変の「しよう」も同じ理由で開かないのだ（「仕様」「使用」と同じ字形なのだ）
  [/([えけげせぜてでねへべめれ])よう(?:ね|な|にゃ|よ|ぜ|ぞ)?$/u, "$1るのだ"],
  // 五段の意向形は お段＋「う」なのだ（「ポカリスエット飲もう」「今日も頑張ろう」
  // 「みんなもカスタム絵文字を使おう」「今日も楽しくいこう」）。
  // ★ 承認版はここを無変換にしていたのだ。理由は「お段の直後の『う』は
  // 『そう』『どう』『ありがとう』と字形が紛れる」だったのだ。
  // だが意向形は活用表で引けるのだ。お段は未然形の変異で、行は連用形（い段）と
  // 同じなのだから、お段を い段に写して語幹表に問えばよいのだ
  //   飲も→飲み（マ行の表にある）／ ありがと→ありがち（タ行の表に無い）
  //   や→やり（ラ行の表にある）／ そ・ど・こ（語幹が空なので表に無い）
  // 意向（勧誘）を平叙に変えてしまうが、ずんだもん語尾は言い切りの形しか
  // 持たないのだ。五段の命令形を終止形に直しているのと同じ扱いなのだ。
  // ★ サ行（そ）も入れるのだ。以前は「『話そう』は意向形とも様態の『そう』とも
  // 読めて活用表はどちらとも答えない」として外していたのだが、それは半分しか
  // 正しくなかったのだ。立つ位置が違うからなのだ——
  //   意向形の「そ」は サ行五段の語幹 の直後（話そう・返そう・壊そう・渡そう）
  //   様態の「そう」は 形容詞の語幹 か 連用形 の直後（高そう・負けそう・詰まってそう）
  // 「話」はサ行五段の語幹表にあり、「高」は無いのだから、表は答えを持っているのだ。
  // 表に載っていないものは下の様態の「そう」の規則がそのまま受け持つのだ。
  // 残る真の紛れは、サ行五段と一段が対を成して連用形が語幹と同形になる語だけなのだ
  //   出そう（出す の意向形／出る の連用形＋様態）／汚そう（汚す／汚い の語幹）
  // ハ行（ほ）は外したままなのだ。現代語にハ行五段は無く（ワ行に移った）、
  // 「ひ」の語幹表そのものが存在しないからなのだ。
  // ★ 表が「用言ではない」と答えたときは番人（無変換）ではなく RULE_PASS で
  // 降ろすのだ。「そ」を入れたことで、この規則は様態の「そう」（「高そう」）にも
  // 字形として当たるようになったからなのだ。番人のまま降ろすと
  // 「高そうなのだ」を作る下の規則まで届かなくなるのだ。
  // 「そ」以外の お段（ありがとう・行こう…）では、降りた先にある規則が
  // どれも「そう」を見る規則なので当たらず、最後の番人（お段＋「う」）に落ちて
  // 承認版と同じ無変換になるのだ
  [
    /([おこごそとのぼもろ])う(?:ね|な|にゃ|よ|ぜ|ぞ)?$/u,
    (m, c, off, str) =>
      isGodan(O_TO_I[c], off, str)
        ? GODAN_ROW[O_TO_I[c]].u + "のだ"
        : RULE_PASS,
  ],
  // 意向形＋終助詞（「元気にすごそうね」「終わらせよーぜ」）は活用を復元できないので
  // 触らない。長音符で引き伸ばした「よー」「こー」も同じ意向形なのだ。
  // ★ 上の2本（活用表で行が決まる意向形）に当たらなかったものだけがここに落ちるのだ
  [/[おこごそぞとどのほぼもろよ][うー](?:ね|な|にゃ|よ|ぜ|ぞ)$/, "$&"],
  // 様態の「そう」の前に接尾辞「さ」が立つのは、形容詞「ない」「よい」の2語だけなのだ
  // （「寛容ではなさそう」「改善しなさそう」／「動くならよさそう」）。
  // 他の形容詞は語幹に直に付く（「高そう」であって「高さそう」ではない）ので、
  // 「〜さそう」という形はこの2語からしか出てこない閉じた集合なのだ。
  // ★ 承認版がこの類を無変換にしていたのは、様態の「そう」を
  // 「連用形（い段）＋そう」の形でしか見ていなかったからなのだ。
  // 「なさ」「よさ」の「さ」は あ段なのでその形に当たらず、規則が届いていなかったのだ。
  // 様態の「そう」は形容動詞のようにふるまうので、下の「高そう」と同じく
  // 「なのだ」を挟むのだ
  [/[なよ]さそう$/u, "$&なのだ"],
  // 口語では接尾辞「さ」を挟まない形もあるのだ（「ビニールはガサガサいわなそう」
  // ＝「言わなそう」）。この「な」が否定の「ない」の語幹であることは、
  // その直前が未然形かどうかで決まるのだ——五段の未然形は あ段、
  // 一段・可能動詞の未然形は語幹と同形の え段なのだ。
  // 口語否定の「ねえ」（「止まらねえ」）とまったく同じ問いを活用表に投げるのだ
  // （「いわ」の「わ」→「い」はワ行の表にあり、「みんな」の「ん」は表に無い）。
  // 表で確かめられない「な」は連体形の「な」か体言の末尾なので、
  // そこの「そう」は指示語（「みんなそう」）として下の規則に任せるのだ
  [
    /([わかがさたなばまら]|[えけげせてねべめれ])なそう$/u,
    (m, c, off, str) =>
      (A_TO_I[c] !== undefined && isGodan(A_TO_I[c], off, str)) ||
      (E_TO_I[c] !== undefined && isGodan(E_TO_I[c], off, str))
        ? m + "なのだ"
        : RULE_PASS,
  ],
  // 様態・伝聞の「〜そう」は形容動詞的にふるまうので「なのだ」を付ける
  // （「かなり高そう」→「かなり高そうなのだ」）。
  // 漢字の直後に限るのは、ひらがなが続く「すごそう」「過ごそう」が
  // 様態か意向形か判別できず、「そうそう」まで巻き込むからなのだ。
  // ★ カタカナ語幹も同じなのだ（「うにゅう剥いたら結構グロそう」＝「グロい」の語幹）。
  // 様態の「そう」が付くのは連用形だけではなく、形容詞・形容動詞の語幹にも付くのだ。
  // 語幹が仮名だけだと切れ目が読めないという上の理由は、書き分けられている
  // カタカナには当たらないのだ——漢字語幹に当たらないのとまったく同じ理屈なのだ。
  // 意向形（サ行五段の「話そう」）の語幹がカタカナで書かれて「そ」だけ
  // ひらがなに落ちる、という書き方は無いのだ
  [/([一-龯々ァ-ヺーゝゞ])そう$/u, "$&なのだ"],
  // テ形の直後の「そう」は必ず様態・伝聞（意向形はテ形に続けられない）ので、
  // ひらがなが続いていても迷わず形容動詞扱いにできるのだ
  // （「詰まってそう」→「詰まってそうなのだ」）
  [/([てで])そう$/, "$&なのだ"],
  // い段・え段の直後の「そう」も様態・伝聞なのだ。様態の「そう」は連用形に付き、
  // 五段の連用形は い段、一段の連用形は い段・え段だからなのだ
  // （「負けそう」「なりそう」「落ちそう」「うれしそう」「すきそう」）。
  // 紛らわしいのは意向形の「〜そう」だけで、それはサ行五段（「話そう」「探そう」）に
  // 限られるのだ。他の行の意向形は「〜こう」「〜もう」のように別の仮名になるからなのだ。
  // だからサ行五段の語幹表を引いて、載っている時だけ意向形として避けるのだ。
  // お段の直後（「すごそう」「過ごそう」）は語幹の切れ目が読めないので下の番人に流す
  [
    /[いきぎしちにひみりじびぴえけげせぜてでねへめれべぺ]そう$/u,
    (m, off, str) => (isGodan("し", off + 1, str) ? m : m + "なのだ"),
  ],
  // 意向形「行こう」「しよう」や「〜そう」「ありがとう」は活用が判別できないので触らない
  [/([おこごそぞとどのほぼもろよ])う$/, "$&"],
  // 用言＋準体助詞「の」は説明・問いかけの言い切り（「ついてないんじゃないの」）。
  // 属格の「の」（「私の」）は用言で終わらないので下の番人に落ちて無変換になるのだ。
  // 番人の「の」より先に置かないと横取りされるのだ
  yr("の", "$1のだ？"),
  // 口語否定の「ん」＋準体助詞「の」（「何とかならんの」）を開く規則は置かないのだ。
  // 「ん」の直前の段を未然形に限っても名詞は除けない（「みかんの」「ごはんの」の
  // 「か」「は」も同じ段）ので、属格の「の」を疑問に変えてしまうからなのだ
  // 助詞・接続助詞で終わる行は文が途中なので変換しない（「時もなのだ」を防ぐ）。
  // 「と」は入れていない。「えんどれすえいと」のように「と」で終わる体言と
  // 区別できず、そちらを無変換にしてしまうからなのだ
  // 「たら」は過去の助動詞「た」の仮定形で、「ば」と同じ条件の言いさしなのだ
  // 断定「だ」＋逆接の言いさし「が」（「サブ垢どころか別SNSも無理だが」）。
  // 「〜んだが」（nd で処理済み）とまったく同じ言いさしで、後ろに続くはずの節が
  // 省かれた形なのだ。文はそこで終わっているので断定に開くのだ。
  // 直前が「の」「な」なら既に言い切りの一部（「〜のだが」「〜なのだが」）で、
  // そこに重ねると「〜のなのだが」と断定が二重になるので除くのだ。
  // 下の助詞止めの番人（「が」）より先に置かないと無変換に落ちるのだ
  // 「〜んだが」「〜いだが」の「だ」は断定ではなく音便の直後で濁った過去なのだ
  // （飲んだ・泳いだ）。断定と読むと「飲んなのだが」と語幹が壊れるので、
  // 活用表に問うて分けるのだ（isOnbinPast）
  [/(?<![のな])だが$/u, daSplit("だが")],
  // 断定「だ」＋接続助詞「し」の言いさし（「実質リレーに集まってる集団だし」
  // 「あすけんはもう三日坊主だし」）。並べるはずのもう一つの節が省かれた形で、
  // 文はそこで終わっているのだ。上の「だが」・下の「だけど」とまったく同じ形なので、
  // 同じ daSplit に通すのだ——「読んだし」の「だ」は断定ではなく音便の直後で濁った
  // 過去なので（飲んだ・読んだ）、断定と読むと「読んなのだ」と語幹が壊れるからなのだ。
  // 「が」「けど」と違って「し」は残さないのだ。「し」は節を並べる助詞で、
  // 逆接のように前の節だけで意味が完結する形ではないからなのだ
  // （「集団なのだし」は宙に浮くが、「集団なのだ」は言い切れているのだ）。
  // 直前が「の」「な」なら既に言い切りの一部（「〜のだし」「〜なのだし」）なので除くのだ。
  // ★ 用言の直後の「だし」は非文なので（「行くだし」とは言わない）、
  // 受けるのは体言側と音便過去だけでよいのだ。残る紛れは体言の「出汁」だけで、
  // それは前部が体言という点で断定とまったく同じ形をしていて表では分けられないのだ
  [/(?<![のな])だし(?:なあ|ねえ|ね|よ|な|さ)?$/u, daSplit("だ")],
  // 形容詞の連用形「〜く」＋接続助詞「て」で行が終わっていれば言いさしなのだ
  // （後ろに続くはずの節が省かれた形。「あまりイカやる機会がなくて」）。
  // 下の番人が「て」を無変換に留めているのは、文末のテ形に依頼（「詳しく教えて」）が
  // あって叙述に変えると意味が反転するからなのだ。その理由はここには当たらないのだ——
  // 形容詞は依頼にならないからなのだ。カ行五段のテ形はイ音便で「〜いて」になるので、
  // 「くて」という形は形容詞の連用形にしか現れないのだ（「書くて」という活用は無い）。
  // 終止形に戻すのは連用形の「く」を「い」に替えるだけなのだ
  // （「なくて」→「ない」「暑くて」→「暑い」「したくて」→「したい」）。
  // 「〜くって」は入れないのだ。仮名で書かれたワ行五段の促音便（「食って」）と
  // 字形が同じで、そちらは語幹まで書き換えてしまうからなのだ。
  // 「〜んくて」も入れないのだ。これは口語否定「〜ん」＋「くて」（「わからんくて」＝
  // 「わからなくて」）で、「く」を「い」に替えると「わからんいのだ」と語幹が壊れるのだ。
  // 正しくは「わからないのだ」だが、「ん」を「ない」に開くのは別の機構の仕事なので、
  // ここでは承認版と同じ無変換に留めるのだ
  [/(?<!ん)くて$/u, "いのだ"],
  // 複合助詞（格助詞＋動詞のテ形が一語になったもの）で終わる行は文の途中なのだ
  // （「〜漢字の扱いは…問題について」「怒っていい相手かどうかは別として」
  // 「なごや発のアーバンライナーにて」）。
  // 下の裸のテ形の規則に食われると「についてほしいのだ」という非文になるのだ。
  // 助詞は閉じた類なので数え上げられるのだ——ここが「〜て」で終わる副詞
  // （「初めて」「かえって」「すべて」）と違うところなのだ。副詞のほうは開いた類で、
  // 数え上げる道が無いままなのだ。
  // 促音便の形（「にとって」「をもって」「に従って」）はここに要らないのだ。
  // 下の規則が初めから「って」を見ないからなのだ
  [/(?:に(?:おい|つい|対し|関し|際し|加え|基づい)|とし|を(?:除い|含め))て$/u, "$&"],
  [/にて$/u, "$&"],
  // 丁寧の「ます」の連用形＋接続助詞「て」は必ず中止法なのだ
  // （「ホームにきてまして」「ナマコポケットに収納されてしまいまして」）。
  // 依頼の「〜てほしい」は丁寧の外側に立つので（「〜ていただきたい」）、
  // 「〜ましてほしい」という形は活用表のどこにも無いのだ。
  // 直前が連用形の語尾であることを求めるのは、「だます」「かます」のように
  // 「ます」が語幹の一部の五段サ行動詞（そのテ形は「だまして」）を除くためなのだ。
  // 上の「ます」の規則群と同じ番人なのだ
  [new RegExp(`${MASU_STEM_CLASS}まして$`, "u"), "$&"],
  // 行末に単独で立つテ形は依頼なのだ（「ライトニングアドレス設定して」
  // 「Zap先のアドレスをリプで教えて」「ちょっと待ってて」）。
  // ★ 承認版はここを無変換にしていたのだ。理由は上（「ないで」の下）に書いてある
  // とおり「終止形に直すと依頼が叙述に変わって意味が反転する」だったのだ。
  // その理由は「設定して」→「設定するのだ」への反論としては正しいが、
  // 「〜てほしいのだ」は依頼のままなので、この言い換えには当たらないのだ。
  // 既に「て＋終助詞」（「塗ってよ」「添えてね」）をこの形に開いてあるのだから、
  // 終助詞が無いだけの裸のテ形も同じ形に開けるのだ。
  // 「て」がテ形の助詞かタ行五段の活用語尾（命令形「待て」）かは活用表が
  // 答えを持っているので、上の「て＋終助詞」と同じ分け方をするのだ。
  // 直前がテ形を作れる形（イ音便・サ行・一段の連用形・漢字語幹）であることを
  // 求めるのは、裸の「て」が「なんて」「うんてん」のような仮名書きの体言の
  // 途中にも現れるからなのだ（TE_CONTRACT と同じ見張りなのだ）。
  // ★ 促音便（「って」）だけは初めから外すのだ。引用の「って」（＝「と」の口語形。
  // 「いいよって」「9日前ですって」「無職って」）と字形がまったく同じで、
  // しかも活用表が答えを持たないからなのだ——促音便の語幹は仮名書きが多く
  // （「がんばって」「ひっぱって」「とって」「やって」）、表に載るのは漢字語幹だけなのだ。
  // 全コーパス6373件で測ると、開いた場合は改善12・悪化27だったのだ。
  // ★ "final" の印は、この規則を「文末だと分かっている行」に限るためなのだ。
  // 中止法（「名付けて さくらスクリプト」）は空白の手前の断片として来るので、
  // そこで降ろせば分かれるのだ
  [
    new RegExp(`(?<=[一-龯々${ICHIDAN_LEAD_CHARS}])て$`, "u"),
    (m, off, str) =>
      isGodan("ち", off, str)
        ? isTaImperative(off, str)
          ? "つのだ"
          : m
        : m + "ほしいのだ",
    "final",
  ],
  [/(から|けれども|けれど|けど|より|とか|たり|たら|なら|ながら|まま|が|を|に|へ|は|の|も|て)$/,
    "$&"],
  // 終助詞の直後の「と」は引用の助詞で、後ろに続くはずの「思う」「言う」が
  // 省かれた言いさしなのだ（「相性と良し悪しってあるんやなと」）。
  // 「〜ないと」「〜なきゃ」と同じく、省かれた述語を補って言い切りにするのだ。
  // 体言はこの位置（終助詞）で終わらないので、「えんどれすえいと」のような
  // 「と」で終わる語を巻き込まないのだ
  [/([なねよわ])と$/u, "$1と思うのだ"],
  // 断定の「だ」＋「と」は条件節か引用の言いさしで、文末ではないのだ
  // （「〜とかだと」「雨だと困る」の前半、「バカだと言われた」の引用）。
  // 断定の直後という位置なので体言の末尾ではありえず、
  // 「えんどれすえいと」のような「と」で終わる語を巻き込まないのだ。
  // 「だとなのだ」という壊れた語形を防ぐ番人なのだ
  [/だと$/u, "$&"],
  // 漢字を含む語に続く「と」は引用・条件の言いさしなので触らない
  // （「〜であっても流入すると」）。漢字を要求するのは「てすとてすと」
  // 「えんどれすえいと」のような「と」で終わる体言を巻き込まないためなのだ
  [/[一-龯々][ぁ-ゖ]{0,2}と$/u, "$&"],
  // 全角スペースの後ろが数字と年月日だけの行末は、見出しに添えた日付ラベルなので
  // 断定の対象ではない（「…下半身露出未遂　６月２９日」）
  [/　[0-9０-９]+[年月日][0-9０-９年月日]*$/u, "$&"],
  // ★ 用言の終止形＋接続助詞「し」の言いさし（「おめめちゃんがいるし」
  // 「被害を被る人はほぼいないし」）。並べるはずのもう一つの節が省かれた形で、
  // 文はそこで終わっているのだ。
  // 上にある 体言＋断定「だ」＋「し」（「集まってる集団だし」）とまったく同じ
  // 言いさしなのだ。体言側だけが開いていて、その対である用言側が抜けていたのだ。
  // 「し」を残さないのも体言側と同じ理由なのだ——「し」は節を並べる助詞で、
  // 逆接の「が」「けど」のように前の節だけで意味が完結する形ではないからなのだ
  // （「いるのだし」は宙に浮くが、「いるのだ」は言い切れているのだ）。
  // ★ 番人は活用表なのだ。「し」はサ行五段の連用形の語尾とも同形で
  // （「話し」「暮らし」「増し」「物差し」）、そちらは連用中止か連用形名詞であって
  // 言いさしではないのだ。直前を isYogenEnd に問うて、用言の終止形と
  // 確かめられた時だけ開くのだ（「いる」「ない」「安い」は表にあり、
  // 「わた（わたし）」「はな（はなし）」「むか（むかし）」は無いのだ）。
  // 表で決着しなかったものは RULE_PASS で降ろして、下の字形の番人に任せるのだ。
  // 番人のほうは向きが逆（表に無い語を降ろすと下の規則が変換してしまう）なので、
  // 字形のまま残さなければならないのだ——その理由は次の項に書いてあるとおりなのだ
  // ★ 終助詞の並びから「よ」だけは外すのだ。「〜しよ」はサ変の意向形の縮約
  // （「植樹しよ」＝「植樹しよう」）と字形がまったく同じで、そちらは上で
  // 別の規則が受け持っているのだ。表で決着しなかった「〜しよ」を承認版は
  // 無変換に留めているので（「知らないしよ」「これは安いしよ」）、
  // ここで横取りしてはいけないのだ。「ね」「な」「さ」には意向形との紛れが無いのだ
  // ★ 漢字の直後の「た」は過去と認めないのだ。isYogenEnd は「漢字＋た」を過去形と
  // 読むが（送り仮名を省いた「見た」「来た」のためなのだ）、その読みをここに通すと
  // 「果たし」「満たし」「きたし」の語幹の「た」まで過去に見えて
  // 「役目を果たのだ」と語幹が壊れるのだ。本物の過去は音便形（い・っ・ん・し）か
  // 一段の連用形（え段・い段）の直後に立つので、そちらだけを通せば
  // 「なくなったし」「切れたし」「殴ってきたし」は保たれるのだ
  [
    /し(?:なあ|ねえ|ね|な|さ)?$/u,
    (m, off, str) => {
      const head = str.slice(0, off);
      if (/[^ぁ-ゖ]た$/u.test(head)) return RULE_PASS;
      return isYogenEnd(head) ? "のだ" : RULE_PASS;
    },
  ],
  // 「安いし」の接続助詞「し」。これは変換する規則ではなく「この文は触らない」と
  // 決める番人なので、活用表に通してはいけないのだ。
  // 通す規則では「表で用言と確かめられた時だけ変換する」が安全側だが、
  // 番人では向きが逆で、表に無い語を降ろすと下の規則が変換してしまうのだ
  // （「なにしてんのわたし」の「た」は用言ではないが、番人が降りると
  //  「わたしなのだ」と変換されてしまうのだ）。字形のまま控えめに留めるのだ
  [new RegExp(`(${YOGEN})し$`), "$&"],
  // 漢字＋「し」は連用中止（「TKGみが増し」）か名詞なので、終止形を推測せず触らない
  [/([一-龯々])し$/, "$&"],
  // 「た」の直前が あ/う/お段 の仮名なら過去形ではありえないので体言扱い。
  // （過去の「た」の直前は い段・え段・「っ」・「ん」に限られる）
  // 「のすがた」→「のすがたなのだ」（「のすがたのだ」を防ぐ）
  [
    /([あかさたなはまやらわがざだばぱうくすつぬふむゆるぐずづぶぷおこそとのほもよろごぞどぼぽ])た$/,
    "$1たなのだ",
  ],
];

// 末尾の装飾（笑い・ラテン文字・数字・記号・絵文字・空白）を分離する
const DECOR_TAIL = /[\s\p{P}\p{S}\p{M}\p{Cf}A-Za-z0-9ｗ笑草]+$/u;
// URL・ハッシュタグを退避する不可視マーカー（どちらも書式制御文字 Cf なので
// 末尾の装飾として切り離される）。
// URL とハッシュタグを別のマーカーにするのは、末尾に URL が付く行だけを
// 「共有・告知の定型行」とみなしたいからなのだ。
// ハッシュタグは自分の文にタグを添えただけのことが多い（「ノルマ達成 #けだまメイズ」）
const URL_MARK = "⁠"; // WORD JOINER
const TAG_MARK = "﻿"; // ZERO WIDTH NO-BREAK SPACE
// ラテン文字だけで書かれた顔文字・笑い。日本語の直後に続いても語の一部ではないので、
// 本文に戻さず飾りのままにしておくのだ。
// 「w」は笑い、「orz」「OTL」は膝をついた人を象った落胆の顔文字なのだ。
// 本文に戻すと語尾が顔文字の後ろに付いて「忘れたorzなのだ」になるのだ
const FACE_LETTERS = /^(?:[wWｗ]+|[oO][rR][zZ]|[oO][tT][lL])$/u;
// 括弧の対応表（閉じ括弧の内側に語尾を挿し込まないための判定に使う）
const BRACKETS = [
  ["(", ")"], ["（", "）"], ["[", "]"], ["［", "］"],
  ["{", "}"], ["【", "】"], ["「", "」"], ["『", "』"], ["〈", "〉"],
];
// 感動詞・掛け声（そのまま残す）
const INTERJECTION =
  /^(よー*し|よし(?:よし)*|さー*て|うん(?:うん)*|ううん|はい(?:はい)*|いいえ|おー*|ふー*|わー*い|あー*|えー*|おっけー|おつ)$/u;
// 挨拶（そのまま残す）。挨拶語＋仮名の伸ばし・崩しだけの行に限る
// （「おやすみすとら」「おはようございます」など。「おはよう、今日は…」は対象外）
// ★ 「ございます」で終わる挨拶だけを丁寧語として開く版（「おはようございます」→
// 「おはようなのだ」）を試して戻したのだ。4470件で改善0・悪化19だったのだ。
// 「ございます」は挨拶の一部として崩されるからなのだ（「おはようございノス～」）。
// 崩しの形は無限にあって数え上げられないので、「ございます」が丁寧の補助動詞なのか
// 挨拶語の一部なのかは表層では決まらないのだ。
// 挨拶をまるごと無変換にするのは承認版の明示の判断で、活用テストにも
// 回帰コーパス18件にも書き留めてあるのだ
const GREETING =
  /^(おはよ|おやすみ|こんにちは|こんばんは|ただいま|おかえり|いってきま|いってらっしゃ)[ぁ-ゖァ-ヺー～]*$/u;
// 記号＋空白で始まる見出し・ラベル行（bot の定型データ投稿の「■ 流速計測」など）。
// 空白を必須にして「●今日は寒い」のような普通の文まで巻き込まないようにする
const HEADING_MARK = /^\s*[■□▼▽▲△▶◀●○◎◆◇★☆][ \t　]/u;
// 音符で始まる行（歌詞・CM の引用）。1行でもあれば投稿全体が引用とみなす
const LYRIC_LINE = /^[ \t　]*[🎵🎶♪♫♬]/mu;
// 隅付き括弧【】や記号で始まる見出し行を持つ投稿は bot の定型投稿とみなす
// （「【緊急地震速報】08:40」「■ 流速計測」）。
// 中の体言止めの行（「宮崎県北部平野部」「震度 5-」）はラベルと数値であって文ではないので、
// 引用ブロックと同じ扱いにして、用言・丁寧語で終わる行だけを変換するのだ。
const BOT_HEADING = /^[ \t　]*(?:【[^】]{2,20}】|[■□▼▽▲△▶◀●○◎◆◇★☆][ \t　])/mu;
// 音符で終わる行（時報・CM の擬音「ポォ～ン♪」）。
// 「楽しかった♪」のように単なる気分の飾りのこともあるので行全体は捨てず、
// 用言・丁寧語で終わらない体言止めの行だけを引用とみなす（下の fallback で使う）
const NOTE_TAIL = /[🎵🎶♪♫♬][ \t　]*$/u;
// 波ダッシュで引き伸ばしたカタカナ語は擬音（「ポォ～ン」「テロッテ～ン」）。
// 「～」を含む語は実在の名詞ではありえないので、擬音とみなして無変換にする
const ONOMATOPOEIA = /[ァ-ヺ][ァ-ヺー～〜]*[～〜][ァ-ヺー～〜]*$/u;
// ---------------------------------------------------------------------------
// 母音の引き伸ばし（長音化）
// ---------------------------------------------------------------------------
// 母音を伸ばすのは最後の1モーラに付いた韻律の印であって、語の一部ではないのだ。
// 仮名での書き方は3通りあるのだ。
//   長音符・波ダッシュ  「そうだよなー」「たのしー」   … 下の stretched で剥がす
//   小書きの母音仮名    「〜んだなぁ」「〜ですけどぉ」 … STRETCH_TAIL で剥がす
//   等大の母音仮名      「〜だけどねえ」「〜だよなあ」 … LONG_VOWEL_TAIL で剥がす
// 3つとも同じ音を表しているのだから、語尾の照合の前に一度だけ剥がして
// 出力に戻すのが筋なのだ。個々の規則の終助詞リストに「ねえ」「なぁ」を
// 書き足していくのは、同じことを規則の数だけ繰り返す数合わせなのだ。
//
// 小書き仮名で引き伸ばした感嘆・呼びかけの末尾（「まだぁ」「たのしぃ」「そうだよぉ」）。
// 小書きの母音仮名は現代語の正書法では語の一部になれない（拗音の「ゃゅょ」と違って
// 「ぁぃぅぇぉ」が語中・語末に立つ語は無い）ので、この字が末尾にある時点で
// 書き手が語尾を崩していると分かるのだ。長音「ー」だけの引き伸ばし
// （「いやー」「コーヒー」）は語の一部のこともあるので対象にしない
// （下の「ひらがな＋長音」の処理で別に扱う）。
const STRETCH_TAIL = /.[ぁ-ゖァ-ヺ][ぁぃぅぇぉ][ぁぃぅぇぉー～〜]*$/u;
// 等大の母音仮名で引き伸ばした末尾（「だよなあ」「言ってたなあ」「思いましたあ」）。
// 引き伸ばしの印であることの証は「直前の1字の母音を繰り返している」ことなのだ
// （な＋あ）。だから あ段の直後の「あ」に限るのだ。
// あ段は五段の未然形に現れる段だが、未然形は必ず後ろに助動詞が続く形で、
// 文末に裸で立つことは無いのだ。だから文末の「あ段＋あ」は引き伸ばしか
// 感動詞（「まあ」「さあ」）のどちらかで、感動詞は下の番人が落とすのだ。
//
// ★ 残りの4つの母音は入れられないのだ。どれも活用語尾そのものが同じ字だからなのだ。
//   「い」… 形容詞の終止形の語尾が い段＋「い」そのものなのだ（「おいしい」「ない」）
//   「う」… 五段の終止形の語尾が う段＋「う」（「食う」「吸う」）、
//           意向形・様態が お段＋「う」（「行こう」「そう」）なのだ
//   「お」… お段＋「お」は活用語尾には無いが、体言（「十（とお）」）とぶつかり、
//           引き伸ばしとしての用例（「そお」「もお」）は実データで拾えなかったのだ
//   「え」… え段＋「え」には引き伸ばしではない由来が2つあるのだ。
//           ひとつは連母音融合で、形容詞の語尾「〜あい／〜おい」が え段の長音に
//           融合した形なのだ（ない→ねえ、すごい→すげえ、たかい→たけえ、
//           ちいさい→ちいせえ）。この「え」は韻律の印ではなく活用語尾そのものなのだ。
//           もうひとつは終助詞・助詞を伸ばした形で、こちらは伸ばす前の1字
//           （「暑いぜえ」の「ぜ」、「学校でえ」の「で」）が語尾ではなく助詞なのだ。
//           規則表はこの2つを既に別々の枝で受け持っているので（口語否定の「〜ねえ」・
//           形容詞の口語音便・終助詞ぜ／格助詞で の番人）、
//           え段を一律に剥がすとその枝の手前を素通りしてしまうのだ。
//           実測したのだ——え段まで広げると活用テストが 落ちた -6 になるのだ
//           （脂汗が止まらねえ／そんな字は書かねえ／マイスリー2錠意味ねえ／
//            見ててねえ／今日は暑いぜえ／学校でえ。全コーパス13618件で20件が変化）。
//           「書かれたままの形を規則表が丸ごと述語として受け取ったか」を先に問う
//           番人を足すと連母音融合の3件は救えるが、助詞を伸ばした3件は残るのだ
//           （落ちた -3・18件変化。これも実測したのだ）。
//           え段は引き伸ばしの印と活用語尾・助詞が同居している段なので、
//           照合の前に一律に正規化することはできないのだ
const A_ROW = "ぁあかがさざただなはばぱまやゃらゎわ";
const LONG_VOWEL_TAIL = new RegExp(`[${A_ROW}]あ+$`, "u");
// 波ダッシュを3つ以上重ねた末尾（「ヨカね～～～♪」）だけに使う2つの字形の類なのだ。
// そこでは「引き伸ばす前の語尾が一意に決まるか」を字形で見分けているのだ
// （下の該当箇所の註を見るのだ）。丁寧語（「そうですね～～～」）と
// 用言＋終助詞（「すごいね～～～」）がその形なのだ
const STRETCH_RESTORABLE =
  /(?:です|ます|でしょう?|でした|ました|ませ[んょ])(?:ね|よ|か|けど|けれど)*$|から[なねよ]$/u;
const STRETCH_SFP = new RegExp(`${YOGEN}(?:よね|よな|よ|ね|な|わ)$`, "u");
// 短いひらがな語を長音・波ダッシュで引き伸ばしただけの文（「げっしょー」「おはのすー」
// 「かわい〜〜〜」）。引き伸ばす前の形（「かわい〜」＝「かわいい」）は復元できず、
// 長音を削ると「かわいのだ」「げっしょなのだ」と語を壊すので、丸ごと無変換にする。
// 4文字以下に限るのは、「うまかったー」のように活用が読み取れる長さの文まで
// 巻き込まないためなのだ。カタカナ語の長音（「インイヤー」「コーヒー」）は
// 語の一部なので対象外にする。
const SHORT_ELONGATED = /^[ぁ-ゖ]{1,4}[ー～〜]+[\s\p{P}\p{S}]*$/u;
// 短いひらがなだけの投稿は挨拶・造語・擬音（「おはのす」「ぴ」）で、品詞を決める
// 手掛かりが無いので触らない。その例外が「ん」で終わる語なのだ。
// 日本語の用言の終止形は「ん」で終わらないので、この形は体言と決まり、
// 「なのだ」を付けられる（「ぺこん」→「ぺこんなのだ」「はなきん」→「はなきんなのだ」）。
// ただし口語否定の「〜ん」（＝「ぬ」）は未然形に付くので、直前が「ら・か・せ・へ」の段なら
// 体言（「みかん」「やかん」）と否定（「わからん」「あかん」「せん」「へん」）が
// 区別できないのだ。迷う形は触らない。
// 断定・終助詞だけでできた投稿（「じゃん」「だもん」）も、語尾を落とすと内容語が
// 残らず「なのだ」だけになってしまうので、この例外から外すのだ
// 短くても丁寧の「ます」で終わる語は擬音・挨拶ではなく述語なのだ（「できます」）。
// ただし条件を3つ付けるのだ。
//   直前が連用形の語尾（MASU_STEM_CLASS）であること
//     ＝「ますます」の「す」のような語の一部の「ます」を除くため
//   その手前にもう1字あること
//     ＝1字の語幹では活用の種類が決められないからなのだ（「きます」は「来る」、
//       「みます」は「見る」で、い段の既定の五段に落とすと「くのだ」「むのだ」と語が消える）
//   活用表で行が確定すること（五段か上一段の表に載っていること）
//     ＝短い仮名書きは語の切れ目が読めず、形だけでは「ます」が丁寧の助動詞なのか
//       語幹の一部なのか決まらないのだ。「はげます」は五段サ行の終止形（励ます）、
//       「たします」は「足します」とも「たす」＋αとも読めるのだ。
//       表に無い語を既定のサ変・五段に落とすと「たするのだ」「おくのだ」と非文になるので、
//       行が決まらないものは丁寧形と認めず、短い投稿として無変換に戻すのだ。
//       え段（＝一段確定）も通さないのだ。「はげます」「だます」のように
//       え段＋「ます」で終わる五段サ行の終止形と区別が付かないからなのだ
const SHORT_POLITE = new RegExp(`[ぁ-ゖ](${MASU_STEM_CLASS})ます$`, "u");
const isShortPolite = (s) => {
  const m = SHORT_POLITE.exec(s);
  if (!m) return false;
  const off = m.index + 1; // 連用形の語尾の位置
  return isGodan(m[1], off, s) || isIchidan(m[1], off, s);
};
// 短くても過去形で終わる仮名の投稿は、擬音・挨拶ではなく述語なのだ（「ゆるした」
// 「ちかれた」）。過去の助動詞「た」の直前は い段・え段・促音・撥音に限られるので、
// 体言の末尾の「た」（「あなた」「ぶた」「うた」は あ段・う段）とは分けられるのだ
const SHORT_PAST = /[いきしちにひみりぎじびぴえけげせぜてでねへべめれっん]た$/u;
const SHORT_N_NOUN = /^[ぁ-ゖ]{2,3}ん$/u;
const AMBIGUOUS_N = /[らかせへ]ん$|^(?:じゃん|だもん)$/u;
// 投稿全体が助詞で始まるひらがなだけの短い断片（「のすがた」）。
// 直前の投稿に続けて書かれた体言止めなので、単独では文にならず変換できない。
// 語頭に立ちにくい「の」「を」に限る（「が」「に」「は」「も」だと
// 「がんばる」「はじまった」「もんぴ」のような普通の語を巻き込む）。
// 画像 URL や他の行を伴う投稿はそれだけで完結しているので対象外にする
// （「のりよし」＋画像のような短い題名を壊さないため）。
const FRAGMENT_POST = /^[のを][ぁ-ゖ]{1,4}$/u;
// 末尾に付いた対応の取れた括弧の注記（「幸せだよ(私の定義)」「おもしろい(笑)」）。
// 注記の内側に語尾を挿し込まないよう、装飾として切り離してから語尾を変換する。
// 顔文字の締めに使う踊り字（「(￣^￣)ゞ」）も一緒に切り離すのだ。
const TRAILING_NOTE =
  /[（(【［「『〈][^（(【［「『〈）)】］」』〉]*[）)】］」』〉][\sゝゞヽヾ]*$/u;
// 引用（メール・Markdown の「>」）で始まる行。
// 自分の文と併記された引用は他人の発言なので書き換えない（「> 検証しにくい」＋自分の返事）。
// ただし投稿全体が引用の場合は、その引用文こそが投稿の中身なので変換してよいのだ
const QUOTE_LINE = /^[ \t　]*[>＞]/u;
// 半角記号の箇条書き行。前後の行と1つの文をなす体言止めの断片であることが多いので
// （「だから marketplace 的には / - 公開募集で学習 / が自然そう」）、
// 引用ブロックと同じくルールに当たった時だけ変換する。
// 中黒「・」の箇条書きは完結した文が来るので対象にしないのだ
const ASCII_BULLET = /^[ \t　]*[-*+][ \t]/u;
// 文が途中で終わっている行（読点で終わる）。次の行に述語が続くので変換しない。
// 読点の後ろに記号・絵文字が続く行までここに含めてはいけないのだ。
// 「楽しい、😊」「行くよ、♪」は述語で言い切ったうえに気分の飾りを添えた行で、
// 読点の前が文末なのだ。記号まで含めて無変換にすると、それらが丸ごと落ちるのだ。
// 「うにゅう、🐯」が「うにゅうのだ」と誤って開いていたのは読点のせいではなく、
// 「うにゅう」を用言と読み違えていたせいなのだ（拗音＋「う」の判定で直したのだ）
const COMMA_END = /[、，][\s]*$/u;
// 材料・データの列挙ブロックを見つけるための行の判定。
// 助詞（文の骨格）を1つも含まず、用言の終止形でも終わらない短い行は、
// 文ではなくラベル・材料・作品名の断片なのだ（「梅みそ」「ショウガ」「震度 5-」）。
// ただし1行だけなら普通の体言止めの投稿（「ログボ」「やば言語」）なので、
// この形の行が3行以上続いた時にはじめて列挙ブロックとみなすのだ。
const PARTICLE = /[はがをにへともの]|から|まで|より/u;
const YOGEN_END = /[うくぐすずつぬふぶむるいたん]$/u;
function isListItemLine(line) {
  const t = line.replace(/[\s\p{P}\p{S}\p{M}\p{Cf}A-Za-z0-9]+$/u, "").trim();
  return t !== "" && t.length <= 12 && !PARTICLE.test(t) && !YOGEN_END.test(t);
}
// 行頭の格助詞＋体言。この行は前の行の名詞句を受けているので、前の行は文の途中なのだ
// （「株式会社　淀川に殴られる」＋「が爆誕するかも」）。
// 格助詞の直後を漢字・カタカナに限るのは「がんばる」のような語頭の仮名と区別するため
const LEADING_PARTICLE = /^[ \t　]*[がをにへ][一-龯々ァ-ヺ]/u;
// 空白で字下げされた行は引用・データの並び（bot のカード名など）
const INDENTED_LINE = /^[ 　][^\s]/u;
// タイトルと出典を記号で並べた行（「脱獄王 - ニコニコ動画」）。
// 空白で挟んだ区切り記号は日本語の文には現れない。
// ただし1行だけの投稿は「ぽわ / 2 = ぽか」のような本文そのものなので対象外にするのだ
const SEPARATOR_LINE = /[ \t　][-–—|｜/*+][ \t　]/u;
// 箇条書きの行（半角記号・中黒のどちらでも）
const BULLET_LINE = /^[ \t　]*(?:[-*+][ \t]|・)/u;

// 変換せずそのまま残す行を投稿全体から洗い出す。
// 行単位の手掛かり（前後の行との関係・字下げ・区切り記号）は
// 1文だけを見る zundaSentence では判断できないので、ここでまとめて集めるのだ
function linesToSkip(text) {
  const lines = text.split("\n");
  const skip = new Set();
  const body = lines.filter((l) => l.trim() !== "");
  // 材料・データの列挙ブロック（体言止めの短い行が3行以上続く範囲）
  const flags = lines.map(isListItemLine);
  let run = 0;
  for (let i = 0; i <= lines.length; i++) {
    if (i < lines.length && flags[i]) {
      run++;
      continue;
    }
    if (run >= 3) for (let k = i - run; k < i; k++) skip.add(lines[k]);
    run = 0;
  }
  // 行頭の引用句「という〜」は、その手前の行までを丸ごと名詞句にまとめる形なのだ
  // （「理論が必要か / 努力が必要か / という話」）。
  // まとめられた側は引用の中身であって文ではないので、語尾を接いではいけないのだ。
  // どこまで遡るかは空行と句点で区切るのだ。引用は段落や文をまたがないからなのだ
  for (let i = 1; i < lines.length; i++) {
    if (!/^[ \t　]*(?:という|っていう)/u.test(lines[i])) continue;
    for (let k = i - 1; k >= 0; k--) {
      if (lines[k].trim() === "" || /[。．！!？?]\s*$/u.test(lines[k])) break;
      skip.add(lines[k]);
    }
  }
  if (body.length < 2) return skip;
  for (let i = 0; i < lines.length; i++) {
    if (lines[i].trim() === "") continue;
    if (INDENTED_LINE.test(lines[i])) skip.add(lines[i]);
    if (SEPARATOR_LINE.test(lines[i])) skip.add(lines[i]);
    // 次の（空行を挟まない）行が格助詞で始まるなら、この行は文の途中
    const next = lines[i + 1];
    if (next !== undefined && LEADING_PARTICLE.test(next)) skip.add(lines[i]);
    // 箇条書きを導く行が助詞「で」で終わっていれば、文はそこで終わっていない
    // （「でも一方で」＋「- みんなが…」）。中止法を断定に戻すルールの誤爆を防ぐのだ
    if (next !== undefined && BULLET_LINE.test(next) && /で[\s]*$/u.test(lines[i]))
      skip.add(lines[i]);
  }
  return skip;
}

// 倒置。日本語は述語で言い切ったあとに主語・補語・副詞を後置できるのだ
// （「何個あるんだこれ」「どこですかここは」「動きはするんだよな一応」）。
// 後置される語は指示代名詞と一部の副詞だけで、これは閉じた類なのだ。
// 前半だけを文として変換し、後置部はそのまま残すのだ。
// 前半が述語の形（断定・丁寧・終助詞）で終わっていることを条件にするのは、
// 連体修飾（「言ってたあれ」＝「あれ」を修飾する節）と分けるためなのだ
const INVERSION =
  /^(.*(?:んだ|んです|のだ|です|ます|だ|[かよねな]))((?:これ|それ|あれ|ここ|そこ|あそこ)(?:は|が|も)?|一応|とりあえず|たぶん|多分)$/u;
// 後置されたのが副詞なら、前半が用言の終止形で終わっているだけで倒置と決まるのだ
// （「明日には存在忘れてる多分」→「忘れてるのだ多分」）。
// 上の INVERSION が前半に述語の形（断定・丁寧・終助詞）を求めているのは、
// 連体修飾（「言ってたあれ」＝「あれ」を修飾する節）と分けるためなのだ。
// 副詞は連体修飾を受けないので、その心配が要らないのだ。
// 「たぶん」を仮名で入れないのは、「使った分」「働いた分」のような
// 「〜た＋ぶん」と字形が同じで、そちらを倒置と読んでしまうからなのだ。
// ★ ここも語の列挙なのだ。上の IMPERATIVE_ADV と同じ理由で形の類にはできないのだ
// （日本語の副詞に形態の目印が無いのだ）。後置できるのは陳述副詞という閉じた類だが、
// 並んでいる3語のうち2語はテスト1件と1対1で、「とりあえず」はどのテストにも
// 対応しないのだ。列挙の長さは「出会った文の数」でしかないと承知して使うのだ。
// 足すときは仮名書きの形に気をつけるのだ。「多分」は漢字なら語として決まるが、
// 「たぶん」は上のとおり「〜た＋ぶん」と衝突するので入れられないのだ
const INVERSION_ADV = new RegExp(
  `^(.*${YOGEN})(一応|とりあえず|多分)$`,
  "u",
);

// 定型詩（俳句・川柳・短歌）は音数そのものが形式なのだ。語尾を足すと韻律が壊れ、
// 三行のうち一行だけに付けば構造も崩れるので、投稿ごと無変換にするのだ。
// ハッシュタグは作者自身が定型詩だと宣言した印なので、それだけで十分な手掛かりなのだ
const VERSE_TAG = /[#＃][ \t]*(?:n?575|haiku|senryu|senryuu|tanka)\b/iu;
// 日本語の呼び名は普通の文にも現れる（「TLでは俳句を詠むbotと議論した」）ので、
// 語だけでは足りないのだ。定型詩の体裁——三行以上に分かち書きされ、
// どの行も一句の長さ（最長7音）に収まっている——を併せて条件にするのだ
const VERSE_WORD = /(?:俳句|川柳|短歌|狂歌|都々逸)/u;
const VERSE_LINE_MAX = 12;
// 印も呼び名も無い定型詩は、体裁だけが手掛かりなのだ。
// 上句・中句・下句のちょうど三行に分かち書きされ、どの行も一句の長さに収まり、
// 句読点も感嘆符も打たれていない——この形をした散文はほとんど無いのだ
// （実測 3000件中 22件で、すべて俳句・川柳だったのだ）。
// 三行という条件を「以上」ではなく「ちょうど」にするのは、
// 箇条書きや連投の断片を巻き込まないためなのだ
const VERSE_SHAPE_MAX = 8;
const VERSE_PUNCT = /[。、，．！!？?…]/u;

// 日本語の文字（仮名・漢字・長音）。空白の両側がこれなら文の切れ目とみなす
const JP_CHAR = /[ぁ-ゖァ-ヺー々〆ヶ一-龯]/u;

// 日本語同士を挟む空白（半角・全角）で1行を文に切る。
// 「イヤだね 分散して…」のように句点の代わりに空白で文を並べる書き方に対応する。
// 「zundamstr も見て」「23 時」のようにラテン文字・数字が隣接する空白は
// 単なる語の区切りなので切らない。返り値は {body, gap} の配列で、gap は元の空白。
function splitByJapaneseSpace(s) {
  const segs = [];
  const re = /[ 　]+/gu;
  let start = 0;
  let m;
  while ((m = re.exec(s)) !== null) {
    const before = s[m.index - 1];
    const after = s[m.index + m[0].length];
    if (before && after && JP_CHAR.test(before) && JP_CHAR.test(after)) {
      segs.push({ body: s.slice(start, m.index), gap: m[0] });
      start = m.index + m[0].length;
    }
  }
  segs.push({ body: s.slice(start), gap: "" });
  return segs;
}

// 開いたままの括弧が残っているか（＝閉じ括弧を装飾として切り離したか）
function hasUnclosedBracket(s) {
  for (const [open, close] of BRACKETS) {
    let n = 0;
    for (const ch of s) {
      if (ch === open) n++;
      else if (ch === close) n--;
    }
    if (n > 0) return true;
  }
  return false;
}

// 話者ごとのキャラ語尾（「〜だよぷく」「〜てねぷく」）を、語彙を知らずに投稿から見つける。
// 未知の語尾は無限にあって列挙できないので、「同じ仮名列がその投稿の複数の文末に
// 繰り返し現れる」という事実だけを手掛かりにするのだ。
// 誤検出を避けるため、次の2つを両方満たすものだけをキャラ語尾とみなす:
//   (a) その文がどの ZUNDA_RULES にも当たらないこと
//       ＝既知の語尾なら「〜ないよ」「〜ですね」のように普通に処理できるので対象外
//   (b) 終助詞・断定の直後に付いていること
//       ＝キャラ語尾は文法的な文末の「後ろ」に足されるもので、
//         「〜を勉強する」の「する」のような述語そのものとはここで区別できるのだ
// 「な」は連体形の「な」（「そんなわけ」「〜ない」）と紛れるので目印に使わないのだ
const SFP_ANCHOR = "(?:だ|です|ます|みたい|[ねよわぞぜ])";
// 語尾そのものが普通の述語・助動詞であるものは、繰り返されても語尾ではないのだ
const PLAIN_ENDING = /^(?:のだ|なのだ|です|ます|ない|いる|ある|する|くる|した|など|から|けど|ので|のに)$/u;
function detectCharSuffix(text) {
  const sents = text
    .split(/[\n。．！!？?]/)
    .map((t) => t.trim())
    .filter((t) => t !== "");
  if (sents.length < 3) return ""; // 偶然の一致を避けるため短い投稿には使わない
  const counts = new Map();
  const anchored = new Set();
  for (const sent of sents) {
    const m = sent.match(DECOR_TAIL);
    let core = m ? sent.slice(0, sent.length - m[0].length) : sent;
    core = core.replace(/([ぁ-ゖ])ー+$/u, "$1");
    if (!core) continue;
    if (ZUNDA_RULES.some(([re]) => re.test(core))) continue; // (a)
    // 1文字の語尾は見ない。「訴えられない」の「い」のように活用の一部を
    // 語尾と誤認して語を食ってしまうからなのだ（キャラ語尾は必ず2文字以上ある）
    for (let n = 2; n <= 3 && core.length > n; n++) {
      const suf = core.slice(-n);
      if (!/^[ぁ-ゖァ-ヺ]+$/u.test(suf)) continue;
      counts.set(suf, (counts.get(suf) ?? 0) + 1);
      if (new RegExp(SFP_ANCHOR + suf + "$", "u").test(core)) anchored.add(suf); // (b)
    }
  }
  let best = "";
  for (const [suf, n] of counts)
    if (n >= 2 && anchored.has(suf) && !PLAIN_ENDING.test(suf) && suf.length > best.length)
      best = suf;
  return best;
}

// quoted = 歌詞・CM などの引用ブロック内の行。ルールに当たらない体言止めは触らない。
// 空白区切りの手前の文（＝文末とは限らない断片）にも同じ控えめな扱いを使う
function zundaSentence(raw, quoted = false, opts = {}) {
  // --- 変換しない行（誤変換より無変換のほうがよい） ---
  if (/^[\s]*[🎵🎶♪♫♬]/u.test(raw)) return raw; // 音符で始まる歌詞行
  if (/^　/.test(raw)) return raw; // 全角スペース字下げは歌詞・引用
  // 自分の文と併記された「>」の引用行は他人の発言なので触らない
  if (opts.partialQuote && QUOTE_LINE.test(raw)) return raw;
  if (COMMA_END.test(raw)) return raw; // 読点で終わる行は述語が次の行に続く
  // 格助詞で始まる行は前の行から続く一つの文の後半なのだ
  // （「…- 納品物を受け取る」＋「が自然そう」）。
  // 前の行のほうは LEADING_PARTICLE で無変換にしてあるが、この行は違うのだ。
  // 述語はこちらの行にあって文はここで終わっているので、変換するのが正しいのだ
  // （「②感じよく返す」＋「が難しいかも」→「が難しいかもしれないのだ」）
  if (HEADING_MARK.test(raw)) return raw; // 「■ 流速計測」等の見出しラベル行
  // 括弧で丸ごと囲まれた行は見出し・ラベルのことが多い（「【お知らせ】」「(閲覧注意)」）。
  // ただし中身が用言で言い切られていれば、それは括弧に入れた1つの文なのだ
  // （「(蛍光灯買いに行ってない)」）。中身だけを文として変換して括弧を戻すのだ。
  // 見出し・ラベルは体言止めなので、この条件で分かれるのだ
  const wrapped = raw.match(/^(\s*[[［【（(])([^\]］】）)]+)([\]］】）)]\s*)$/u);
  if (wrapped) {
    if (!/[うくぐすずつぬぶむるいた]$/u.test(wrapped[2])) return raw;
    const inner = zundaSentence(wrapped[2], quoted, opts);
    return inner === wrapped[2] ? raw : wrapped[1] + inner + wrapped[3];
  }
  if (/^\s*[[［【（(].*[\]］】）)]\s*$/u.test(raw)) return raw; // 括弧だけの見出し・ラベル行
  if (/([ぁ-ゖァ-ヺ])\1\1/u.test(raw)) return raw; // 同じ仮名の3連続は擬音・叫び
  // 1モーラを伸ばして1音で閉じただけの語は感動詞（「うーむ」「ふーん」「あーあ」）。
  // 語幹と言えるものが1文字しかなく、品詞を決める手がかりが無いのだ
  if (/^[ぁ-ゖ][ー〜～]+[ぁ-ゖ]$/u.test(raw.trim())) return raw;
  // 2〜3文字のまとまりが3回以上繰り返される行は擬音（「のすのすのすのす」）。
  // 意味のある語がこの形で3回続くことはないのだ
  if (/^([ぁ-ゖァ-ヺ]{2,3})\1{2,}$/u.test(raw.trim())) return raw;
  if (GREETING.test(raw.trim())) return raw; // 挨拶はそのまま
  if (SHORT_ELONGATED.test(raw.trim())) return raw; // 引き伸ばしただけの短い語はそのまま
  // 波ダッシュを語中に含む短いひらがなの断片は擬音（「うにょ〜ん」「ぷわ〜ん」）。
  // 長音符「ー」は「うまかったー」「ノーマン」のように語の一部でもあるので、
  // ここでは波ダッシュだけを手掛かりにするのだ
  if (/^[ぁ-ゖ][ぁ-ゖー〜～]{0,5}$/u.test(raw.trim()) && /[〜～]/u.test(raw))
    return raw;
  // 1〜2文字のひらがなだけの文は擬音・掛け声（「ぴ」「にゃ」）
  if (/^[ぁ-ゖ]{1,2}$/u.test(raw.trim())) return raw;
  // 促音「っ」は語頭に立てない音なので、「っ」で始まる短い仮名の行は
  // 語の頭を削って勢いだけを残した掛け声なのだ（「っしゃ！」＝「よっしゃ」）。
  // 元の語が復元できないうえ、感動詞には述語が無いので触らないのだ。
  // 長さで区切るのは、引用の「って」で始まる文（「って性質がある」）が
  // 同じ形をしていて、そちらには普通の述語があるからなのだ
  if (/^っ[ぁ-ゖァ-ヺー]{0,3}$/u.test(raw.trim())) return raw;
  // 半角記号の箇条書きは体言止めの断片が多いので控えめに扱う
  if (ASCII_BULLET.test(raw)) quoted = true;
  // 行単位の手掛かりで「文ではない」と分かった行はそのまま残す
  // （列挙ブロック・字下げ・区切り記号の行・次行が格助詞で始まる行）
  if (opts.skipLines && opts.skipLines.has(raw)) return raw;

  // 読点の前が丁寧語で終わっていれば、そこは文の切れ目なので先に常体へ直してから
  // 残りを処理する（「ねます、おやすみ〜」→「ねるのだ、おやすみなのだ〜」）。
  // 丁寧語に限るのは、「ロボからすると、」「そうそう、」のような普通の読点まで
  // 文末とみなすと、節の途中で語尾が付いて文が壊れるからなのだ
  // 疑問の「か」を伴う丁寧形（「〜ますか、」）も同じ文の切れ目なのだ
  const pol = raw.match(
    /^([^、，\n]*?(?:です|ます|ました|ません|でした)[かねよ]{0,2})([、，])/u,
  );
  if (pol) {
    const head = zundaSentence(pol[1], quoted, opts);
    if (head !== pol[1]) {
      // 疑問形に開いた節の直後の読点は「のだ？、」と記号が重なるので落とす
      const sep = /[？?]$/u.test(head) ? "" : pol[2];
      return zundaSentence(head + sep + raw.slice(pol[0].length), quoted, opts);
    }
  }

  // 日本語同士を挟む空白は句点の代わりなので、そこで区切って文ごとに変換する。
  // 手前の文は quoted 扱い（ルールに当たった時だけ変換）にして、
  // 「明日 東京に行く」の「明日」に語尾が付くような行き過ぎを防ぐ。
  const segs = splitByJapaneseSpace(raw);
  if (segs.length > 1) {
    return segs
      .map(
        (seg, k) =>
          zundaSentence(
            seg.body,
            k < segs.length - 1 ? true : quoted,
            opts,
          ) +
          seg.gap,
      )
      .join("");
  }

  // 末尾の注記（対応の取れた括弧）を装飾として切り離す
  let note = "";
  let s = raw;
  const nm = s.match(TRAILING_NOTE);
  if (nm) {
    note = nm[0];
    s = s.slice(0, s.length - note.length);
    // 鉤括弧の直前に立つ語は話者の名前なのだ（「ぼく「はい……」」「宇和「〜」」）。
    // 台本形式の投稿でよく使われる書き方で、名前は述語ではないから
    // 「ぼくのだ「はい……」」のように語尾を接いではいけないのだ。
    // 括弧の中の台詞は別の文として扱われるので、ここで返しても取りこぼさないのだ
    if (/^[「『]/u.test(note) && s.trim() !== "") return raw;
  }
  // 末尾の装飾を切り離してから語尾を変換し、装飾を戻す
  const m = s.match(DECOR_TAIL);
  let decorSym = m ? m[0] : "";
  let core = decorSym ? s.slice(0, s.length - decorSym.length) : s;
  if (!core) return raw; // 日本語コンテンツが無い行はそのまま
  // 日本語に直に続く英数字は語の一部なので本文に戻す（「手仕込みUDP」「衣80%」）。
  // 切り離したままだと語尾が語の途中に入って「手仕込みなのだUDP」になるのだ。
  // 「おもしろいw」の笑いと「忘れたorz」の顔文字は語ではないので対象外にする
  if (/^[A-Za-z0-9%％]+$/u.test(decorSym) && !FACE_LETTERS.test(decorSym) &&
      JP_CHAR.test(core[core.length - 1])) {
    core += decorSym;
    decorSym = "";
  }
  if (ONOMATOPOEIA.test(core)) return raw; // 引き伸ばした擬音はそのまま
  // --- 母音の引き伸ばしを剥がす（語尾の照合の前に一度だけ） ---
  // 剥がしてよいかの判定は規則表そのものに問うのだ（applyTailRules）。
  // 「引き伸ばしを落とした形の末尾は、規則表が知っている文末の語尾か」——
  // これは丁寧形を常体に直したあとで relayTail が問うているのとまったく同じ問いなのだ。
  // 語尾の在庫は規則表が持っているのだから、剥がす側が別の在庫表を抱えてはいけないのだ。
  // 承認版はここに STRETCH_RESTORABLE / STRETCH_SFP という規則表と並行する
  // 2つ目の在庫表を持っていて、そこに「〜んだけど(ね)」「〜んだよな」が
  // 載っていなかったのだ。規則表のほうは「〜んだけどね」も「〜んだよな」も
  // 正しく畳めるのに、剥がす側が知らないので規則まで届いていなかったのだ。
  // 規則が答えなければ（番人に当たった時も含む）その語は同定できていないので剥がさないのだ
  let smallTail = "";
  let stretchBase = "";
  let stretchCore = "";
  if (STRETCH_TAIL.test(core)) {
    const bare = core.replace(/[ぁぃぅぇぉ]+$/u, "");
    // 小書きの母音仮名は語の一部になれない字なので、剥がした形を規則表が
    // 同定できないなら、その語はもう復元できないのだ（「たのしぃ」「たけぇ」）。
    // 誤変換より無変換のほうがよいので、行ごと原文に戻すのだ
    if (!bare || applyTailRules(bare) === null) return raw;
    smallTail = core.slice(bare.length);
    // 引き伸ばしは直前の1字の母音を伸ばした印なのだ。その1字と、剥がした形を
    // 覚えておく。出力にその1字が最後の音として残っていれば飾りとして戻し
    // （「〜のだけどぉ」）、終助詞ごと「のだ」に畳まれて消えていれば
    // 一緒に落とすのだ（下の dec）
    stretchBase = bare[bare.length - 1];
    stretchCore = bare;
    core = bare;
  } else if (LONG_VOWEL_TAIL.test(core)) {
    // 等大の母音仮名のほうは、引き伸ばしの印か語の一部かが字形では決まらないのだ
    // （「なあ」は引き伸ばし、「ええ」は感動詞、「十（とお）」は体言）。
    // だから剥がすのは仮説にとどめて、規則表が答えなければ
    // 原文のまま下の処理に流すのだ（小書き仮名と違って行を捨てはしないのだ）
    const bare = core.replace(/あ+$/u, "");
    if (bare.length > 1 && applyTailRules(bare) !== null) {
      smallTail = core.slice(bare.length);
      stretchBase = bare[bare.length - 1];
      stretchCore = bare;
      core = bare;
    }
  }
  const decor = smallTail + decorSym + note;
  // 引き伸ばしの母音仮名は、伸ばしている1字が出力の最後の音として残っている時だけ
  // 戻すのだ。「〜んですかぁ」の「ぁ」は「か」を伸ばした印なので、「か」が「のだ？」に
  // 畳まれて消えたなら一緒に落とすのだ（「〜のだ？ぁ」という宙に浮いた形を防ぐ）。
  // 「〜ですけどぉ」は「ど」が「のだけど」に残るので、飾りとしてそのまま戻すのだ。
  // ★ 規則が末尾を書き換えず後ろに接いだだけのとき（＝答えが剥がした形で始まるとき）は
  // 戻さないのだ。伸ばされていた1字は語中に移っていて、行末に来ているのは
  // 語尾の「のだ」の側の字だからなのだ。字だけを見て戻すと、書き手が伸ばしてもいない
  // 音に印が付くのだ（「まだぁ」→「まだ」＋「なのだ」で末尾がまた「だ」になり、
  // 「まだなのだぁ」と断定の「だ」を伸ばした形になってしまう）。
  // 規則に当たらず原文のまま返すとき（conv === stretchCore）は、
  // 伸ばされた1字が末尾のままなので戻すのだ（「寝ろこぶねぇ」）
  const dec = (conv) =>
    conv +
    (smallTail &&
    (!conv.endsWith(stretchBase) ||
      (conv !== stretchCore && conv.startsWith(stretchCore)))
      ? ""
      : smallTail) +
    decorSym +
    note;

  // 「ラベル: 値」形式のデータ行（bot の集計・計測ログ）は表を壊すので変換しない
  if (/[:：]/.test(decor)) return raw;
  // 本文の後ろに「演算子＋数字」が続く行は数式・箇条書き風の断片（「らん漫 * 2」）。
  // ここに語尾を挿し込むと式が分断されるのだ。
  // 「らんまん * 4 = らん漫」のように本文が行末に来る形は装飾が空なので影響しない
  if (/^[ \t　]*[-+*/=×÷][ \t　]*[0-9０-９]/u.test(decor)) return raw;
  // 括弧の内側に語尾を挿し込まない
  if (hasUnclosedBracket(core)) return raw;
  // 感動詞・掛け声はそのまま
  if (INTERJECTION.test(core.trim())) return raw;
  // 注記や記号を外したら挨拶だけが残る行はそのまま（「おはようございますのすし(￣^￣)ゞ」）
  if (GREETING.test(core.trim())) return raw;

  // ひらがな＋長音で引き伸ばした感動詞・形容動詞語幹（「いやー」「やだー」）は
  // 長音を落としてから語尾を付ける（「いやーなのだ」の語尾衝突を防ぐ）。
  // 「コーヒー」「インイヤー」のようなカタカナ語の長音は語の一部なので落とさない。
  const stretched = /[ぁ-ゖ]ー+$/u.test(core);
  core = core.replace(/([ぁ-ゖ])ー+$/u, "$1");

  // この投稿の話者のキャラ語尾が付いていれば、その直前の終助詞ごと落としてから
  // 通常の変換にかける（「みたいぷく」→「みたいなのだ」）
  let charStripped = false;
  if (opts.charSuffix && core.length > opts.charSuffix.length &&
      core.endsWith(opts.charSuffix)) {
    const bare = core.slice(0, -opts.charSuffix.length).replace(/[ねよなわぞぜ]$/u, "");
    if (bare) {
      core = bare;
      charStripped = true;
    }
  }

  // 倒置は前半だけを文として変換するのだ。前半が規則に当たらなければ倒置ではないので
  // （「犯人は俺」の「俺」は後置ではなく述語なのだ）、その時は何もしない
  const inv = core.match(INVERSION);
  if (inv) {
    const head = zundaSentence(inv[1], true, opts);
    if (head !== inv[1]) return dec(head + inv[2]);
  }
  // 後置された副詞の場合は、前半が用言の終止形で終わっていることが分かっているので
  // 1つの文としてそのまま変換してよいのだ（quoted に落として控えめにする必要が無い）
  const invAdv = core.match(INVERSION_ADV);
  if (invAdv) {
    const head = zundaSentence(invAdv[1], quoted, opts);
    if (head !== invAdv[1]) return dec(head + invAdv[2]);
  }

  for (const [re, rep, finalOnly] of ZUNDA_RULES) {
    // ★ 第3要素の "final" は「文末だと分かっている行でだけ効かせる」印なのだ。
    // 依頼のテ形（「教えて」）と中止法のテ形（「名付けて さくらスクリプト」）は
    // 語形がまったく同じで、分かれ目は「そこで文が終わっているか」だけなのだ。
    // quoted は「文末とは限らない断片」（空白区切りの手前・引用ブロック内・
    // 箇条書きの断片）に立つ印なので、そのまま使えるのだ
    // さらに、句読点なしの改行で終わっていて後ろにまだ本文が続く行も
    // 文の途中なのだ（「テーブルの真ん中に電子レンジを置いて」＋「各自食べたい…」）。
    // 書き手が「。」を打った行（「体調には気をつけて。」）は文がそこで終わっている
    // という書き手自身の印なので、そちらは依頼として開くのだ。
    // 読点で終わる行を無変換にする COMMA_END とまったく同じ理屈なのだ
    if (finalOnly === "final" && (quoted || opts.midSentence)) continue;
    if (!re.test(core)) continue;
    const conv = core.replace(re, rep);
    // 置換関数が RULE_PASS を返したら、その規則は字形では当たったが
    // 活用表に問うと当てはまらなかったということなのだ。番人（打ち切り）ではなく
    // 「次の規則に任せる」なので、当たらなかったものとして流すのだ
    if (conv.includes(RULE_PASS)) continue;
    // 置換しても文字列が変わらないルールは「この文は変換しない」という番人なのだ。
    // 変換しないと決めたのに、引き伸ばしの長音だけ削った形を返すのは
    // 変換でも原文保持でもない中途半端な出力なのだ（「たべちゃおっかなー！」の「ー」）。
    // 長音を剥がしていたのなら原文をそのまま返すのだ。
    // キャラ語尾（「〜だよぷく」）はこの投稿の話者の癖だと分かっているので剥がしたままにする
    if (conv === core) return stretched && !charStripped ? raw : dec(core);
    // 波ダッシュが3つ以上続く末尾は引き伸ばした叫び・感嘆なのだ（「ヨカね～～～♪」）。
    // 記号なので装飾として切り離されるが、切り離した先の1字は語の一部ではなく
    // 引き伸ばされた音そのものなのだ。その1字を削る変換をすると引き伸ばしだけが
    // 宙に浮いて「ヨカなのだ～～～♪」と語中へ割り込んだ形になるのだ。
    // 3つ以上に限るのは、下の「長音符が3つ以上続く語は引き伸ばした叫び」と
    // 同じ線引きなのだ。1つだけの「〜」は語尾に添えた飾りで
    // （「明日だ〜」「食べちゃうぞ〜」）、終助詞・断定を畳んでよいのだ。
    // 丁寧語（「そうですね〜〜〜」）と用言＋終助詞（「すごいね〜〜〜」）は
    // 引き伸ばす前の語尾が一意に決まるので、3つ以上でも畳んでよいのだ
    if (
      /^[〜～]{3,}/u.test(decorSym) &&
      !conv.startsWith(core) &&
      !STRETCH_RESTORABLE.test(core) &&
      !STRETCH_SFP.test(core)
    )
      return raw;
    // 長音で引き伸ばした文末は詠嘆・納得であって問いかけではないのだ
    // （「簡単なのかー」「売ってないのかなー」）。引き伸ばしは相手の返事を待つ形ではなく、
    // 自分で噛みしめる言い方だからなのだ。
    // 疑問符を付けるかどうかは原文の句読点に委ねる、というこの表の方針そのものなのだ。
    // 書き手は「？」ではなく「ー」を選んだので、こちらで疑問符を足さないのだ
    if (stretched && /[？?]$/u.test(conv)) return dec(conv.slice(0, -1));
    return dec(conv);
  }
  // 引用ブロック内でルール非該当の行は歌詞の一節・商品名・擬音なので触らない
  // （「名物かまど」→「名物かまどなのだ」「テロッテ～ン♪」の破壊を防ぐ）。
  // ただし見出し記号で始まる bot の定型投稿だけは、守りたいのがラベル・数値の
  // 体言止めの行なので、用言で言い切っている行は本文として下で変換するのだ
  if (quoted && !opts.botHeading) return raw;
  // ルール非該当時は末尾の文字種で出し分ける
  // 「つ」は漢字の直後だけ用言とみなす（「打つ」は動詞だが「やつ」「星2つ」は体言）
  // 拗音の直後の「う」は、ワ行五段の語幹表に載っている時だけ活用語尾なのだ。
  // 載っていれば「〜てしまう」の口語形（「食べちゃう」。表に「ちゃ」「じゃ」がある）、
  // 載っていなければ「う」までで1語の体言なのだ（「うにゅう」「らいしゅう」）
  if (
    /[一-龯々]つ$|[くぐすずぬふぶむるいた]$/u.test(core) ||
    (/う$/u.test(core) &&
      (!/[ゃゅょ]う$/u.test(core) || isGodan("い", core.length - 1, core)))
  )
    return dec(core + "のだ"); // 用言の終止形
  // 口語否定の「ん」（＝「ぬ」）は未然形に付くのだ。段と語幹表で決まる問いなので
  // 1つの述語にまとめてあるのだ（isColloquialN。上の「〜んか」の番人と同じものなのだ）
  if (isColloquialN(core)) return dec(core + "のだ");
  if (quoted) return raw; // bot の定型投稿に残った体言止めのラベル行
  // 長音を落とした形がえ段（命令形・仮定形・一段の活用語尾）や終助詞で終わるなら、
  // それは体言ではなく活用の途中・文末の飾りなのだ（「動けねー」「おはよー」
  // 「いそげいそげー」）。ここまでの規則にも用言の終止形にも当たらなかった以上、
  // 元の活用は復元できないので「なのだ」を付けずに無変換にする。
  // 引き伸ばした形容動詞語幹（「いやー」→「いや」）は や段・あ段で終わるので影響しない。
  // ★ お段も同じなのだ。上の規則には既に「意向形・様態の『〜おう』は活用を復元できないので
  // 触らない」という番人があるのに（「行こう」「しよう」「ありがとう」）、
  // その番人が引き伸ばした形「〜おー」まで届いていなかったのだ。
  // 引き伸ばしは「う」と同じ音を表しているだけで、語としては同じものなのだ
  // （「行こー」＝「行こう」「ましょー」＝「ましょう」）。届いていないせいで
  // 長音だけが削られて「行こなのだ」「ましょなのだ」と語が欠けていたのだ。
  // 拗音の「ょ」も同じお段なので入れるのだ（「どっこいしょー」「よいしょー」）
  if (stretched && /[えけげせぜてでねへべめれよわなおこごそぞとどのほぼもろょ]$/u.test(core))
    return raw;
  // 長音符が3つ以上続く語は引き伸ばした叫び・感嘆（「あーーー」「えーーーん」）。
  // 実在の語にこの形は無く、伸ばす前の語形も復元できないので体言扱いにしないのだ
  // （「みれなーーーい」のように用言の終止形で終わる形は上で変換済み）。
  // ただし見るのは末尾の語だけなのだ。行のどこかに引き伸ばしがあるだけで文全体の
  // 変換をやめると、後ろに続く別の語まで巻き添えになる
  // （「はあーーーー、、、うんち」「う〜〜〜〜バイト」の「うんち」「バイト」）。
  // 引き伸ばしを閉じる1〜2字の仮名（「えーーーん」の「ん」）は同じ語の一部なのだ
  if (/[ー〜～]{3,}[ぁ-ゖ]{0,2}$/u.test(core)) return raw;
  // 音符で終わる体言止めの行は歌詞・CM・時報の擬音なので触らない
  // （「ポォ～ン♪」→「ポォ～ンなのだ♪」の破壊を防ぐ。「楽しかった♪」は上の用言で変換済み）
  if (NOTE_TAIL.test(raw)) return raw;
  // 末尾に URL が付く行は共有・告知の定型行で、本文は作品名や見出しのことが多い
  // （「荒野の七人／真昼の決闘 https://…」）。
  // 末尾に括弧の注記が付く行の本文も、作品名や形態名のことが多い
  // （「ゆうひかげ(じょうもんのすがた)」）。
  // どちらも用言で終わる普通の文は上で変換済みなので、残った体言止めには付けないのだ
  if (decor.includes(URL_MARK) || note) return raw;
  // 日本語に英数字が続く語（「手仕込みUDP」「衣80%」）は体言扱い
  if (/[A-Za-z0-9%％]$/u.test(core) && JP_CHAR.test(core))
    return dec(core + "なのだ");
  if (/[ぁ-ゖ]$/u.test(core)) return dec(core + "なのだ"); // その他の仮名は体言扱い
  if (/[一-龯々ァ-ヺーゝゞ]$/u.test(core)) return dec(core + "なのだ"); // 漢字・カタカナ（体言）
  return dec(core); // それ以外はそのまま
}

function zundamonize(text) {
  // 投稿全体が助詞で始まる短い断片なら、前の投稿の続きなので触らない
  if (FRAGMENT_POST.test(text.trim())) return text;
  // 投稿全体がひらがなだけの短い語なら、挨拶・造語・擬音（「おはのす」「ぴ」）。
  // 挨拶を語彙リストで数え上げるとキリがないので、長さで一般に逃がすのだ
  const short = text.trim();
  if (/^[ぁ-ゖ]{1,4}$/u.test(short) &&
      !isShortPolite(short) &&
      !SHORT_PAST.test(short) &&
      !(SHORT_N_NOUN.test(short) && !AMBIGUOUS_N.test(short)))
    return text;
  // 現代日本語の正書法は漢字仮名交じりで、助詞も送り仮名も仮名で書く。
  // 表意文字がこれだけ並んでいて仮名が1文字も無い投稿には、語尾を接ぎ木する
  // 相手（日本語の述語）が無いのでそのまま返すのだ。
  // 中国語の投稿がここに落ちるが、漢文調の日本語（「〜願上候」）も同じく無変換になる。
  // どちらも仮名の活用語尾が無く、機械的に語尾を差し替える手掛かりが無いのだ
  if (!/[ぁ-ゖァ-ヺ]/u.test(text) &&
      (text.match(/[一-龯々]/gu) ?? []).length >= 12) return text;
  // 濁点を1字ずつに付けて回った投稿は、語ではなく字面そのものが遊びなのだ
  // （「め゛う゛の゛お゛尻゛に゛…」）。濁点は語の切れ目を無視して打たれているので、
  // どこが文末なのかを決められず、語尾を挿すと文字列を分断してしまうのだ。
  // 普通の日本語で単独の濁点が3つ以上出ることはないのだ
  if ((text.match(/[゛゙]/gu) ?? []).length >= 3) return text;

  // 定型詩は音数が形式そのものなので、語尾を接ぎ木すると詩でなくなるのだ。
  // 詩の本体を数えるときは、URL・nostr参照・ハッシュタグの行を除くのだ。
  // 引用の nevent や作者のタグは詩の一部ではないので、
  // 入れたままだと行数も字数も条件から外れてしまうのだ
  if (VERSE_TAG.test(text)) return text;
  const vl = text
    .split("\n")
    .map((l) => l.replace(/https?:\/\/\S+|nostr:\S+|[#＃]\S+/gu, "").trim())
    .filter((l) => l !== "");
  if (VERSE_WORD.test(text)) {
    if (vl.length >= 3 && vl.every((l) => [...l].length <= VERSE_LINE_MAX))
      return text;
  }
  // 印も呼び名も無い定型詩は、三行の体裁そのものを手掛かりにするのだ。
  // ただし引用句「という〜」で締めくくられた三行（「理論が必要か / 努力が必要か /
  // という話」）は、行を分けて書いた散文の引用なので除くのだ。
  // 定型詩の下句が引用句で始まることはないのだ
  if (
    vl.length === 3 &&
    vl.every((l) => [...l].length <= VERSE_SHAPE_MAX) &&
    !vl.some((l) => /^(?:という|っていう)/u.test(l)) &&
    !VERSE_PUNCT.test(vl.join(""))
  )
    return text;


  // 音符で始まる行（歌詞・CM）か、見出し行（bot の定型投稿）が1行でもあれば、
  // 投稿全体を引用ブロックとみなす。
  // 引用中は用言・丁寧語の行だけ変換し、体言止めの行はそのまま残す。
  const lyric = LYRIC_LINE.test(text);
  const botHeading = !lyric && BOT_HEADING.test(text);
  const quoted = lyric || botHeading;

  // URL とハッシュタグは変換から保護する（タグ文字列を壊さないため）
  const kept = [];
  const hold = (mark) => (m) => {
    kept.push(m);
    return mark + (kept.length - 1) + mark;
  };
  let masked = text.replace(/https?:\/\/\S+/g, hold(URL_MARK));
  masked = masked.replace(
    /(^|[\s（(【「])([#＃][^\s#＃]+)/gu,
    (_m, pre, tag) => pre + hold(TAG_MARK)(tag),
  );

  // 材料・データの列挙ブロックに属する行を先に洗い出しておく。
  // 下の分割はマスク後の文字列を渡すので、こちらもマスク後で数えるのだ
  const skipLines = linesToSkip(masked);
  const charSuffix = detectCharSuffix(masked);
  // 引用行と自分の文が混在しているか（＝引用を保護すべきか）
  const bodyLines = masked.split("\n").filter((l) => l.trim() !== "");
  const quoteCount = bodyLines.filter((l) => QUOTE_LINE.test(l)).length;
  const partialQuote = quoteCount > 0 && quoteCount < bodyLines.length;

  // 文単位で分割（句読点・改行を区切りとして保持）し、各文を全部変換する
  // 全角ピリオド「．」を句点として使う書き手もいるので区切りに入れる。
  // 絵文字の「❓」「❗」も感嘆符・疑問符として文末に置かれるので同じ区切りにするのだ。
  // ただし直後に引用の「って」「と」が続く「❗って言われて」は文の途中で、
  // 記号は引用された台詞の中身なのだ。ここで切ると「クビなのだ❗って言われて」と
  // 文の途中に語尾が入ってしまうので、その時だけ区切らない
  // （異体字セレクタ U+FE0F は「❗️」のように記号の直後に付くので一緒に見るのだ）
  const parts = masked.split(
    // 同じことが普通の感嘆符・疑問符でも起きるのだ。引用句「という」が続く
    // 「フライドポテト！というツイート」の「！」は引用された台詞の中の記号で、
    // 文の終わりではないのだ。ここで切ると引用句の途中に語尾が入ってしまう。
    // 「という」だけに限って「って」を入れないのは、「〜！って言われた」の形では
    // 引用された台詞そのものを変換するほうが自然だからなのだ。
    // 「という」の後ろに来るのは体言（「というツイート」「という話」）で、
    // 台詞ではなく引用の中身をまるごと名詞句にする形だから扱いが違うのだ
    /(\n|。|．|[！!？?](?!という)|[❓❗]\uFE0F?(?!\uFE0F?(?:って|と)))/u,
  );
  let out = "";
  for (let i = 0; i < parts.length; i += 2) {
    const body = parts[i] ?? "";
    const delim = parts[i + 1] ?? "";
    if (body.trim() === "") {
      out += body + delim;
      continue;
    }
    // この断片のあとに本文がまだ続くか。続いていて、しかも区切りが
    // 句読点ではなく素の改行なら、文はこの行で終わっていないのだ
    const moreAfter = parts.slice(i + 2).some((p) => (p ?? "").trim() !== "");
    const midSentence = moreAfter && /^\s*\n\s*$/u.test(delim);
    let conv = zundaSentence(body, quoted, {
      skipLines, partialQuote, charSuffix, botHeading, midSentence,
    });
    let d = delim;
    // 「〜か。」を疑問化すると「〜のだ？。」と終端記号が重なるので、
    // 変換後が疑問符で終わるなら区切りの句点・疑問符を落とす
    if (/[？?]$/.test(conv) && /^[。？?]$/.test(d)) d = "";
    // 書き手が感嘆符で閉じた文は問いかけではないのだ（「今日地震あったのかーーー！」）。
    // 「か」を疑問と読んで付けた疑問符のほうを落として、原文の感嘆符に譲るのだ。
    // 疑問符を付けるかどうかは原文の句読点に委ねる、という方針そのものなのだ。
    //
    // 「元気ですか！」のように引き伸ばしの無い「か」＋「！」も同じ扱いにするのだ。
    // 詠嘆（「あったのかーーー！」）だけに絞って「元気ですか！」には疑問符を残す案も
    // あるが、残すと「元気なのだ？！」という重ね打ちになるのだ。
    // どちらが正しいかは原文からは決まらないのだ。「元気ですか！」は問いかけにも
    // 呼びかけにも読めて、書き手が「？」ではなく「！」を選んだという事実だけが
    // 手掛かりなのだ。そこで、句読点は書き手のものだという上の方針を通して
    // 感嘆符の側に一本化するのだ（実データでの証拠は詠嘆の1件だけで、
    // 「か」＋「！」を分ける根拠は無いのだ）
    else if (/[？?]$/.test(conv) && /^[！!]$/.test(d)) conv = conv.slice(0, -1);
    out += conv + d;
  }

  // URL・ハッシュタグを復元
  return out.replace(
    new RegExp(`[${URL_MARK}${TAG_MARK}](\\d+)[${URL_MARK}${TAG_MARK}]`, "g"),
    (_, i) => kept[Number(i)],
  );
}

export { zundamonize, zundaSentence, ZUNDA_RULES };
